function OpsDashboardRoute() {
  return <OpsDashboard />;
}

function OpsDashboard() {
  const location = useLocation();
  const routeSection = sectionFromPathname(location.pathname);
  const section = routeSection ?? "overview";
  const setSection = useCallback((target: Section, options?: { replace?: boolean }) => {
    void router.navigate({
      to: pathForSection(target) as never,
      replace: options?.replace,
    });
  }, []);
  const [admin, setAdmin] = useState(() => ({
    name: getAdminName(),
    email: getAdminEmail(),
    password: "",
  }));
  const [sessionActor, setSessionActor] = useState<AdminSession["actor"] | null>(null);
  const [authChecked, setAuthChecked] = useState(!getAdminToken());
  const [loginError, setLoginError] = useState("");
  const [loginPending, setLoginPending] = useState(false);
  const [forgotMode, setForgotMode] = useState<"hidden" | "email" | "otp">("hidden");
  const [forgotEmail, setForgotEmail] = useState("");
  const [forgotOtp, setForgotOtp] = useState("");
  const [forgotNewPassword, setForgotNewPassword] = useState("");
  const [forgotMessage, setForgotMessage] = useState("");
  const [forgotPending, setForgotPending] = useState(false);
  const [googleSsoEnabled, setGoogleSsoEnabled] = useState(false);

  useEffect(() => {
    syncRouteMetadata(routeSection);
    if (!routeSection) setSection("overview", { replace: true });
  }, [routeSection, setSection]);

  // Capture token from a Google SSO callback redirect (`#sso=token=...&name=...&email=...`)
  // before the auth-check effect runs. Runs synchronously during this render.
  useEffect(() => {
    const hash = window.location.hash || "";
    if (hash.startsWith("#sso=")) {
      const params = new URLSearchParams(hash.slice(5));
      const token = params.get("token");
      const name = params.get("name") ?? "Admin";
      const email = params.get("email") ?? "";
      window.history.replaceState(null, "", window.location.pathname + window.location.search);
      if (token) {
        setAdminToken(token);
        setAdminName(name);
        setAdminEmail(email);
      }
    } else if (hash.startsWith("#sso_error=")) {
      const message = decodeURIComponent(hash.slice("#sso_error=".length));
      window.history.replaceState(null, "", window.location.pathname + window.location.search);
      setLoginError(message);
    }
  }, []);

  useEffect(() => {
    void (async () => {
      const res = await getAuthConfig();
      if (res.ok) setGoogleSsoEnabled(!!res.data.google?.enabled);
    })();
  }, []);

  useEffect(() => {
    const token = getAdminToken();
    if (!token) {
      setAuthChecked(true);
      return;
    }

    void (async () => {
      const session = await getAdminSession();
      if (!session.ok || !session.data.actor) {
        clearAdminSession();
        setSessionActor(null);
        setLoginError(session.data.error ?? "Your admin session has expired.");
        setAuthChecked(true);
        return;
      }
      setAdminName(session.data.actor.name);
      setAdminEmail(session.data.actor.email ?? "");
      setSessionActor(session.data.actor);
      if (session.data.actor.email) {
        identify(session.data.actor.email, { name: session.data.actor.name, role: session.data.actor.role });
      }
      const requestedSection = sectionFromPathname(window.location.pathname) ?? "overview";
      if (!canAccessSection(session.data.actor ?? null, requestedSection)) {
        setSection(firstAccessibleSection(session.data.actor ?? null), { replace: true });

