export interface ApiResult<T> {
  ok: boolean;
  status: number;
  data: T;
}

const ADMIN_TOKEN_KEY = "appointy.ops.adminToken";
const ADMIN_NAME_KEY = "appointy.ops.adminName";
const ADMIN_EMAIL_KEY = "appointy.ops.adminEmail";

export const apiOrigin = import.meta.env.VITE_OPS_API_URL ?? "";

export function getAdminToken(): string {
  return localStorage.getItem(ADMIN_TOKEN_KEY) ?? "";
}

export function setAdminToken(token: string): void {
  if (token) localStorage.setItem(ADMIN_TOKEN_KEY, token);
  else localStorage.removeItem(ADMIN_TOKEN_KEY);
}

export function getAdminName(): string {
  return localStorage.getItem(ADMIN_NAME_KEY) ?? "Admin";
}

export function setAdminName(name: string): void {
  localStorage.setItem(ADMIN_NAME_KEY, name || "Admin");
}

export function getAdminEmail(): string {
  return localStorage.getItem(ADMIN_EMAIL_KEY) ?? "";
}

export function setAdminEmail(email: string): void {
  if (email) localStorage.setItem(ADMIN_EMAIL_KEY, email);
  else localStorage.removeItem(ADMIN_EMAIL_KEY);
}

export function clearAdminSession(): void {
  localStorage.removeItem(ADMIN_TOKEN_KEY);
  localStorage.removeItem(ADMIN_NAME_KEY);
  localStorage.removeItem(ADMIN_EMAIL_KEY);
}

export async function apiRequest<T>(
  method: string,
  path: string,
  body?: unknown,
): Promise<ApiResult<T>> {
  const headers: Record<string, string> = {
    Accept: "application/json",
  };
  if (body !== undefined) headers["Content-Type"] = "application/json";

  const token = getAdminToken();
  if (token) headers.Authorization = `Bearer ${token}`;

  try {
    const response = await fetch(`${apiOrigin}${path}`, {
      method,
      headers,
      body: body === undefined ? undefined : JSON.stringify(body),
    });
    const data = await response.json().catch(() => ({}));
    return {
      ok: response.ok,
      status: response.status,
      data: data as T,
    };
  } catch (error) {
    return {
      ok: false,
      status: 0,
      data: { error: error instanceof Error ? error.message : "Network error" } as T,
    };
  }
}

