import { apiRequest, apiOrigin, getAdminToken } from "./client";

const SITE_ID = (import.meta.env.VITE_OPS_SITE_ID as string | undefined) ?? "default";

const SITE_HEADERS = { "X-Site-Id": SITE_ID };

export interface CanonicalProduct {
  product_id: string;
  site_id: string;
  canonical_name: string;
  category: string | null;
  hsn_code: string | null;
  unit: string;
  pack_size: number;
  created_at: string;
  updated_at: string;
}

export interface UnresolvedBillItem {
  id: string;
  site_id: string;
  order_id: string | null;
  bill_item_name: string;
  hsn_code: string | null;
  qty: number;
  unit_rate: number | null;
  line_value: number | null;
  status: string;
  created_at: string;
}

export interface BillExtractionLine {
  sr_no?: number;
  hsn_code?: string | null;
  item_name: string;
  qty: number;
  rate?: number | null;
  value?: number | null;
}

export interface BillUploadResult {
  bill: {
    vendor: string | null;
    bill_number: string | null;
    bill_date: string | null;
    grand_total: number | null;
    items: BillExtractionLine[];
  };
  orderId: string;
  matchResults: Array<{
    billItemName: string;
    matched: boolean;
    canonicalName?: string;
    productId?: string;
    matchMethod?: string;
    confidence?: number;
  }>;
}

export interface ComplianceLogRow {
  scanned_at: string;
  date: string;
  vendor: string | null;
  bill_number: string | null;
  product_id: string | null;
  product_name: string;
  category: string | null;
  hsn_code: string | null;
  unit: string | null;
  pack_size: number | null;
  qty_received: number;
  expected_qty: number | null;
  unit_rate: number | null;
  line_value: number | null;
  expiry_date: string | null;
  received_by: string | null;
  status: "OK" | "MISMATCH";
}

export function listCanonicalProducts() {
  return apiRequest<{ products: CanonicalProduct[] }>(
    "GET", "/api/inventory/canonical-products", undefined, SITE_HEADERS,
  );
}

export function createCanonicalProduct(input: {
  canonical_name: string;
  category?: string;
  hsn_code?: string;
  unit?: string;
  pack_size?: number;
}) {
  return apiRequest<{ product: CanonicalProduct }>(
    "POST", "/api/inventory/canonical-products", input, SITE_HEADERS,
  );
}

export function listUnresolvedBillItems() {
  return apiRequest<{ items: UnresolvedBillItem[] }>(
    "GET", "/api/inventory/bills/unresolved", undefined, SITE_HEADERS,
  );
}

export function resolveBillItem(input: {
  unresolved_id: string;
  product_id: string;
  bill_item_name?: string;
  remember_alias?: boolean;
}) {
  return apiRequest<{ resolved: boolean }>(
    "POST", "/api/inventory/bills/resolve", input, SITE_HEADERS,
  );
}

export function uploadBill(input: {
  image_base64: string;
  vendor?: string;
  bill_number?: string;
  bill_date?: string;
}) {
  return apiRequest<BillUploadResult>(
    "POST", "/api/inventory/bills", input, SITE_HEADERS,
  );
}

export function listCompliance(params?: { from?: string; to?: string }) {
  const q = new URLSearchParams();
  if (params?.from) q.set("from", params.from);
  if (params?.to) q.set("to", params.to);
  const qs = q.toString();
  return apiRequest<{ rows: ComplianceLogRow[] }>(
    "GET",
    `/api/inventory/compliance${qs ? `?${qs}` : ""}`,
    undefined,
    SITE_HEADERS,
  );
}

export function complianceCsvUrl(params?: { from?: string; to?: string }): string {
  const q = new URLSearchParams();
  if (params?.from) q.set("from", params.from);
  if (params?.to) q.set("to", params.to);
  // CSV link includes the bearer token because <a download> can't set headers.
  q.set("token", "");
  const token = getAdminToken();
  // Browsers can't attach Authorization; use Bearer-as-query is not supported
  // server-side. So we trigger a fetch + blob download from the UI instead.
  return `${apiOrigin}/api/inventory/compliance/export.csv?${q.toString()}__token=${encodeURIComponent(token)}`;
}

export async function downloadComplianceCsv(params?: { from?: string; to?: string }): Promise<void> {
  const q = new URLSearchParams();
  if (params?.from) q.set("from", params.from);
  if (params?.to) q.set("to", params.to);
  const headers: Record<string, string> = { ...SITE_HEADERS };
  const token = getAdminToken();
  if (token) headers.Authorization = `Bearer ${token}`;
  const res = await fetch(`${apiOrigin}/api/inventory/compliance/export.csv?${q.toString()}`, { headers });
  if (!res.ok) throw new Error(`Export failed (${res.status})`);
  const blob = await res.blob();
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = `compliance_${params?.from ?? "all"}_${params?.to ?? "all"}.csv`;
  document.body.appendChild(a);
  a.click();
  a.remove();
  URL.revokeObjectURL(url);
}

export async function fileToBase64(file: File): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => {
      const result = reader.result;
      if (typeof result !== "string") {
        reject(new Error("Failed to read file"));
        return;
      }
      // strip "data:image/...;base64," prefix
      const comma = result.indexOf(",");
      resolve(comma >= 0 ? result.slice(comma + 1) : result);
    };
    reader.onerror = () => reject(reader.error);
    reader.readAsDataURL(file);
  });
}

