// ── Admin: Bill Upload + Extraction ─────────────────────────

if (pathname === "/api/inventory/bills" && method === "POST") {
  const auth = await authenticate(req, res);
  if (!auth) return true;
  const body = await readBodyJson(req);

  const imageSource = asString(body.image) ?? asString(body.image_url);
  if (!imageSource) {
    json(res, 400, { error: "image (base64) or image_url is required" });
    return true;
  }

  const mimeType = asString(body.mime_type) ?? "image/jpeg";

  // Step 1: Extract structured data from bill image
  const extraction = await extractBillFromImage(imageSource, mimeType);
  if (!extraction.success || !extraction.bill) {
    json(res, 422, { error: extraction.error ?? "Bill extraction failed" });
    return true;
  }

  // Step 2: Match line items to canonical products + create order
  const result = await processBill(
    auth.siteId,
    extraction.bill,
    asString(body.image_url),
  );

  json(res, 200, {
    orderId: result.orderId,
    bill: extraction.bill,
    matches: result.results.map((r) => ({
      item: r.lineItem.item_purchased,
      hsn: r.lineItem.hsn_code,
      qty: r.lineItem.qty,
      rate: r.lineItem.rate,
      matched: r.match.matched,
      canonicalName: r.match.canonicalName,
      method: r.match.method,
      confidence: r.match.confidence,
      orderItemId: r.orderItemId,
    })),
    summary: result.summary,
  });
  return true;
}

