};

const th: React.CSSProperties = {
  padding: "6px 8px", borderBottom: "1px solid var(--line)", fontWeight: 600, fontSize: 11,
  textTransform: "uppercase", letterSpacing: 0.5,
};

const td: React.CSSProperties = { padding: "8px", verticalAlign: "top" };

toolUseResult.content:
import { useMemo, useState, type ReactNode } from "react";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import {
  Warehouse,
  Upload,
  FileText,
  Download,
  RefreshCw,
  Plus,
  Check,
  AlertTriangle,
} from "lucide-react";

import {
  type CanonicalProduct,
  type UnresolvedBillItem,
  type ComplianceLogRow,
  type BillUploadResult,
  listCanonicalProducts,
  createCanonicalProduct,
  listUnresolvedBillItems,
  resolveBillItem,
  uploadBill,
  listCompliance,
  downloadComplianceCsv,
  fileToBase64,
} from "../../api/inventory";
import { toastError, toastSuccess, errorMessage } from "../../components/ui/toast";

type TabKey = "bills" | "unresolved" | "products" | "compliance";

export function InventorySection() {
  const [tab, setTab] = useState<TabKey>("bills");

  return (
    <div>
      <section className="panel">
        <div className="panel-title">
          <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
            <Warehouse size={20} />
            <div>
              <div style={{ fontSize: 12, color: "var(--muted)", textTransform: "uppercase", letterSpacing: 0.6 }}>
                Operations
              </div>
              <h2 style={{ margin: 0 }}>Inventory</h2>
            </div>
          </div>
        </div>
        <p className="panel-copy">
          Upload vendor bills, resolve unmatched line items, manage the canonical product catalog, and export the
          compliance audit log.
        </p>
        <div style={{ display: "flex", gap: 6, borderBottom: "1px solid var(--line)", marginBottom: 14, flexWrap: "wrap" }}>
          <TabButton active={tab === "bills"} onClick={() => setTab("bills")} icon={<Upload size={14} />} label="Upload bill" />
          <TabButton active={tab === "unresolved"} onClick={() => setTab("unresolved")} icon={<AlertTriangle size={14} />} label="Unresolved" />
          <TabButton active={tab === "products"} onClick={() => setTab("products")} icon={<FileText size={14} />} label="Catalog" />
          <TabButton active={tab === "compliance"} onClick={() => setTab("compliance")} icon={<Download size={14} />} label="Compliance" />
        </div>

        {tab === "bills" && <BillUploadTab />}
        {tab === "unresolved" && <UnresolvedTab />}
        {tab === "products" && <CatalogTab />}
        {tab === "compliance" && <ComplianceTab />}
      </section>
    </div>
  );
}

function TabButton({ active, onClick, icon, label }: { active: boolean; onClick: () => void; icon: ReactNode; label: string }) {
  return (
    <button
      type="button"
      onClick={onClick}
      style={{
        display: "inline-flex",
        alignItems: "center",
        gap: 6,
        padding: "8px 12px",
        background: "transparent",
        border: "none",
        borderBottom: active ? "2px solid var(--accent, #2563eb)" : "2px solid transparent",
        color: active ? "var(--text)" : "var(--muted)",
        fontWeight: active ? 600 : 500,
        cursor: "pointer",
        fontSize: 13,
      }}
    >
      {icon}
      {label}
    </button>
  );
}

// ───────────────────────── Bill Upload ─────────────────────────

function BillUploadTab() {
  const queryClient = useQueryClient();
  const [file, setFile] = useState<File | null>(null);
  const [preview, setPreview] = useState<string | null>(null);
  const [result, setResult] = useState<BillUploadResult | null>(null);

  const uploadMutation = useMutation({
    mutationFn: async (f: File) => {
      const image = await fileToBase64(f);
      return uploadBill({ image, mime_type: f.type || "image/jpeg" });
    },
    onSuccess: (res) => {
      if (!res.ok) {
        toastError(errorMessage((res.data as { error?: string }).error, "Bill upload failed"));
        return;
      }
      setResult(res.data);
      toastSuccess("Bill processed", `${res.data.summary?.matched ?? 0} matched, ${res.data.summary?.unresolved ?? 0} unresolved`);
      void queryClient.invalidateQueries({ queryKey: ["inv-unresolved"] });
    },
    onError: (err) => toastError(err, "Bill upload failed"),
  });

  function onFile(f: File | null) {
    setFile(f);
    setResult(null);
    if (!f) { setPreview(null); return; }
    const url = URL.createObjectURL(f);
    setPreview(url);
  }

  return (
    <div style={{ display: "grid", gap: 16, gridTemplateColumns: "1fr 1fr" }}>
      <div>
        <label
          htmlFor="bill-file"
          style={{
            display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center",
            minHeight: 220, border: "1.5px dashed var(--line)", borderRadius: 10, padding: 24,
            cursor: "pointer", background: "var(--surface, #fafafa)",
          }}
        >
          {preview ? (
            <img src={preview} alt="Bill preview" style={{ maxHeight: 200, maxWidth: "100%", borderRadius: 6 }} />
          ) : (
            <>
              <Upload size={28} />
              <div style={{ marginTop: 8, fontWeight: 600 }}>Click to upload bill image</div>
              <div style={{ fontSize: 12, color: "var(--muted)", marginTop: 4 }}>JPG / PNG / WEBP up to ~10 MB</div>
            </>
          )}
          <input
            id="bill-file"
            type="file"
            accept="image/*"
            style={{ display: "none" }}
            onChange={(e) => onFile(e.target.files?.[0] ?? null)}
          />
        </label>
        <div style={{ display: "flex", gap: 8, marginTop: 12 }}>
          <button
            type="button"
            className="primary-button"
            disabled={!file || uploadMutation.isPending}
            onClick={() => file && uploadMutation.mutate(file)}
          >
            {uploadMutation.isPending ? "Processing…" : "Extract & match"}
          </button>
          {file && (
            <button type="button" onClick={() => onFile(null)} style={ghostBtn}>
              Clear
            </button>
          )}
        </div>
      </div>

      <div>
        {!result && (
          <div style={{ color: "var(--muted)", fontSize: 13 }}>
            Upload a vendor bill and we'll OCR + LLM-extract the line items, then match each to the canonical catalog.
            Anything we can't match lands in <b>Unresolved</b> for you to resolve.
          </div>
        )}
        {result && (
          <div>
            <div style={{ fontWeight: 600, marginBottom: 8 }}>
              {result.bill.vendor ?? "Vendor"} · {result.bill.bill_number ?? "—"} · {result.bill.bill_date ?? "—"}
            </div>
            <div style={{ display: "flex", gap: 8, marginBottom: 10 }}>
              <Pill ok>{result.summary?.matched ?? 0} matched</Pill>
              <Pill warn>{result.summary?.unresolved ?? 0} unresolved</Pill>
              <Pill>{result.summary?.total ?? result.matches.length} total</Pill>
            </div>
            <div style={{ display: "grid", gap: 6 }}>
              {result.matches.map((m, i) => (
                <div key={i} style={billRow}>
                  <div>
                    <div style={{ fontWeight: 600, fontSize: 13 }}>{m.item}</div>
                    <div style={{ fontSize: 12, color: "var(--muted)" }}>
                      HSN {m.hsn ?? "—"} · qty {m.qty} · ₹{m.rate ?? "—"}
                    </div>
                  </div>
                  <div style={{ textAlign: "right", fontSize: 12 }}>
                    {m.matched ? (
                      <span style={{ color: "#16a34a", display: "inline-flex", gap: 4, alignItems: "center" }}>
                        <Check size={14} /> {m.canonicalName}
                      </span>
                    ) : (
                      <span style={{ color: "#dc2626" }}>Unresolved</span>
                    )}
                    {m.method && <div style={{ color: "var(--muted)" }}>{m.method}</div>}
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

// ───────────────────────── Unresolved ─────────────────────────

function UnresolvedTab() {
  const queryClient = useQueryClient();
  const unresolvedQuery = useQuery({ queryKey: ["inv-unresolved"], queryFn: listUnresolvedBillItems });
  const productsQuery = useQuery({ queryKey: ["inv-canonical"], queryFn: listCanonicalProducts });

  const items = unresolvedQuery.data?.data?.items ?? [];
  const products = productsQuery.data?.data?.products ?? [];

  const resolveMutation = useMutation({
    mutationFn: resolveBillItem,
    onSuccess: (res) => {
      if (!res.ok) { toastError(errorMessage((res.data as { error?: string }).error, "Resolve failed")); return; }
      toastSuccess("Item resolved");
      void queryClient.invalidateQueries({ queryKey: ["inv-unresolved"] });
    },
    onError: (err) => toastError(err, "Resolve failed"),
  });

  const createMutation = useMutation({
    mutationFn: createCanonicalProduct,
    onError: (err) => toastError(err, "Create product failed"),
  });

  return (
    <div>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 10 }}>
        <div style={{ fontWeight: 600 }}>
          {items.length} unresolved item{items.length === 1 ? "" : "s"}
        </div>
        <button type="button" onClick={() => void unresolvedQuery.refetch()} style={ghostBtn}>
          <RefreshCw size={14} /> Refresh
        </button>
      </div>

      {unresolvedQuery.isLoading && <div style={{ color: "var(--muted)" }}>Loading…</div>}
      {!unresolvedQuery.isLoading && items.length === 0 && (
        <div style={{ color: "var(--muted)", fontStyle: "italic", padding: 24, textAlign: "center" }}>
          No unresolved items. Every bill line is mapped to a canonical product.
        </div>
      )}

      <div style={{ display: "grid", gap: 10 }}>
        {items.map((it) => (
          <UnresolvedRow
            key={it.id}
            item={it}
            products={products}
            onResolveExisting={(productId) =>
              resolveMutation.mutate({
                unresolved_id: it.id,
                product_id: productId,
                bill_item_name: it.bill_item_name,
                remember_alias: true,
              })
            }
            onCreateNew={async (input) => {
              const created = await createMutation.mutateAsync(input);
              if (!created.ok) return;
              await resolveMutation.mutateAsync({
                unresolved_id: it.id,
                product_id: created.data.product_id,
                bill_item_name: it.bill_item_name,
                remember_alias: true,
              });
              void queryClient.invalidateQueries({ queryKey: ["inv-canonical"] });
            }}
          />
        ))}
      </div>
    </div>
  );
}

function UnresolvedRow({
  item,
  products,
  onResolveExisting,
  onCreateNew,
}: {
  item: UnresolvedBillItem;
  products: CanonicalProduct[];
  onResolveExisting: (productId: string) => void;
  onCreateNew: (input: { canonical_name: string; category?: string; hsn_code?: string; unit?: string; pack_size?: number }) => void;
}) {
  const [mode, setMode] = useState<"existing" | "new">("existing");
  const [search, setSearch] = useState("");
  const [newName, setNewName] = useState(item.bill_item_name);
  const [newCategory, setNewCategory] = useState("Grocery");
  const [newUnit, setNewUnit] = useState("pcs");
  const [newPack, setNewPack] = useState(1);

  const matches = useMemo(() => {
    const q = search.trim().toLowerCase();
    const base = q
      ? products.filter((p) => p.canonical_name.toLowerCase().includes(q))
      : products;
    return base.slice(0, 8);
  }, [products, search]);

  return (
    <div style={{ border: "1px solid var(--line)", borderRadius: 10, padding: 14 }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", gap: 12 }}>
        <div>
          <div style={{ fontWeight: 600, fontSize: 14 }}>{item.bill_item_name}</div>
          <div style={{ fontSize: 12, color: "var(--muted)", marginTop: 2 }}>
            HSN {item.hsn_code ?? "—"} · qty {item.qty} · ₹{item.unit_rate ?? "—"} · value ₹{item.line_value ?? "—"}
          </div>
        </div>
        <div style={{ display: "flex", gap: 6 }}>
          <button
            type="button"
            onClick={() => setMode("existing")}
            style={mode === "existing" ? activePillBtn : pillBtn}
          >
            Existing
          </button>
          <button
            type="button"
            onClick={() => setMode("new")}
            style={mode === "new" ? activePillBtn : pillBtn}
          >
            New product
          </button>
        </div>
      </div>

      {mode === "existing" && (
        <div style={{ marginTop: 12 }}>
          <input
            type="text"
            placeholder="Search catalog…"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            style={input}
          />
          <div style={{ display: "grid", gap: 4, marginTop: 8 }}>
            {matches.map((p) => (
              <button
                key={p.product_id}
                type="button"
                onClick={() => onResolveExisting(p.product_id)}
                style={pickRow}
              >
                <div>
                  <div style={{ fontWeight: 600, fontSize: 13 }}>{p.canonical_name}</div>
                  <div style={{ fontSize: 11, color: "var(--muted)" }}>
                    {p.category ?? "—"} · {p.unit} · pack {p.pack_size} · HSN {p.hsn_code ?? "—"}
                  </div>
                </div>
                <Check size={16} />
              </button>
            ))}
            {matches.length === 0 && (
              <div style={{ fontSize: 12, color: "var(--muted)", padding: 8 }}>No matches.</div>
            )}
          </div>
        </div>
      )}

      {mode === "new" && (
        <div style={{ marginTop: 12, display: "grid", gap: 8, gridTemplateColumns: "1fr 1fr" }}>
          <FieldLabel label="Canonical name">
            <input type="text" value={newName} onChange={(e) => setNewName(e.target.value)} style={input} />
          </FieldLabel>
          <FieldLabel label="Category">
            <input type="text" value={newCategory} onChange={(e) => setNewCategory(e.target.value)} style={input} />
          </FieldLabel>
          <FieldLabel label="Unit">
            <select value={newUnit} onChange={(e) => setNewUnit(e.target.value)} style={input}>
              <option value="pcs">pcs</option>
              <option value="kg">kg</option>
              <option value="g">g</option>
              <option value="l">l</option>
              <option value="ml">ml</option>
              <option value="pack">pack</option>
            </select>
          </FieldLabel>
          <FieldLabel label="Pack size">
            <input type="number" value={newPack} min={0} step="any" onChange={(e) => setNewPack(Number(e.target.value) || 1)} style={input} />
          </FieldLabel>
          <div style={{ gridColumn: "1 / -1", display: "flex", justifyContent: "flex-end" }}>
            <button
              type="button"
              className="primary-button"
              onClick={() =>
                onCreateNew({
                  canonical_name: newName.trim(),
                  category: newCategory.trim() || undefined,
                  hsn_code: item.hsn_code ?? undefined,
                  unit: newUnit,
                  pack_size: newPack,
                })
              }
              disabled={!newName.trim()}
            >
              <Plus size={14} /> Create + map
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

// ───────────────────────── Catalog ─────────────────────────

function CatalogTab() {
  const queryClient = useQueryClient();
  const productsQuery = useQuery({ queryKey: ["inv-canonical"], queryFn: listCanonicalProducts });
  const products = productsQuery.data?.data?.products ?? [];
  const [showForm, setShowForm] = useState(false);
  const [draft, setDraft] = useState({ canonical_name: "", category: "Grocery", hsn_code: "", unit: "pcs", pack_size: 1 });
  const [filter, setFilter] = useState("");

  const filtered = useMemo(() => {
    const q = filter.trim().toLowerCase();
    if (!q) return products;
    return products.filter((p) =>
      p.canonical_name.toLowerCase().includes(q) ||
      (p.category ?? "").toLowerCase().includes(q) ||
      (p.hsn_code ?? "").toLowerCase().includes(q),
    );
  }, [products, filter]);

  const createMutation = useMutation({
    mutationFn: () => createCanonicalProduct({
      canonical_name: draft.canonical_name,
      category: draft.category || undefined,
      hsn_code: draft.hsn_code || undefined,
      unit: draft.unit,
      pack_size: draft.pack_size,
    }),
    onSuccess: (res) => {
      if (!res.ok) { toastError(errorMessage((res.data as { error?: string }).error, "Create failed")); return; }
      toastSuccess("Product created");
      setShowForm(false);
      setDraft({ canonical_name: "", category: "Grocery", hsn_code: "", unit: "pcs", pack_size: 1 });
      void queryClient.invalidateQueries({ queryKey: ["inv-canonical"] });
    },
    onError: (err) => toastError(err, "Create failed"),
  });

  return (
    <div>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 10, gap: 10 }}>
        <input
          type="text"
          placeholder="Filter by name, category, HSN…"
          value={filter}
          onChange={(e) => setFilter(e.target.value)}
          style={{ ...input, flex: 1, maxWidth: 360 }}
        />
        <div style={{ display: "flex", gap: 8 }}>
          <button type="button" onClick={() => void productsQuery.refetch()} style={ghostBtn}>
            <RefreshCw size={14} /> Refresh
          </button>
          <button type="button" className="primary-button" onClick={() => setShowForm(true)}>
            <Plus size={14} /> New product
          </button>
        </div>
      </div>

      {showForm && (
        <div style={{ border: "1px solid var(--line)", borderRadius: 10, padding: 14, marginBottom: 12 }}>
          <div style={{ display: "grid", gap: 8, gridTemplateColumns: "2fr 1fr 1fr 1fr 1fr" }}>
            <FieldLabel label="Canonical name">
              <input type="text" value={draft.canonical_name} onChange={(e) => setDraft({ ...draft, canonical_name: e.target.value })} style={input} />
            </FieldLabel>
            <FieldLabel label="Category">
              <input type="text" value={draft.category} onChange={(e) => setDraft({ ...draft, category: e.target.value })} style={input} />
            </FieldLabel>
            <FieldLabel label="HSN">
              <input type="text" value={draft.hsn_code} onChange={(e) => setDraft({ ...draft, hsn_code: e.target.value })} style={input} />
            </FieldLabel>
            <FieldLabel label="Unit">
              <select value={draft.unit} onChange={(e) => setDraft({ ...draft, unit: e.target.value })} style={input}>
                <option value="pcs">pcs</option><option value="kg">kg</option><option value="g">g</option>
                <option value="l">l</option><option value="ml">ml</option><option value="pack">pack</option>
              </select>
            </FieldLabel>
            <FieldLabel label="Pack size">
              <input type="number" step="any" value={draft.pack_size} onChange={(e) => setDraft({ ...draft, pack_size: Number(e.target.value) || 1 })} style={input} />
            </FieldLabel>
          </div>
          <div style={{ display: "flex", gap: 8, marginTop: 10, justifyContent: "flex-end" }}>
            <button type="button" onClick={() => setShowForm(false)} style={ghostBtn}>Cancel</button>
            <button type="button" className="primary-button" disabled={!draft.canonical_name.trim() || createMutation.isPending} onClick={() => createMutation.mutate()}>
              {createMutation.isPending ? "Creating…" : "Create"}
            </button>
          </div>
        </div>
      )}

      <div style={{ overflowX: "auto" }}>
        <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 13 }}>
          <thead>
            <tr style={{ textAlign: "left", color: "var(--muted)" }}>
              <th style={th}>Canonical name</th>
              <th style={th}>Category</th>
              <th style={th}>HSN</th>
              <th style={th}>Unit</th>
              <th style={th}>Pack</th>
              <th style={th}>Created</th>
            </tr>
          </thead>
          <tbody>
            {filtered.map((p) => (
              <tr key={p.product_id} style={{ borderTop: "1px solid var(--line)" }}>
                <td style={td}>{p.canonical_name}</td>
                <td style={td}>{p.category ?? "—"}</td>
                <td style={td}>{p.hsn_code ?? "—"}</td>
                <td style={td}>{p.unit}</td>
                <td style={td}>{p.pack_size}</td>
                <td style={td}>{p.created_at ? new Date(p.created_at).toLocaleDateString() : "—"}</td>
              </tr>
            ))}
            {filtered.length === 0 && (
              <tr><td colSpan={6} style={{ ...td, textAlign: "center", color: "var(--muted)", padding: 24 }}>
                {productsQuery.isLoading ? "Loading…" : "No products. Seed the catalog or create one to begin."}
              </td></tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
}

// ───────────────────────── Compliance ─────────────────────────

function ComplianceTab() {
  const today = new Date().toISOString().slice(0, 10);
  const monthAgo = new Date(Date.now() - 30 * 86400_000).toISOString().slice(0, 10);
  const [from, setFrom] = useState(monthAgo);
  const [to, setTo] = useState(today);

  const query = useQuery({
    queryKey: ["inv-compliance", from, to],
    queryFn: () => listCompliance({ from: from || undefined, to: to ? `${to}T23:59:59` : undefined }),
  });

  const rows: ComplianceLogRow[] = query.data?.data?.rows ?? [];

  async function onExport() {
    try {
      await downloadComplianceCsv({ from: from || undefined, to: to ? `${to}T23:59:59` : undefined });
      toastSuccess("CSV exported");
    } catch (err) {
      toastError(err, "Export failed");
    }
  }

  return (
    <div>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-end", marginBottom: 12, gap: 10, flexWrap: "wrap" }}>
        <div style={{ display: "flex", gap: 10 }}>
          <FieldLabel label="From">
            <input type="date" value={from} onChange={(e) => setFrom(e.target.value)} style={input} />
          </FieldLabel>
          <FieldLabel label="To">
            <input type="date" value={to} onChange={(e) => setTo(e.target.value)} style={input} />
          </FieldLabel>
        </div>
        <div style={{ display: "flex", gap: 8 }}>
          <button type="button" onClick={() => void query.refetch()} style={ghostBtn}>
            <RefreshCw size={14} /> Refresh
          </button>
          <button type="button" className="primary-button" onClick={() => void onExport()}>
            <Download size={14} /> Export CSV
          </button>
        </div>
      </div>

      <div style={{ overflowX: "auto" }}>
        <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 12 }}>
          <thead>
            <tr style={{ textAlign: "left", color: "var(--muted)" }}>
              <th style={th}>Date</th>
              <th style={th}>Vendor</th>
              <th style={th}>Bill #</th>
              <th style={th}>Product</th>
              <th style={th}>HSN</th>
              <th style={th}>Unit</th>
              <th style={th}>Pack</th>
              <th style={{ ...th, textAlign: "right" }}>Qty</th>
              <th style={{ ...th, textAlign: "right" }}>Expected</th>
              <th style={{ ...th, textAlign: "right" }}>Value</th>
              <th style={th}>Expiry</th>
              <th style={th}>By</th>
              <th style={th}>Status</th>
            </tr>
          </thead>
          <tbody>
            {rows.map((r, i) => (
              <tr key={i} style={{ borderTop: "1px solid var(--line)" }}>
                <td style={td}>{r.date}</td>
                <td style={td}>{r.vendor ?? "—"}</td>
                <td style={td}>{r.bill_number ?? "—"}</td>
                <td style={td}>{r.product_name}</td>
                <td style={td}>{r.hsn_code ?? "—"}</td>
                <td style={td}>{r.unit ?? "—"}</td>
                <td style={td}>{r.pack_size ?? "—"}</td>
                <td style={{ ...td, textAlign: "right" }}>{r.qty_received}</td>
                <td style={{ ...td, textAlign: "right" }}>{r.expected_qty ?? "—"}</td>
                <td style={{ ...td, textAlign: "right" }}>{r.line_value != null ? `₹${r.line_value}` : "—"}</td>
                <td style={td}>{r.expiry_date ?? "—"}</td>
                <td style={td}>{r.received_by ?? "—"}</td>
                <td style={td}>
                  {r.status === "OK" ? (
                    <Pill ok>OK</Pill>
                  ) : (
                    <Pill warn>Mismatch</Pill>
                  )}
                </td>
              </tr>
            ))}
            {rows.length === 0 && (
              <tr><td colSpan={13} style={{ ...td, textAlign: "center", color: "var(--muted)", padding: 24 }}>
                {query.isLoading ? "Loading…" : "No receipts in this range."}
              </td></tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
}

// ───────────────────────── tiny ui helpers ─────────────────────────

function FieldLabel({ label, children }: { label: string; children: ReactNode }) {
  return (
    <label style={{ display: "grid", gap: 4, fontSize: 11, color: "var(--muted)", textTransform: "uppercase", letterSpacing: 0.5 }}>
      {label}
      {children}
    </label>
  );
}

function Pill({ ok, warn, children }: { ok?: boolean; warn?: boolean; children: ReactNode }) {
  const bg = ok ? "#dcfce7" : warn ? "#fef3c7" : "#e5e7eb";
  const color = ok ? "#166534" : warn ? "#92400e" : "#374151";
  return (
    <span style={{ background: bg, color, padding: "2px 8px", borderRadius: 999, fontSize: 11, fontWeight: 600 }}>
      {children}
    </span>
  );
}

