export async function appendToSheetDirect(
  tabName: string,
  rowData: string[],
): Promise<void> {
  const config = getConfig();
  if (!config) return;

  const sheets = await getSheetsClient();
  if (!sheets) return;

  const { spreadsheetId } = config;

  // Ensure the tab exists
  await ensureSheet(sheets, spreadsheetId, tabName);

  // Check if headers exist (row 1)
  try {
    const headerCheck = await sheets.spreadsheets.values.get({
      spreadsheetId,
      range: formatSheetRange(tabName, 'A1:A1'),
    });

    const hasHeaders = (headerCheck.data.values?.[0]?.length ?? 0) > 0;

    if (!hasHeaders) {
      // Write headers from the domain registry
      // Import dynamically to avoid circular dependency
      const { getSheetConfigForDomain, getAllDomains } = await import('../domains/index');
      const domain = getAllDomains().find(d => d.schema.sheetTabName === tabName);
      if (domain) {
        await sheets.spreadsheets.values.update({
          spreadsheetId,
          range: formatSheetRange(tabName, 'A1'),
          valueInputOption: 'USER_ENTERED',
          requestBody: { values: [domain.schema.sheetColumns] },
        });
        console.log(`📊 [Sheets] Auto-wrote headers for "${tabName}"`);
      }
    }
  } catch {
    // Non-critical — proceed with append
  }

  // Append the row
  await sheets.spreadsheets.values.append({
    spreadsheetId,
    range: formatSheetRange(tabName, 'A:A'),
    valueInputOption: 'USER_ENTERED',
    insertDataOption: 'INSERT_ROWS',
    requestBody: { values: [rowData] },

