  // ── Compliance: date-wise audit log of received items ────────
  // JSON: GET /api/inventory/compliance?from=YYYY-MM-DD&to=YYYY-MM-DD
  // CSV : GET /api/inventory/compliance/export.csv?...
  if (
    (pathname === "/api/inventory/compliance" ||
      pathname === "/api/inventory/compliance/export.csv") &&
    method === "GET"
  ) {
    const auth = await authenticate(req, res);
    if (!auth) return true;
    const q = parseUrl(req.url ?? "", true).query;
    const from = typeof q.from === "string" ? q.from : null;
    const to = typeof q.to === "string" ? q.to : null;
    const rows = await listComplianceLog(auth.siteId, from, to);

    if (pathname === "/api/inventory/compliance") {
      json(res, 200, { rows });
      return true;
    }

    // CSV branch
    const headers = [
      "date","vendor","bill_number","product","category","hsn","unit","pack_size",
      "qty_received","expected_qty","unit_rate","value","expiry_date","received_by","status",
    ];
    const esc = (v: unknown): string => {
      if (v === null || v === undefined) return "";
      const s = String(v);
      return /[",\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
    };
    const lines = [headers.join(",")];
    for (const r of rows) {
      lines.push([
        r.date, r.vendor, r.bill_number, r.product_name, r.category, r.hsn_code,
        r.unit, r.pack_size, r.qty_received, r.expected_qty, r.unit_rate, r.line_value,
        r.expiry_date, r.received_by, r.status,
      ].map(esc).join(","));
    }
    const filename = `compliance_${from ?? "all"}_${to ?? "all"}.csv`;
    res.writeHead(200, {
