/**
 * Bill Matcher — maps vendor bill line items to canonical products.
 *
 * Multi-step matching pipeline:
 *   1. Exact name match against canonical_products
 *   2. Product alias cache hit (raw_name + optional HSN context)
 *   3. HSN-scoped fuzzy match (Fuse.js within same HSN category)
 *   4. LLM normalization (existing normalizer.ts)
 *   5. Unresolved → admin queue
 *
 * Each successful match learns an alias for future free lookups.
 * Over time, the alias cache grows and the LLM is called less.
 */

import { nanoid } from "nanoid";
import type { BillLineItem, ExtractedBill } from "./bill-extractor";
import {
  createOrderFromBill,
  createOrderItemFromBill,
  findCanonicalProductByName,
  findProductAlias,
  insertUnresolvedBillItem,
  listCanonicalProductsByHsn,
  saveProductAlias,
  type CanonicalProduct,
} from "./db";
import { normalizeProductName } from "./normalizer";

export type MatchResult = {
  matched: boolean;
  productId: string | null;
  canonicalName: string;
  confidence: number;
  method: "exact" | "alias" | "hsn_fuzzy" | "normalized" | "unresolved";
};

/**
 * Simple fuzzy name comparison. Returns a similarity score 0-1.
 * Avoids pulling in Fuse.js server-side for a simple use case.
 */
function fuzzyScore(a: string, b: string): number {
  const la = a.toLowerCase().replace(/[^a-z0-9]/g, "");
  const lb = b.toLowerCase().replace(/[^a-z0-9]/g, "");
  if (la === lb) return 1.0;
  if (la.includes(lb) || lb.includes(la)) return 0.8;

  // Bigram similarity (Dice coefficient)
  const bigramsA = new Set<string>();
  for (let i = 0; i < la.length - 1; i++) bigramsA.add(la.slice(i, i + 2));
  const bigramsB = new Set<string>();
  for (let i = 0; i < lb.length - 1; i++) bigramsB.add(lb.slice(i, i + 2));

  if (bigramsA.size === 0 || bigramsB.size === 0) return 0;

  let intersection = 0;
  for (const bg of bigramsA) {
    if (bigramsB.has(bg)) intersection++;
  }
  return (2 * intersection) / (bigramsA.size + bigramsB.size);
}

/**
 * Match a single bill line item to a canonical product.
 */
export async function matchBillLineToProduct(
  siteId: string,
  item: BillLineItem,
): Promise<MatchResult> {
  const name = item.item_purchased.trim();
