  const exact = await findCanonicalProductByName(siteId, name);
  if (exact) {
    return {
      matched: true,
      productId: exact.product_id,
      canonicalName: exact.canonical_name,
      confidence: 1.0,
      method: "exact",
    };
  }

  // Step 2: Product alias cache hit (HSN-aware)
  const alias = await findProductAlias(siteId, name, hsn);
  if (alias && alias.confidence >= 0.7) {
    return {
      matched: true,
      productId: alias.product_id,
      canonicalName: alias.raw_name,
      confidence: alias.confidence,
      method: "alias",
    };
  }

  // Step 3: HSN-scoped fuzzy match
  if (hsn) {
    const candidates = await listCanonicalProductsByHsn(siteId, hsn);
    if (candidates.length > 0) {
      let bestMatch: CanonicalProduct | null = null;
      let bestScore = 0;

      for (const candidate of candidates) {
        const score = fuzzyScore(name, candidate.canonical_name);
        if (score > bestScore) {
          bestScore = score;
          bestMatch = candidate;
        }
      }

      if (bestMatch && bestScore >= 0.6) {
        // Learn this alias for next time
        await saveProductAlias({
          id: `pa_${nanoid(12)}`,
          siteId,
          rawName: name,
          productId: bestMatch.product_id,
          hsnCode: hsn,
          confidence: bestScore,
          source: "hsn_fuzzy",
        });

        return {
          matched: true,
          productId: bestMatch.product_id,
          canonicalName: bestMatch.canonical_name,
          confidence: bestScore,
          method: "hsn_fuzzy",
        };
      }
    }
  }

  // Step 4: LLM normalization
  try {
    const normalized = await normalizeProductName({ siteId, rawName: name });
    if (normalized.confidence >= 0.7) {
      const product = await findCanonicalProductByName(
        siteId,
        normalized.canonical,
      );
      if (product) {
        // Learn alias
        await saveProductAlias({
          id: `pa_${nanoid(12)}`,
          siteId,
          rawName: name,
