        return {
          matched: true,
          productId: product.product_id,
          canonicalName: product.canonical_name,
          confidence: normalized.confidence,
          method: "normalized",
        };
      }
    }
  } catch {
    // LLM failed — fall through to unresolved
  }

  // Step 5: Unresolved
  return {
    matched: false,
    productId: null,
    canonicalName: name,
    confidence: 0,
    method: "unresolved",
  };
}

