// ── Admin: Bill extract (no DB writes) ──────────────────────
// Returns OCR-extracted items + suggested catalog matches per item.
// The admin reviews, edits, and validates before anything is committed.
if (
  (pathname === "/api/inventory/bills/extract" ||
    pathname === "/api/inventory/bills") && // back-compat
  method === "POST"
) {
  const auth = await authenticate(req, res);
  if (!auth) return true;
  const body = await readBodyJson(req);

  const imageSource = asString(body.image) ?? asString(body.image_url);
  if (!imageSource) {
    json(res, 400, { error: "image (base64) or image_url is required" });
    return true;
  }
  const mimeType = asString(body.mime_type) ?? "image/jpeg";

  const extraction = await extractBillFromImage(imageSource, mimeType);
  if (!extraction.success || !extraction.bill) {
    json(res, 422, { error: extraction.error ?? "Bill extraction failed" });
    return true;
  }

  // Per-line suggestions — no writes.
  const items = await Promise.all(
    extraction.bill.line_items.map(async (line, idx) => ({
      tempId: `t_${idx}`,
      bill_item_name: line.item_purchased,
      hsn_code: line.hsn_code,
      qty: line.qty,
      rate: line.rate,
      value: line.value,
      unit_hint: line.unit, // LLM's best guess; admin confirms
      suggestions: await suggestForBillLine(auth.siteId, line, 3),
    })),
  );

  json(res, 200, {
    bill: {
      vendor_name: extraction.bill.vendor_name,
      bill_number: extraction.bill.bill_number,
      bill_date: extraction.bill.bill_date,
      grand_total: extraction.bill.grand_total,
      tax_total: extraction.bill.tax_total,
    },
    items,
  });
  return true;
}

// ── Admin: Bill validate (writes order + canonicals + aliases) ──
if (pathname === "/api/inventory/bills/validate" && method === "POST") {
  const auth = await authenticate(req, res);
  if (!auth) return true;
  const body = await readBodyJson(req);
  const validated = body as unknown as ValidatedBill;
  if (!Array.isArray(validated.items) || validated.items.length === 0) {
    json(res, 400, { error: "items[] required" });
    return true;
  }

  const result = await processValidatedBill(auth.siteId, auth.guardName, validated);

  // Push every committed item to the "Ordered" tab.
  void Promise.all(
    result.committed.map((c) =>
      appendToSheetDirect("Ordered", [
        new Date().toISOString().slice(0, 10),
        validated.bill_number ?? "",
        validated.vendor_name ?? "",
        c.billItemName ?? "",
        c.canonicalName,
        c.hsnCode ?? "",
        c.unit,
        String(c.packSize),
        String(c.qty),
        c.rate != null ? String(c.rate) : "",
        c.value != null ? String(c.value) : "",
        auth.guardName,
      ]),
    ),
  ).catch((err) =>
    logError("[Inventory] Ordered sheet append failed", err, { scope: "inventory.sheets" }),
  );

  json(res, 200, { orderId: result.orderId, committed: result.committed.length });
  return true;
}

