// ───────────────────────── Bill Upload ─────────────────────────

type ReviewRow = {
  tempId: string;
  bill_item_name: string;       // original from OCR (kept for alias)
  // editable fields
  canonical_name: string;
  hsn_code: string;
  qty: number;
  rate: number | null;
  value: number | null;
  unit: string;
  pack_size: number;
  // resolution
  action: "use_existing" | "create_new";
  product_id: string | null;
  suggestions: BillSuggestion[];
};

const UNIT_OPTIONS = ["pcs", "kg", "g", "l", "ml", "pack"];

function BillUploadTab({ goToTab }: { goToTab: (t: TabKey) => void }) {
  const queryClient = useQueryClient();
  const [file, setFile] = useState<File | null>(null);
  const [preview, setPreview] = useState<string | null>(null);
  const [billMeta, setBillMeta] = useState<BillExtractResult["bill"] | null>(null);
  const [rows, setRows] = useState<ReviewRow[]>([]);

  const extractMutation = useMutation({
    mutationFn: async (f: File) => {
      const image = await fileToBase64(f);
      return extractBill({ image, mime_type: f.type || "image/jpeg" });
    },
    onSuccess: (res) => {
      if (!res.ok) {
        toastError(errorMessage((res.data as { error?: string }).error, "Bill extract failed"));
        return;
      }
      setBillMeta(res.data.bill);
      setRows(res.data.items.map(itemToRow));
    },
    onError: (err) => toastError(err, "Bill extract failed"),
  });

  const validateMutation = useMutation({
    mutationFn: () => {
      if (!billMeta) throw new Error("No bill to validate");
      return validateBill({
        vendor_name: billMeta.vendor_name,
        bill_number: billMeta.bill_number,
        bill_date: billMeta.bill_date,
        grand_total: billMeta.grand_total,
        items: rows.map((r) => ({
          action: r.action,
          product_id: r.product_id,
          canonical_name: r.canonical_name.trim(),
          hsn_code: r.hsn_code || null,
          unit: r.unit,
          pack_size: r.pack_size,
          qty: r.qty,
          rate: r.rate,
          value: r.value,
          bill_item_name: r.bill_item_name,
        })),
      });
    },
    onSuccess: (res) => {
      if (!res.ok) { toastError(errorMessage((res.data as { error?: string }).error, "Validate failed")); return; }
      toastSuccess("Order created", `${res.data.committed} item(s) added`);
      setFile(null);
      setPreview(null);
      setBillMeta(null);
      setRows([]);
      void queryClient.invalidateQueries({ queryKey: ["inv-canonical"] });
    },
    onError: (err) => toastError(err, "Validate failed"),
  });

  function onFile(f: File | null) {
    setFile(f);
    setBillMeta(null);
    setRows([]);
    if (!f) { setPreview(null); return; }
    setPreview(URL.createObjectURL(f));
  }

  function patchRow(tempId: string, patch: Partial<ReviewRow>) {
    setRows((rs) => rs.map((r) => (r.tempId === tempId ? { ...r, ...patch } : r)));
  }

  function removeRow(tempId: string) {
    setRows((rs) => rs.filter((r) => r.tempId !== tempId));
  }

  function acceptSuggestion(tempId: string, s: BillSuggestion) {
    patchRow(tempId, {
      action: "use_existing",
      product_id: s.productId,
      canonical_name: s.canonicalName,
      unit: s.unit,
      pack_size: s.packSize,
      hsn_code: s.hsnCode ?? "",
    });
  }

  const extracted = billMeta !== null;

  return (
    <div>
      {!extracted && (
        <div style={{ display: "grid", gap: 16, gridTemplateColumns: "1fr 1fr" }}>
          <div>
            <label
              htmlFor="bill-file"
              style={{
                display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center",
                minHeight: 220, border: "1.5px dashed var(--line)", borderRadius: 10, padding: 24,
                cursor: "pointer", background: "var(--surface, #fafafa)",
              }}
            >
              {preview ? (
                file?.type === "application/pdf" ? (
                  <object data={preview} type="application/pdf" style={{ width: "100%", height: 200, borderRadius: 6 }}>
                    <div style={{ fontSize: 13 }}>{file?.name}</div>
                  </object>
                ) : (
                  <img src={preview} alt="Bill preview" style={{ maxHeight: 200, maxWidth: "100%", borderRadius: 6 }} />
                )
              ) : (
                <>
                  <Upload size={28} />
                  <div style={{ marginTop: 8, fontWeight: 600 }}>Click to upload bill</div>
                  <div style={{ fontSize: 12, color: "var(--muted)", marginTop: 4 }}>JPG / PNG / WEBP / PDF up to ~10 MB</div>
                </>
              )}
              <input
                id="bill-file"
                type="file"
                accept="image/*,application/pdf"
                style={{ display: "none" }}
                onChange={(e) => onFile(e.target.files?.[0] ?? null)}
              />
            </label>
            <div style={{ display: "flex", gap: 8, marginTop: 12 }}>
              <button
                type="button"
                className="primary-button"
                disabled={!file || extractMutation.isPending}
                onClick={() => file && extractMutation.mutate(file)}
              >
                {extractMutation.isPending ? "Extracting…" : "Extract items"}
              </button>
              {file && (
                <button type="button" onClick={() => onFile(null)} style={ghostBtn}>
                  Clear
                </button>
              )}
            </div>
          </div>

          <div>
            <div style={{ color: "var(--muted)", fontSize: 13 }}>
              Step 1: upload the bill. We'll OCR + LLM-extract every line item and propose catalog matches.
              <br /><br />
              Step 2: you review the editable list, correct names/HSN/qty/rate, set the unit + pack size, then
              accept or override the suggested catalog match. Items with no match register as new products on save.
              <br /><br />
              Step 3: <b>Validate</b> commits the order. Field-app guards then see these as expected deliveries.
            </div>
          </div>
        </div>
      )}

      {extracted && billMeta && (
        <div>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-end", marginBottom: 12, gap: 10, flexWrap: "wrap" }}>
            <div>
              <div style={{ fontSize: 12, color: "var(--muted)", textTransform: "uppercase", letterSpacing: 0.5 }}>Review extracted bill</div>
              <div style={{ display: "flex", gap: 16, marginTop: 4, fontSize: 13 }}>
                <BillField label="Vendor" value={billMeta.vendor_name} onChange={(v) => setBillMeta({ ...billMeta, vendor_name: v })} />
                <BillField label="Bill #" value={billMeta.bill_number} onChange={(v) => setBillMeta({ ...billMeta, bill_number: v })} />
                <BillField label="Date" value={billMeta.bill_date} onChange={(v) => setBillMeta({ ...billMeta, bill_date: v })} type="date" />
              </div>
            </div>
            <div style={{ display: "flex", gap: 8 }}>
              <button type="button" onClick={() => { setBillMeta(null); setRows([]); }} style={ghostBtn}>
                Discard
              </button>
              <button
                type="button"
                className="primary-button"
                disabled={rows.length === 0 || validateMutation.isPending}
                onClick={() => validateMutation.mutate()}
              >
                {validateMutation.isPending ? "Saving…" : `Validate & save (${rows.length})`}
              </button>
            </div>
          </div>

          <div style={{ display: "grid", gap: 10 }}>
            {rows.map((r) => (
              <ReviewRowCard
                key={r.tempId}
                row={r}
                onChange={(patch) => patchRow(r.tempId, patch)}
                onAcceptSuggestion={(s) => acceptSuggestion(r.tempId, s)}
                onRemove={() => removeRow(r.tempId)}
              />
            ))}
            {rows.length === 0 && (
              <div style={{ padding: 14, border: "1px dashed var(--line)", borderRadius: 8, color: "var(--muted)", fontSize: 13, textAlign: "center" }}>
                All rows removed. Discard and re-upload, or go to <button type="button" onClick={() => goToTab("products")} style={linkBtn}>Catalog</button>.
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

function itemToRow(it: BillExtractItem): ReviewRow {
  // If there's a strong suggestion (>= 0.85), pre-fill action=use_existing
  const top = it.suggestions[0];
  const useTop = top && top.score >= 0.85;
  return {
    tempId: it.tempId,
    bill_item_name: it.bill_item_name,
    canonical_name: useTop ? top.canonicalName : it.bill_item_name,
    hsn_code: it.hsn_code ?? top?.hsnCode ?? "",
    qty: it.qty,
    rate: it.rate,
    value: it.value,
    unit: useTop ? top.unit : (it.unit_hint && UNIT_OPTIONS.includes(it.unit_hint) ? it.unit_hint : "pcs"),
    pack_size: useTop ? top.packSize : 1,
    action: useTop ? "use_existing" : "create_new",
    product_id: useTop ? top.productId : null,
    suggestions: it.suggestions,
  };
}

function BillField({
  label, value, onChange, type = "text",
}: { label: string; value: string | null; onChange: (v: string | null) => void; type?: string }) {
  return (
    <label style={{ display: "grid", gap: 2 }}>
      <span style={{ fontSize: 10, color: "var(--muted)", textTransform: "uppercase", letterSpacing: 0.5 }}>{label}</span>
      <input
        type={type}
        value={value ?? ""}
        onChange={(e) => onChange(e.target.value || null)}
        style={{ ...input, fontSize: 13, padding: "4px 8px", minWidth: 120 }}
      />
    </label>
  );
}

function ReviewRowCard({
  row, onChange, onAcceptSuggestion, onRemove,
}: {
  row: ReviewRow;
  onChange: (patch: Partial<ReviewRow>) => void;
  onAcceptSuggestion: (s: BillSuggestion) => void;
  onRemove: () => void;
}) {
  const top = row.suggestions[0];
  const isUsingExisting = row.action === "use_existing" && row.product_id;
  return (
    <div style={{ border: "1px solid var(--line)", borderRadius: 10, padding: 12 }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 8 }}>
        <div style={{ fontSize: 11, color: "var(--muted)" }}>
          From bill: <b>{row.bill_item_name}</b>
        </div>
        <div style={{ display: "flex", gap: 6, alignItems: "center" }}>
          {isUsingExisting ? (
            <Pill ok>Mapped to catalog</Pill>
          ) : (
            <Pill warn>Will register as new</Pill>
          )}
          <button type="button" onClick={onRemove} style={{ ...ghostBtn, padding: "4px 8px", fontSize: 11 }}>Remove</button>
        </div>
      </div>

      <div style={{ display: "grid", gap: 8, gridTemplateColumns: "2fr 1fr 1fr 1fr 1fr 1fr", alignItems: "end" }}>
        <FieldLabel label="Canonical name">
          <input
            type="text"
            value={row.canonical_name}
            onChange={(e) => onChange({ canonical_name: e.target.value, action: "create_new", product_id: null })}
            style={input}
          />
        </FieldLabel>
        <FieldLabel label="HSN">
          <input type="text" value={row.hsn_code} onChange={(e) => onChange({ hsn_code: e.target.value })} style={input} />
        </FieldLabel>
        <FieldLabel label="Qty">
          <input type="number" step="any" value={row.qty} onChange={(e) => onChange({ qty: Number(e.target.value) || 0 })} style={input} />
        </FieldLabel>
        <FieldLabel label="Rate (₹)">
          <input type="number" step="any" value={row.rate ?? ""} onChange={(e) => onChange({ rate: e.target.value === "" ? null : Number(e.target.value) })} style={input} />
        </FieldLabel>
        <FieldLabel label="Unit">
          <select value={row.unit} onChange={(e) => onChange({ unit: e.target.value })} style={input}>
            {UNIT_OPTIONS.map((u) => <option key={u} value={u}>{u}</option>)}
          </select>
        </FieldLabel>
        <FieldLabel label="Pack size">
          <input type="number" step="any" value={row.pack_size} onChange={(e) => onChange({ pack_size: Number(e.target.value) || 1 })} style={input} />
        </FieldLabel>
      </div>

      {row.suggestions.length > 0 && (
        <div style={{ marginTop: 10 }}>
          <div style={{ fontSize: 11, color: "var(--muted)", marginBottom: 4 }}>Catalog suggestions:</div>
          <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
            {row.suggestions.map((s) => {
              const active = row.product_id === s.productId;
              return (
                <button
                  key={s.productId}
                  type="button"
                  onClick={() => onAcceptSuggestion(s)}
                  style={{
                    border: "1px solid var(--line)",
                    borderRadius: 6,
                    padding: "6px 10px",
                    background: active ? "var(--text)" : "transparent",
                    color: active ? "var(--surface, #fff)" : "var(--text)",
                    cursor: "pointer",
                    fontSize: 12,
                    display: "inline-flex",
                    gap: 6,
                    alignItems: "center",
                  }}
                >
                  {active && <Check size={12} />}
                  <span style={{ fontWeight: 600 }}>{s.canonicalName}</span>
                  <span style={{ opacity: 0.8 }}>· {s.packSize} {s.unit}</span>
                  <span style={{ opacity: 0.7 }}>· {Math.round(s.score * 100)}% {s.method}</span>
                </button>
              );
            })}
            <button
              type="button"
              onClick={() => onChange({ action: "create_new", product_id: null })}
              style={{
                border: "1px dashed var(--line)",
                borderRadius: 6,
                padding: "6px 10px",
                background: row.action === "create_new" ? "var(--text)" : "transparent",
                color: row.action === "create_new" ? "var(--surface, #fff)" : "var(--muted)",
                cursor: "pointer",
                fontSize: 12,
              }}
            >
              {top ? "None — register new" : "Register as new product"}
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

