            file?.type === "application/pdf" ? (
              <object data={preview} type="application/pdf" style={{ width: "100%", height: 200, borderRadius: 6 }}>
                <div style={{ fontSize: 13 }}>{file?.name}</div>
              </object>
            ) : (
              <img src={preview} alt="Bill preview" style={{ maxHeight: 200, maxWidth: "100%", borderRadius: 6 }} />
            )
          ) : (
            <>
              <Upload size={28} />
              <div style={{ marginTop: 8, fontWeight: 600 }}>Click to upload bill</div>
              <div style={{ fontSize: 12, color: "var(--muted)", marginTop: 4 }}>JPG / PNG / WEBP / PDF up to ~10 MB</div>
            </>
          )}
          <input
            id="bill-file"
            type="file"
            accept="image/*,application/pdf"
            style={{ display: "none" }}
            onChange={(e) => onFile(e.target.files?.[0] ?? null)}
          />
        </label>
        <div style={{ display: "flex", gap: 8, marginTop: 12 }}>
          <button
            type="button"
            className="primary-button"
            disabled={!file || uploadMutation.isPending}
            onClick={() => file && uploadMutation.mutate(file)}
          >
            {uploadMutation.isPending ? "Processing…" : "Extract & match"}
          </button>
          {file && (
            <button type="button" onClick={() => onFile(null)} style={ghostBtn}>
              Clear
            </button>
          )}
        </div>
      </div>

      <div>
        {!result && (
          <div style={{ color: "var(--muted)", fontSize: 13 }}>
            Upload a vendor bill and we'll OCR + LLM-extract the line items, then auto-match each to the canonical
            catalog. Matched items go into the order silently. Only items that <b>don't</b> match any existing mapping
            land in <b>Unresolved</b> for you to resolve.
          </div>
        )}
        {result && (() => {
          const unresolvedMatches = result.matches.filter((m) => !m.matched);
          return (
            <div>
              <div style={{ fontWeight: 600, marginBottom: 8 }}>
                {result.bill.vendor ?? "Vendor"} · {result.bill.bill_number ?? "—"} · {result.bill.bill_date ?? "—"}
              </div>
              <div style={{ display: "flex", gap: 8, marginBottom: 10 }}>
                <Pill ok>{result.summary?.matched ?? 0} auto-matched</Pill>
                <Pill warn>{unresolvedMatches.length} need attention</Pill>
