              {unresolvedMatches.length === 0 ? (
                <div style={{ padding: 14, border: "1px solid var(--line)", borderRadius: 8, color: "var(--muted)", fontSize: 13 }}>
                  Every line item matched an existing product. Nothing to resolve.
                </div>
              ) : (
                <>
                  <div style={{ fontSize: 12, color: "var(--muted)", marginBottom: 6 }}>Items that need your attention:</div>
                  <div style={{ display: "grid", gap: 6 }}>
                    {unresolvedMatches.map((m, i) => (
                      <div key={i} style={billRow}>
                        <div>
                          <div style={{ fontWeight: 600, fontSize: 13 }}>{m.item}</div>
                          <div style={{ fontSize: 12, color: "var(--muted)" }}>
                            HSN {m.hsn ?? "—"} · qty {m.qty} · ₹{m.rate ?? "—"}
                          </div>
                        </div>
                        <span style={{ color: "#dc2626", fontSize: 12 }}>Unresolved</span>
                      </div>
                    ))}
                  </div>
                  <div style={{ marginTop: 12 }}>
                    <button type="button" className="primary-button" onClick={() => goToTab("unresolved")}>
                      Resolve {unresolvedMatches.length} item{unresolvedMatches.length === 1 ? "" : "s"} →
                    </button>
                  </div>
                </>
              )}
            </div>
          );
        })()}
      </div>
    </div>
  );
}

