// ─── Auth ─────────────────────────────────────────────────

let _sheetsClient: sheets_v4.Sheets | null = null;

async function getSheetsClient(): Promise<sheets_v4.Sheets | null> {
  if (_sheetsClient) return _sheetsClient;

  const config = getConfig();
  if (!config) {
    console.warn('⚠️ [Sheets] GOOGLE_SHEETS_ID or GOOGLE_SERVICE_ACCOUNT_KEY_PATH not set — export disabled');
    return null;
  }

  try {
    let keyFile: Record<string, unknown>;
    if (config.keyJson) {
      keyFile = JSON.parse(Buffer.from(config.keyJson, 'base64').toString('utf-8'));
    } else {
      keyFile = JSON.parse(readFileSync(config.keyPath!, 'utf-8'));
    }
    const auth = new google.auth.GoogleAuth({
      credentials: keyFile,
      scopes: ['https://www.googleapis.com/auth/spreadsheets'],
    });

    _sheetsClient = google.sheets({ version: 'v4', auth });
    return _sheetsClient;
  } catch (error) {
    console.error('❌ [Sheets] Auth failed:', error);
    return null;
  }
}

// ─── Helpers ──────────────────────────────────────────────

/**
 * Build a Telegram deep-link URL from chat ID and message ID.
 */
function buildTelegramLink(chatId: unknown, msgId: unknown): string {
  if (!chatId || !msgId) return '';
  const absId = Math.abs(Number(chatId));
  const idStr = String(absId);
  const cleanId = idStr.startsWith('100') && idStr.length > 10 ? idStr.slice(3) : idStr;
  return `https://t.me/c/${cleanId}/${msgId}`;
}

function formatSheetRange(sheetTitle: string, range: string): string {
  const escapedTitle = sheetTitle.replace(/'/g, "''");
  return `'${escapedTitle}'!${range}`;
}

