// ── Compliance Google Sheet integration ──────────────────────
//   GET  /api/inventory/compliance/sheet-info — does Sheets work?
//   POST /api/inventory/compliance/sheet-sync — push all rows now
if (
  pathname === "/api/inventory/compliance/sheet-info" &&
  method === "GET"
) {
  const auth = await authenticate(req, res);
  if (!auth) return true;
  const spreadsheetId = process.env.GOOGLE_SHEETS_ID ?? null;
  const configured = Boolean(
    spreadsheetId &&
      (process.env.GOOGLE_SERVICE_ACCOUNT_KEY_JSON ||
        process.env.GOOGLE_SERVICE_ACCOUNT_KEY_PATH),
  );
  json(res, 200, {
    configured,
    spreadsheetId,
    url: spreadsheetId
      ? `https://docs.google.com/spreadsheets/d/${spreadsheetId}/edit`
      : null,
    tabs: ["Ordered", "Received"],
  });
  return true;
}

if (
  pathname === "/api/inventory/compliance/sheet-sync" &&
  method === "POST"
) {
  const auth = await authenticate(req, res);
  if (!auth) return true;
  const body = await readBodyJson(req);
  const from = asString(body.from);
  const to = asString(body.to);
  const rows = await listComplianceLog(auth.siteId, from, to);
  let appended = 0;
  let failed = 0;
  for (const r of rows) {
    try {
      await appendToSheetDirect("Received", complianceRowToSheetValues(r));
      appended++;
    } catch (err) {
      logError("[Inventory] sheet sync row failed", err, { scope: "inventory.sheets" });
      failed++;
    }
  }
  json(res, 200, { appended, failed, total: rows.length });
  return true;
}

