// ── Google Sheet attach / detach (per-site) ─────────────────
//   GET    /api/inventory/sheet              — current attached sheet
//   POST   /api/inventory/sheet  { url|id }  — attach
//   DELETE /api/inventory/sheet              — detach
//   POST   /api/inventory/sheet/sync         — backfill range to Received
if (pathname === "/api/inventory/sheet" && method === "GET") {
  const auth = await authenticate(req, res);
  if (!auth) return true;
  const spreadsheetId = await getSetting(auth.siteId, SHEET_ID_KEY);
  const credentialsAvailable = Boolean(
    process.env.GOOGLE_SERVICE_ACCOUNT_KEY_JSON ||
      process.env.GOOGLE_SERVICE_ACCOUNT_KEY_PATH,
  );
  json(res, 200, {
    attached: Boolean(spreadsheetId),
    spreadsheetId,
    url: spreadsheetId
      ? `https://docs.google.com/spreadsheets/d/${spreadsheetId}/edit`
      : null,
    credentialsAvailable,
    tabs: ["Ordered", "Received"],
  });
  return true;
}

if (pathname === "/api/inventory/sheet" && method === "POST") {
  const auth = await authenticate(req, res);
  if (!auth) return true;
  const body = await readBodyJson(req);
  const raw = asString(body.url) ?? asString(body.spreadsheet_id) ?? asString(body.id);
  if (!raw) {
    json(res, 400, { error: "url or spreadsheet_id is required" });
    return true;
  }
  // Accept either a full sheet URL or a bare id.
  // URL formats: https://docs.google.com/spreadsheets/d/<ID>/edit#...
  const match = raw.match(/\/spreadsheets\/d\/([a-zA-Z0-9_-]+)/);
  const spreadsheetId = match ? match[1] : raw.trim();
  if (!/^[a-zA-Z0-9_-]{20,}$/.test(spreadsheetId)) {
    json(res, 400, { error: "Could not parse a valid Google Sheet ID from input" });
    return true;
  }

  const verification = await verifySpreadsheetAccess(spreadsheetId);
  if (!verification.ok) {
    json(res, 400, {
      error:
        verification.error?.includes("not configured")
          ? "Server's Google service-account credentials are not configured."
          : `Cannot access this sheet. Share it with the service account first. (${verification.error})`,
    });
    return true;
  }

  await setSetting(auth.siteId, SHEET_ID_KEY, spreadsheetId);
  json(res, 200, {
    attached: true,
    spreadsheetId,
    title: verification.title ?? null,
    url: `https://docs.google.com/spreadsheets/d/${spreadsheetId}/edit`,
  });
  return true;
}

if (pathname === "/api/inventory/sheet" && method === "DELETE") {
  const auth = await authenticate(req, res);
  if (!auth) return true;
  await deleteSetting(auth.siteId, SHEET_ID_KEY);
  json(res, 200, { attached: false });
  return true;
}

if (pathname === "/api/inventory/sheet/sync" && method === "POST") {
  const auth = await authenticate(req, res);
  if (!auth) return true;
  const spreadsheetId = await getSetting(auth.siteId, SHEET_ID_KEY);
  if (!spreadsheetId) {
    json(res, 400, { error: "No Google Sheet attached for this site" });
    return true;
  }
  const body = await readBodyJson(req);
  const from = asString(body.from);
  const to = asString(body.to);
  const rows = await listComplianceLog(auth.siteId, from, to);
  let appended = 0;
  let failed = 0;
  for (const r of rows) {
    try {
      await appendInventoryRow(
        spreadsheetId,
        "Received",
        INVENTORY_SHEET_HEADERS.Received,
        complianceRowToSheetValues(r),
      );
      appended++;
    } catch (err) {
      logError("[Inventory] sheet sync row failed", err, { scope: "inventory.sheets" });
      failed++;
    }
  }
  json(res, 200, { appended, failed, total: rows.length });
  return true;
}

