function ComplianceTab() {
  const today = new Date().toISOString().slice(0, 10);
  const monthAgo = new Date(Date.now() - 30 * 86400_000).toISOString().slice(0, 10);
  const [from, setFrom] = useState(monthAgo);
  const [to, setTo] = useState(today);

  const query = useQuery({
    queryKey: ["inv-compliance", from, to],
    queryFn: () => listCompliance({ from: from || undefined, to: to ? `${to}T23:59:59` : undefined }),
  });
  const sheetQuery = useQuery({ queryKey: ["inv-sheet-info"], queryFn: getSheetInfo });
  const sheetInfo = sheetQuery.data?.data;

  const rows: ComplianceLogRow[] = query.data?.data?.rows ?? [];

  const syncMutation = useMutation({
    mutationFn: () => syncSheet({ from: from || undefined, to: to ? `${to}T23:59:59` : undefined }),
    onSuccess: (res) => {
      if (!res.ok) { toastError(errorMessage((res.data as { error?: string }).error, "Sync failed")); return; }
      toastSuccess(`Pushed ${res.data.appended} of ${res.data.total} rows to Google Sheet`);
    },
    onError: (err) => toastError(err, "Sync failed"),
  });

  return (
    <div>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 12, gap: 10, flexWrap: "wrap", padding: 12, border: "1px solid var(--line)", borderRadius: 8 }}>
        <div>
          <div style={{ fontWeight: 600, marginBottom: 2 }}>Linked Google Sheet</div>
          {sheetInfo?.configured ? (
            <div style={{ fontSize: 12, color: "var(--muted)" }}>
              Tabs: <b>{sheetInfo.tabs.join(", ")}</b> · Validated bills append to <b>Ordered</b>;
              every received item appends to <b>Received</b>.
            </div>
          ) : (
            <div style={{ fontSize: 12, color: "#b45309" }}>
              Not configured. Set <code>GOOGLE_SHEETS_ID</code> + Google service-account env vars on the backend.
            </div>
          )}
        </div>
        <div style={{ display: "flex", gap: 8 }}>
          {sheetInfo?.url && (
            <a href={sheetInfo.url} target="_blank" rel="noreferrer" style={{ ...ghostBtn, textDecoration: "none" }}>
              Open sheet ↗
            </a>
          )}
          <button
            type="button"
            className="primary-button"
            disabled={!sheetInfo?.configured || syncMutation.isPending}
            onClick={() => syncMutation.mutate()}
          >
            {syncMutation.isPending ? "Syncing…" : "Sync range to sheet"}
          </button>
        </div>
      </div>

