function SheetConfigCard({ onSyncRange, syncing }: { onSyncRange: () => void; syncing: boolean }) {
  const queryClient = useQueryClient();
  const sheetQuery = useQuery({ queryKey: ["inv-sheet-info"], queryFn: getSheetInfo });
  const sheetInfo = sheetQuery.data?.data;
  const [input, setInputVal] = useState("");

  const attachMutation = useMutation({
    mutationFn: (urlOrId: string) => attachSheet(urlOrId),
    onSuccess: (res) => {
      if (!res.ok) { toastError(errorMessage((res.data as { error?: string }).error, "Attach failed")); return; }
      toastSuccess(`Attached ${res.data.title ?? "sheet"}`);
      setInputVal("");
      void queryClient.invalidateQueries({ queryKey: ["inv-sheet-info"] });
    },
    onError: (err) => toastError(err, "Attach failed"),
  });

  const detachMutation = useMutation({
    mutationFn: detachSheet,
    onSuccess: () => {
      toastSuccess("Sheet detached");
      void queryClient.invalidateQueries({ queryKey: ["inv-sheet-info"] });
    },
    onError: (err) => toastError(err, "Detach failed"),
  });

