async function getUserRow(adminEmail: string) {
  const db = getOptionalPostgresDb();
  if (!db) throw new Error("Database is not configured.");

  const email = adminEmail.trim().toLowerCase();
  const rows = await db
    .select({
      email: users.email,
      googleRefreshToken: users.googleRefreshToken,
      bulkInviteSpreadsheetId: users.bulkInviteSpreadsheetId,
      bulkInviteSheetName: users.bulkInviteSheetName,
    })
    .from(users)
    .where(eq(users.email, email))
    .limit(1);

  const row = rows[0];
  if (!row) throw new Error("Admin user was not found.");
  return row;
}

async function getSheetsClient(adminEmail: string): Promise<sheets_v4.Sheets> {
  const row = await getUserRow(adminEmail);
  if (!row.googleRefreshToken) {
    throw new Error("Please sign in with Google again so Sheets access can be granted.");
  }

  return google.sheets({
    version: "v4",
    auth: buildOAuthClientWithRefreshToken(row.googleRefreshToken),
  });
}

async function ensureSheetTab(
  sheets: sheets_v4.Sheets,
  spreadsheetId: string,
  sheetName: string,
): Promise<void> {
  const meta = await sheets.spreadsheets.get({ spreadsheetId });
  const exists = meta.data.sheets?.some((sheet) => sheet.properties?.title === sheetName);
  if (exists) return;

  await sheets.spreadsheets.batchUpdate({
    spreadsheetId,
    requestBody: {
      requests: [{ addSheet: { properties: { title: sheetName } } }],
    },
  });
}

