/**
 * Append a single row to a specific spreadsheet + tab. Auto-creates the
 * tab and auto-writes headers on first use. Unlike `appendToSheetDirect`
 * this takes the spreadsheetId from the caller (used for per-site
 * attached sheets stored in `inventory_settings`).
 */
export async function appendInventoryRow(
  spreadsheetId: string,
  tabName: string,
  headers: string[],
  rowData: string[],
): Promise<void> {
  const sheets = await getAuthOnlySheetsClient();
  if (!sheets) throw new Error('Google service-account credentials not configured');

  await ensureSheet(sheets, spreadsheetId, tabName);

  try {
    const headerCheck = await sheets.spreadsheets.values.get({
      spreadsheetId,
      range: formatSheetRange(tabName, 'A1:A1'),
    });
    const hasHeaders = (headerCheck.data.values?.[0]?.length ?? 0) > 0;
    if (!hasHeaders) {
      await sheets.spreadsheets.values.update({
        spreadsheetId,
        range: formatSheetRange(tabName, 'A1'),
        valueInputOption: 'USER_ENTERED',
        requestBody: { values: [headers] },
      });
    }
  } catch {
    // non-critical
  }

  await sheets.spreadsheets.values.append({
    spreadsheetId,
    range: formatSheetRange(tabName, 'A:A'),
    valueInputOption: 'USER_ENTERED',
    insertDataOption: 'INSERT_ROWS',
    requestBody: { values: [rowData] },
  });
}

/**
 * Verify the caller has access to a spreadsheet — used by the dashboard
 * "Attach" button to confirm the URL is valid before saving the id.
 */
export async function verifySpreadsheetAccess(
  spreadsheetId: string,
): Promise<{ ok: boolean; title?: string; error?: string }> {
  const sheets = await getAuthOnlySheetsClient();
  if (!sheets) return { ok: false, error: 'service-account credentials not configured' };
  try {
    const meta = await sheets.spreadsheets.get({ spreadsheetId });
    return { ok: true, title: meta.data.properties?.title ?? undefined };
  } catch (err) {
    return {
      ok: false,
      error: err instanceof Error ? err.message : String(err),
    };
  }
}

