const SHEET_ID_KEY = "google_sheet_id";
const SHEET_OWNER_KEY = "google_sheet_owner_email";

/**
 * Build a Sheets API client authorized as the given admin user, using
 * their stored Google OAuth refresh token. Returns null if the user
 * has no Google token on file — caller decides whether that's an error.
 */
async function getAdminSheetsClient(adminEmail: string) {
  const db = getOptionalPostgresDb();
  if (!db) return null;
  const rows = await db
    .select({ refresh: users.googleRefreshToken })
    .from(users)
    .where(eq(users.email, adminEmail.trim().toLowerCase()))
    .limit(1);
  const refresh = rows[0]?.refresh ?? null;
  if (!refresh) return null;
  return google.sheets({
    version: "v4",
    auth: buildOAuthClientWithRefreshToken(refresh),
  });
}

async function appendComplianceRow(siteId: string, receiptId: string): Promise<void> {
  const [spreadsheetId, ownerEmail] = await Promise.all([
    getSetting(siteId, SHEET_ID_KEY),
    getSetting(siteId, SHEET_OWNER_KEY),
  ]);
  if (!spreadsheetId || !ownerEmail) return; // no sheet attached
  const sheets = await getAdminSheetsClient(ownerEmail);
  if (!sheets) return; // owner's Google token missing — silently skip
  const row = await getComplianceLogForReceipt(siteId, receiptId);
  if (!row) return;
  await appendInventoryRow(
    sheets,
    spreadsheetId,
    "Received",
    INVENTORY_SHEET_HEADERS.Received,
    complianceRowToSheetValues(row),
  );
}

