// ── Google Sheet attach / detach (per-site, admin's own OAuth) ──
//   GET    /api/inventory/sheet              — current attached sheet
//   POST   /api/inventory/sheet  { url|id }  — attach (uses caller's
//                                                Google OAuth token)
//   DELETE /api/inventory/sheet              — detach
//   POST   /api/inventory/sheet/sync         — backfill to Received
if (pathname === "/api/inventory/sheet" && method === "GET") {
  const auth = await authenticate(req, res);
  if (!auth) return true;
  const [spreadsheetId, ownerEmail] = await Promise.all([
    getSetting(auth.siteId, SHEET_ID_KEY),
    getSetting(auth.siteId, SHEET_OWNER_KEY),
  ]);
  let callerHasGoogleToken = false;
  if (auth.adminEmail) {
    const sheets = await getAdminSheetsClient(auth.adminEmail);
    callerHasGoogleToken = Boolean(sheets);
  }
  json(res, 200, {
    attached: Boolean(spreadsheetId),
    spreadsheetId,
    ownerEmail,
    url: spreadsheetId
      ? `https://docs.google.com/spreadsheets/d/${spreadsheetId}/edit`
      : null,
    googleSsoConfigured: isGoogleSsoConfigured(),
    callerHasGoogleToken,
    tabs: ["Ordered", "Received"],
  });
  return true;
}

if (pathname === "/api/inventory/sheet" && method === "POST") {
  const auth = await authenticate(req, res);
  if (!auth) return true;
  if (!auth.adminEmail) {
    json(res, 403, { error: "Only admins can attach a Google Sheet" });
    return true;
  }
  const body = await readBodyJson(req);
  const raw = asString(body.url) ?? asString(body.spreadsheet_id) ?? asString(body.id);
  if (!raw) {
    json(res, 400, { error: "url or spreadsheet_id is required" });
    return true;
  }
  const match = raw.match(/\/spreadsheets\/d\/([a-zA-Z0-9_-]+)/);
  const spreadsheetId: string = (match?.[1] ?? raw).trim();
  if (!/^[a-zA-Z0-9_-]{20,}$/.test(spreadsheetId)) {
    json(res, 400, { error: "Could not parse a valid Google Sheet ID from input" });
    return true;
  }

  const sheets = await getAdminSheetsClient(auth.adminEmail);
  if (!sheets) {
    json(res, 400, {
      error:
        "No Google account connected. Please sign in with Google (top-right) before attaching a sheet.",
    });
    return true;
  }

  const verification = await verifySpreadsheetAccess(sheets, spreadsheetId);
  if (!verification.ok) {
    json(res, 400, {
      error: `Cannot access this sheet with your Google account. Make sure you own it or have edit access. (${verification.error})`,
    });
    return true;
  }

