export async function findProductAlias(
  siteId: string,
  rawName: string,
  hsnCode?: string | null,
): Promise<ProductAlias | null> {
  const db = await getDb();
  // Try HSN-specific alias first, then generic (no HSN)
  if (hsnCode) {
    const specific = await db.execute({
      sql: `SELECT * FROM product_aliases WHERE site_id = ? AND lower(raw_name) = lower(?) AND hsn_code = ? LIMIT 1`,
      args: [siteId, rawName.trim(), hsnCode],
    });
    if (specific.rows[0]) return specific.rows[0] as ProductAlias;
  }
  const generic = await db.execute({
    sql: `SELECT * FROM product_aliases WHERE site_id = ? AND lower(raw_name) = lower(?) AND (hsn_code IS NULL OR hsn_code = '') LIMIT 1`,
    args: [siteId, rawName.trim()],
  });
  return (generic.rows[0] as ProductAlias | undefined) ?? null;
}

export async function saveProductAlias(input: {
  id: string;
  siteId: string;
  rawName: string;
  productId: string;
  hsnCode?: string | null;
  vendorName?: string | null;
  confidence?: number;
  source?: string;
}): Promise<void> {
  const db = await getDb();
  await db.execute({
    sql: `
      INSERT INTO product_aliases (id, site_id, raw_name, product_id, hsn_code, vendor_name, confidence, source)
      VALUES (?, ?, lower(?), ?, ?, ?, ?, ?)
      ON CONFLICT (site_id, raw_name, COALESCE(hsn_code, '')) DO UPDATE SET
        product_id = EXCLUDED.product_id,
        vendor_name = COALESCE(EXCLUDED.vendor_name, product_aliases.vendor_name),
        confidence = EXCLUDED.confidence,
        source = EXCLUDED.source
    `,
    args: [
      input.id,
      input.siteId,
      input.rawName.trim(),
      input.productId,
      input.hsnCode ?? null,
      input.vendorName ?? null,
      input.confidence ?? 1.0,

