function itemToRow(it: BillExtractItem): ReviewRow {
  // Always start from the bill's own values. Suggestions are shown
  // alongside as chips — the admin clicks one explicitly to map. We
  // never auto-apply a suggestion because the alias cache can carry
  // bad mappings from prior test runs, and silently overwriting the
  // extracted name has burned us.
  return {
    tempId: it.tempId,
    bill_item_name: it.bill_item_name,
    canonical_name: it.bill_item_name,
    hsn_code: it.hsn_code ?? "",
    qty: it.qty,
    rate: it.rate,
    value: it.value,
    unit:
      it.unit_hint && UNIT_OPTIONS.includes(it.unit_hint) ? it.unit_hint : "pcs",
    pack_size: 1,
    action: "create_new",
    product_id: null,
    suggestions: it.suggestions,
  };
}

