// ── Admin: Orders CRUD (all statuses, item-level edits) ────────
if (pathname === "/api/inventory/orders/full" && method === "GET") {
  const auth = await authenticate(req, res);
  if (!auth) return true;
  json(res, 200, { orders: await listOrdersWithItems(auth.siteId) });
  return true;
}

// /api/inventory/orders/:id  (DELETE | PATCH)
// /api/inventory/orders/:id/items  (POST — add item)
if (pathname.startsWith("/api/inventory/orders/")) {
  const auth = await authenticate(req, res);
  if (!auth) return true;
  if (!auth.adminEmail) {
    json(res, 403, { error: "Admin only" });
    return true;
  }
  const rest = pathname.replace("/api/inventory/orders/", "");
  const [orderId, sub] = rest.split("/");
  if (!orderId) {
    json(res, 400, { error: "missing order id" });
    return true;
  }

  if (!sub && method === "DELETE") {
    const r = await deleteOrder(auth.siteId, orderId);
    json(res, 200, r);
    return true;
  }
  if (!sub && method === "PATCH") {
    const body = await readBodyJson(req);
    await updateOrderMeta({
      orderId,
      siteId: auth.siteId,
      vendor: asString(body.vendor),
      billNumber: asString(body.bill_number),
      billDate: asString(body.bill_date),
    });
    json(res, 200, { updated: true });
    return true;
  }
  if (sub === "items" && method === "POST") {
    const body = await readBodyJson(req);
    const productId = asString(body.product_id);
    const productName = asString(body.product_name) ?? asString(body.canonical_name);
    const expectedQty = asNumber(body.qty) ?? asNumber(body.expected_qty);
    if (!productName || expectedQty === null) {
      json(res, 400, { error: "product_name and qty are required" });
      return true;
    }
    const { nanoid } = await import("nanoid");
    const itemId = `oi_${nanoid(12)}`;
    const { createOrderItemFromBill } = await import("./db");
    await createOrderItemFromBill({
      id: itemId,
      orderId,
      productId,
      productName,
      billItemName: asString(body.bill_item_name),
      hsnCode: asString(body.hsn_code),
      expectedQty,
      unitRate: asNumber(body.rate),
      lineValue: asNumber(body.value),
      matchMethod: productId ? "admin_added" : "admin_added_new",
      matchConfidence: 1.0,
    });
    json(res, 200, { id: itemId });
    return true;
  }
}

// /api/inventory/order-items/:id  (PATCH | DELETE)
if (pathname.startsWith("/api/inventory/order-items/")) {
  const auth = await authenticate(req, res);
  if (!auth) return true;
  if (!auth.adminEmail) {
    json(res, 403, { error: "Admin only" });
    return true;
  }
  const itemId = pathname.replace("/api/inventory/order-items/", "");
  if (!itemId) {
    json(res, 400, { error: "missing item id" });
    return true;
  }
  if (method === "DELETE") {
    const r = await deleteOrderItem(itemId);
    json(res, 200, r);
    return true;
  }
  if (method === "PATCH") {
    const body = await readBodyJson(req);
    await updateOrderItem({
      itemId,
      productId: asString(body.product_id),
      productName: asString(body.product_name) ?? asString(body.canonical_name),
      hsnCode: asString(body.hsn_code),
      expectedQty: asNumber(body.qty) ?? asNumber(body.expected_qty),
      unitRate: asNumber(body.rate) ?? asNumber(body.unit_rate),
    });
    json(res, 200, { updated: true });
    return true;
  }
}

