// ───────────────────────── Orders ─────────────────────────

function OrdersTab() {
  const queryClient = useQueryClient();
  const ordersQuery = useQuery({ queryKey: ["inv-orders"], queryFn: listOrders });
  const orders = ordersQuery.data?.data?.orders ?? [];

  const invalidate = () => {
    void queryClient.invalidateQueries({ queryKey: ["inv-orders"] });
  };

  const deleteOrderMutation = useMutation({
    mutationFn: deleteOrder,
    onSuccess: (res) => {
      if (!res.ok) { toastError(errorMessage((res.data as { error?: string }).error, "Delete failed")); return; }
      toastSuccess("Order deleted");
      invalidate();
    },
    onError: (err) => toastError(err, "Delete failed"),
  });

  return (
    <div>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 10 }}>
        <div style={{ fontWeight: 600 }}>
          {orders.length} order{orders.length === 1 ? "" : "s"}
        </div>
        <button type="button" onClick={() => void ordersQuery.refetch()} style={ghostBtn}>
          <RefreshCw size={14} /> Refresh
        </button>
      </div>

      {ordersQuery.isLoading && <div style={{ color: "var(--muted)" }}>Loading…</div>}
      {!ordersQuery.isLoading && orders.length === 0 && (
        <div style={{ color: "var(--muted)", fontStyle: "italic", padding: 24, textAlign: "center" }}>
          No orders yet. Upload a bill from the <b>Upload bill</b> tab to create one.
        </div>
      )}

      <div style={{ display: "grid", gap: 10 }}>
        {orders.map((o) => (
          <OrderCard
            key={o.id}
            order={o}
            onChange={invalidate}
            onDelete={() => {
              if (confirm(`Delete this order (${o.bill_number ?? o.id})? Items will be removed too. Receipts already scanned stay in the audit log.`)) {
                deleteOrderMutation.mutate(o.id);
              }
            }}
          />
        ))}
      </div>
    </div>
  );
}

function OrderCard({ order, onChange, onDelete }: { order: OrderFull; onChange: () => void; onDelete: () => void }) {
  const [open, setOpen] = useState(false);
  const totalExpected = order.items.reduce((s, i) => s + (i.expected_qty || 0), 0);
  const totalReceived = order.items.reduce((s, i) => s + (i.received_qty || 0), 0);

  return (
    <div style={{ border: "1px solid var(--line)", borderRadius: 10, overflow: "hidden" }}>
      <div
        style={{ display: "flex", justifyContent: "space-between", alignItems: "center", padding: 12, gap: 10, cursor: "pointer", background: "var(--surface, #fafafa)" }}
        onClick={() => setOpen((v) => !v)}
      >
        <div style={{ display: "flex", alignItems: "center", gap: 8, flex: 1, minWidth: 0 }}>
          {open ? <ChevronDown size={16} /> : <ChevronRight size={16} />}
          <div style={{ minWidth: 0 }}>
            <div style={{ fontWeight: 600, fontSize: 13, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>
              {order.vendor ?? "Unknown vendor"} · {order.bill_number ?? "—"}
            </div>
            <div style={{ fontSize: 11, color: "var(--muted)" }}>
              {order.bill_date ?? "—"} · {order.items.length} item{order.items.length === 1 ? "" : "s"} · {totalReceived}/{totalExpected} received
            </div>
          </div>
        </div>
        <div style={{ display: "flex", gap: 6, alignItems: "center" }}>
          <Pill ok={order.status === "done"} warn={order.status === "partial"}>{order.status}</Pill>
          <button
            type="button"
            onClick={(e) => { e.stopPropagation(); onDelete(); }}
            style={{ ...ghostBtn, padding: "4px 8px", color: "#dc2626" }}
            title="Delete order"
          >
            <Trash2 size={14} />
          </button>
        </div>
      </div>

      {open && (
        <div style={{ padding: 12, borderTop: "1px solid var(--line)" }}>
          <OrderEditor order={order} onChange={onChange} />
        </div>
      )}
    </div>
  );
}

function OrderEditor({ order, onChange }: { order: OrderFull; onChange: () => void }) {
  const updateMetaMutation = useMutation({
    mutationFn: (patch: { vendor?: string; bill_number?: string; bill_date?: string }) => updateOrder(order.id, patch),
    onSuccess: (res) => {
      if (!res.ok) { toastError(errorMessage((res.data as { error?: string }).error, "Update failed")); return; }
      onChange();
    },
    onError: (err) => toastError(err, "Update failed"),
  });

  const [vendor, setVendor] = useState(order.vendor ?? "");
  const [billNumber, setBillNumber] = useState(order.bill_number ?? "");
  const [billDate, setBillDate] = useState(order.bill_date ?? "");

  return (
    <div>
      <div style={{ display: "grid", gap: 8, gridTemplateColumns: "2fr 1fr 1fr auto", alignItems: "end", marginBottom: 12 }}>
        <FieldLabel label="Vendor">
          <input value={vendor} onChange={(e) => setVendor(e.target.value)} style={input} />
        </FieldLabel>
        <FieldLabel label="Bill #">
          <input value={billNumber} onChange={(e) => setBillNumber(e.target.value)} style={input} />
        </FieldLabel>
        <FieldLabel label="Bill date">
          <input type="date" value={billDate} onChange={(e) => setBillDate(e.target.value)} style={input} />
        </FieldLabel>
        <button
          type="button"
          style={ghostBtn}
          disabled={updateMetaMutation.isPending}
          onClick={() => updateMetaMutation.mutate({ vendor, bill_number: billNumber, bill_date: billDate })}
        >
          {updateMetaMutation.isPending ? "Saving…" : "Save meta"}
        </button>
      </div>

      <div style={{ fontSize: 12, color: "var(--muted)", marginBottom: 6 }}>Items</div>
      <div style={{ display: "grid", gap: 6 }}>
        {order.items.map((it) => (
          <OrderItemRow key={it.id} item={it} onChange={onChange} />
        ))}
        {order.items.length === 0 && (
          <div style={{ fontSize: 12, color: "var(--muted)", fontStyle: "italic" }}>No items in this order.</div>
        )}
      </div>

      <div style={{ marginTop: 10 }}>
        <AddItemRow orderId={order.id} onAdded={onChange} />
      </div>
    </div>
  );
}

function OrderItemRow({ item, onChange }: { item: OrderItemFull; onChange: () => void }) {
  const [name, setName] = useState(item.product_name);
  const [qty, setQty] = useState(item.expected_qty);
  const [rate, setRate] = useState<number | null>(item.unit_rate);
  const [hsn, setHsn] = useState(item.hsn_code ?? "");
  const [dirty, setDirty] = useState(false);

  const saveMutation = useMutation({
    mutationFn: () => updateOrderItem(item.id, { canonical_name: name, qty, rate, hsn_code: hsn || null }),
    onSuccess: (res) => {
      if (!res.ok) { toastError(errorMessage((res.data as { error?: string }).error, "Update failed")); return; }
      setDirty(false);
      onChange();
    },
    onError: (err) => toastError(err, "Update failed"),
  });

  const deleteMutation = useMutation({
    mutationFn: () => deleteOrderItem(item.id),
    onSuccess: (res) => {
      if (!res.ok) { toastError(errorMessage((res.data as { error?: string }).error, "Delete failed")); return; }
      toastSuccess("Item removed");
      onChange();
    },
    onError: (err) => toastError(err, "Delete failed"),
  });

  const packLabel = item.unit && item.pack_size != null ? `${item.pack_size} ${item.unit}` : item.unit ?? "—";

  return (
    <div style={{ display: "grid", gap: 6, gridTemplateColumns: "2fr 1fr 80px 80px 80px auto auto", alignItems: "center", padding: 6, border: "1px solid var(--line)", borderRadius: 6 }}>
      <input value={name} onChange={(e) => { setName(e.target.value); setDirty(true); }} style={{ ...input, fontSize: 12 }} />
      <input value={hsn} onChange={(e) => { setHsn(e.target.value); setDirty(true); }} placeholder="HSN" style={{ ...input, fontSize: 12 }} />
      <input type="number" step="any" value={qty} onChange={(e) => { setQty(Number(e.target.value) || 0); setDirty(true); }} style={{ ...input, fontSize: 12 }} />
      <input type="number" step="any" value={rate ?? ""} onChange={(e) => { setRate(e.target.value === "" ? null : Number(e.target.value)); setDirty(true); }} placeholder="rate" style={{ ...input, fontSize: 12 }} />
      <span style={{ fontSize: 11, color: "var(--muted)", textAlign: "right" }}>{packLabel}</span>
      <button
        type="button"
        style={{ ...ghostBtn, padding: "4px 8px", fontSize: 11, opacity: dirty ? 1 : 0.4 }}
        disabled={!dirty || saveMutation.isPending}
        onClick={() => saveMutation.mutate()}
      >
        {saveMutation.isPending ? "…" : "Save"}
      </button>
      <button
        type="button"
        style={{ ...ghostBtn, padding: "4px 6px", color: "#dc2626" }}
        onClick={() => { if (confirm(`Remove "${item.product_name}" from this order?`)) deleteMutation.mutate(); }}
        title="Remove item"
      >
        <Trash2 size={12} />
      </button>
    </div>
  );
}

function AddItemRow({ orderId, onAdded }: { orderId: string; onAdded: () => void }) {
  const productsQuery = useQuery({ queryKey: ["inv-canonical"], queryFn: listCanonicalProducts });
  const products = productsQuery.data?.data?.products ?? [];
  const [productId, setProductId] = useState("");
  const [qty, setQty] = useState(1);
  const [rate, setRate] = useState<number | null>(null);

  const addMutation = useMutation({
    mutationFn: () => {
      const p = products.find((x) => x.product_id === productId);
      if (!p) throw new Error("Pick a product");
      return addOrderItem(orderId, {
        product_id: p.product_id,
        canonical_name: p.canonical_name,
        hsn_code: p.hsn_code,
        qty,
        rate,
      });
    },
    onSuccess: (res) => {
      if (!res.ok) { toastError(errorMessage((res.data as { error?: string }).error, "Add failed")); return; }
      toastSuccess("Item added");
      setProductId("");
      setQty(1);
      setRate(null);
      onAdded();
    },
    onError: (err) => toastError(err, "Add failed"),
  });

  return (
    <div style={{ display: "grid", gap: 6, gridTemplateColumns: "2fr 80px 80px auto", alignItems: "center", padding: 6, border: "1px dashed var(--line)", borderRadius: 6 }}>
      <select value={productId} onChange={(e) => setProductId(e.target.value)} style={{ ...input, fontSize: 12 }}>
        <option value="">+ Add an item from catalog…</option>
        {products.map((p) => (
          <option key={p.product_id} value={p.product_id}>
            {p.canonical_name} ({p.pack_size} {p.unit})
          </option>
        ))}
      </select>
      <input type="number" step="any" value={qty} onChange={(e) => setQty(Number(e.target.value) || 0)} style={{ ...input, fontSize: 12 }} />
      <input type="number" step="any" value={rate ?? ""} onChange={(e) => setRate(e.target.value === "" ? null : Number(e.target.value))} placeholder="rate" style={{ ...input, fontSize: 12 }} />
      <button
        type="button"
        className="primary-button"
        disabled={!productId || addMutation.isPending}
        onClick={() => addMutation.mutate()}
        style={{ padding: "4px 10px", fontSize: 12 }}
      >
        <Plus size={12} /> Add
      </button>
    </div>
  );
}

