/**
 * One-off: print row counts grouped by site_id for every inventory
 * table that has the column. Run with:
 *   cd office-ops-engine && bun run scripts/check-sites.ts
 */
import { config as dotenv } from "dotenv";
dotenv({ path: "env.updated" });

import { getDb } from "../src/mastra/modules/inventory/db";

const tables = [
  "canonical_products",
  "product_aliases",
  "product_barcodes",
  "inventory_orders",
  "inventory_order_items",
  "inventory_receipts",
  "inventory_settings",
];

async function main() {
  const db = await getDb();
  for (const table of tables) {
    try {
      // order_items has no site_id directly — join through orders
      if (table === "inventory_order_items") {
        const r = await db.execute({
          sql: `SELECT o.site_id, count(*)::int AS n
                FROM inventory_order_items oi
                JOIN inventory_orders o ON o.id = oi.order_id
                GROUP BY o.site_id`,
          args: [],
        });
        console.log(`\n${table} (via inventory_orders.site_id):`);
        console.table(r.rows);
        continue;
      }
      const r = await db.execute({
        sql: `SELECT site_id, count(*)::int AS n FROM ${table} GROUP BY site_id`,
        args: [],
      });
      console.log(`\n${table}:`);
      console.table(r.rows.length ? r.rows : [{ site_id: "(empty)", n: 0 }]);
    } catch (err) {
      console.log(`\n${table}: SKIPPED (${err instanceof Error ? err.message : err})`);
    }
  }
  process.exit(0);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

