/**
 * Move every inventory row from site_id=FROM to site_id=TO.
 *   bun run scripts/migrate-site.ts default site-dev
 */
import { config as dotenv } from "dotenv";
dotenv({ path: "env.updated" });

import { getDb } from "../src/mastra/lib/database";

async function main() {
  const from = process.argv[2];
  const to = process.argv[3];
  if (!from || !to) {
    console.error("Usage: bun run scripts/migrate-site.ts <from> <to>");
    process.exit(1);
  }
  if (from === to) {
    console.error("from and to are identical — nothing to do");
    process.exit(1);
  }

  const db = await getDb();
  const tables = [
    "canonical_products",
    "product_aliases",
    "product_barcodes",
    "inventory_orders",
    "inventory_settings",
  ];

  console.log(`Moving rows from site_id='${from}' to site_id='${to}'…`);
  for (const t of tables) {
    const r = await db.execute({
      sql: `UPDATE ${t} SET site_id = ? WHERE site_id = ?`,
      args: [to, from],
    });
    console.log(`  ${t}: ${r.rowsAffected ?? 0} row(s)`);
  }
  console.log("Done.");
  process.exit(0);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

