function OrderCard({ order, onChange, onDelete }: { order: OrderFull; onChange: () => void; onDelete: () => void }) {
  const [open, setOpen] = useState(false);
  const totalExpected = order.items.reduce((s, i) => s + (i.expected_qty || 0), 0);
  const totalReceived = order.items.reduce((s, i) => s + (i.received_qty || 0), 0);
  const progressPct = totalExpected > 0 ? Math.min(100, Math.round((totalReceived / totalExpected) * 100)) : 0;

  return (
    <div style={{ border: "1px solid var(--line)", borderRadius: 10, overflow: "hidden" }}>
      <div
        style={{ display: "flex", justifyContent: "space-between", alignItems: "center", padding: 12, gap: 10, cursor: "pointer", background: "var(--surface, #fafafa)" }}
        onClick={() => setOpen((v) => !v)}
      >
        <div style={{ display: "flex", alignItems: "center", gap: 8, flex: 1, minWidth: 0 }}>
          {open ? <ChevronDown size={16} /> : <ChevronRight size={16} />}
          <div style={{ minWidth: 0, flex: 1 }}>
            <div style={{ fontWeight: 600, fontSize: 14, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>
              {order.vendor ?? "Unknown vendor"}
            </div>
            <div style={{ fontSize: 11, color: "var(--muted)", marginTop: 2 }}>
              Bill #{order.bill_number ?? "—"} · {order.bill_date ?? "—"} · {order.items.length} item{order.items.length === 1 ? "" : "s"}
            </div>
          </div>
        </div>
        <div style={{ display: "flex", gap: 12, alignItems: "center" }}>
          <div style={{ textAlign: "right", minWidth: 90 }}>
            <div style={{ fontSize: 11, color: "var(--muted)" }}>Received</div>
            <div style={{ fontSize: 13, fontWeight: 600 }}>{totalReceived} / {totalExpected}</div>
            <div style={{ height: 3, background: "var(--line)", borderRadius: 2, marginTop: 4, overflow: "hidden" }}>
              <div style={{ width: `${progressPct}%`, height: "100%", background: progressPct === 100 ? "#16a34a" : "#2563eb" }} />
            </div>
          </div>
          <Pill ok={order.status === "done"} warn={order.status === "partial"}>{order.status}</Pill>
          <button
            type="button"
            onClick={(e) => { e.stopPropagation(); onDelete(); }}
            style={{ ...ghostBtn, padding: "4px 8px", color: "#dc2626" }}
            title="Delete order"
          >
            <Trash2 size={14} />
          </button>
        </div>
      </div>

      {open && (
        <div style={{ borderTop: "1px solid var(--line)" }}>
          <OrderEditor order={order} onChange={onChange} />
        </div>
      )}
    </div>
  );
}

function OrderEditor({ order, onChange }: { order: OrderFull; onChange: () => void }) {
  const updateMetaMutation = useMutation({
    mutationFn: (patch: { vendor?: string; bill_number?: string; bill_date?: string }) => updateOrder(order.id, patch),
    onSuccess: (res) => {
      if (!res.ok) { toastError(errorMessage((res.data as { error?: string }).error, "Update failed")); return; }
      toastSuccess("Saved");
      onChange();
    },
    onError: (err) => toastError(err, "Update failed"),
  });

  const [vendor, setVendor] = useState(order.vendor ?? "");
  const [billNumber, setBillNumber] = useState(order.bill_number ?? "");
  const [billDate, setBillDate] = useState(order.bill_date ?? "");
  const metaDirty =
    vendor !== (order.vendor ?? "") ||
    billNumber !== (order.bill_number ?? "") ||
    billDate !== (order.bill_date ?? "");

  return (
    <div style={{ padding: 14 }}>
      {/* Bill meta — label/value rows that read like a sheet header */}
      <div style={{ display: "grid", gap: 0, marginBottom: 14, fontSize: 13 }}>
        <MetaRow label="Vendor">
          <input value={vendor} onChange={(e) => setVendor(e.target.value)} style={metaInput} />
        </MetaRow>
        <MetaRow label="Bill #">
          <input value={billNumber} onChange={(e) => setBillNumber(e.target.value)} style={metaInput} />
        </MetaRow>
        <MetaRow label="Bill date">
          <input type="date" value={billDate} onChange={(e) => setBillDate(e.target.value)} style={metaInput} />
        </MetaRow>
        {metaDirty && (
          <div style={{ display: "flex", justifyContent: "flex-end", padding: "6px 0" }}>
            <button
              type="button"
              className="primary-button"
              disabled={updateMetaMutation.isPending}
              onClick={() => updateMetaMutation.mutate({ vendor, bill_number: billNumber, bill_date: billDate })}
              style={{ padding: "4px 10px", fontSize: 12 }}
            >
              {updateMetaMutation.isPending ? "Saving…" : "Save bill details"}
            </button>
          </div>
        )}
      </div>

      {/* Items — single bordered table, Excel-style header row */}
      <div style={{ border: "1px solid var(--line)", borderRadius: 6, overflow: "hidden" }}>
        <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 12, tableLayout: "fixed" }}>
          <colgroup>
            <col style={{ width: "auto" }} />
            <col style={{ width: 90 }} />
            <col style={{ width: 80 }} />
            <col style={{ width: 70 }} />
            <col style={{ width: 90 }} />
            <col style={{ width: 90 }} />
            <col style={{ width: 60 }} />
          </colgroup>
          <thead>
            <tr style={{ background: "var(--surface, #fafafa)", color: "var(--muted)" }}>
              <th style={thCell}>Product</th>
              <th style={thCell}>HSN</th>
              <th style={{ ...thCell, textAlign: "right" }}>Qty</th>
              <th style={{ ...thCell, textAlign: "right" }}>Rate</th>
              <th style={{ ...thCell, textAlign: "right" }}>Pack</th>
              <th style={{ ...thCell, textAlign: "right" }}>Received</th>
              <th style={thCell}></th>
            </tr>
          </thead>
          <tbody>
            {order.items.map((it) => (
              <OrderItemRow key={it.id} item={it} onChange={onChange} />
            ))}
            {order.items.length === 0 && (
              <tr>
                <td colSpan={7} style={{ ...tdCell, color: "var(--muted)", fontStyle: "italic", textAlign: "center" }}>
                  No items.
                </td>
              </tr>
            )}
            <AddItemRow orderId={order.id} onAdded={onChange} />
          </tbody>
        </table>
      </div>
    </div>
  );
}

function MetaRow({ label, children }: { label: string; children: ReactNode }) {
  return (
    <div style={{ display: "grid", gridTemplateColumns: "100px 1fr", alignItems: "center", borderBottom: "1px solid var(--line)" }}>
      <div style={{ padding: "6px 8px", color: "var(--muted)", fontSize: 11, textTransform: "uppercase", letterSpacing: 0.5, background: "var(--surface, #fafafa)" }}>{label}</div>
      <div style={{ padding: "4px 6px" }}>{children}</div>
    </div>
  );
}

function OrderItemRow({ item, onChange }: { item: OrderItemFull; onChange: () => void }) {
  const [name, setName] = useState(item.product_name);
  const [qty, setQty] = useState(item.expected_qty);
  const [rate, setRate] = useState<number | null>(item.unit_rate);
  const [hsn, setHsn] = useState(item.hsn_code ?? "");

  const dirty =
    name !== item.product_name ||
    qty !== item.expected_qty ||
    rate !== item.unit_rate ||
    hsn !== (item.hsn_code ?? "");

  const saveMutation = useMutation({
    mutationFn: () => updateOrderItem(item.id, { canonical_name: name, qty, rate, hsn_code: hsn || null }),
    onSuccess: (res) => {
      if (!res.ok) { toastError(errorMessage((res.data as { error?: string }).error, "Update failed")); return; }
      onChange();
    },
    onError: (err) => toastError(err, "Update failed"),
  });

  const deleteMutation = useMutation({
    mutationFn: () => deleteOrderItem(item.id),
    onSuccess: (res) => {
      if (!res.ok) { toastError(errorMessage((res.data as { error?: string }).error, "Delete failed")); return; }
      toastSuccess("Item removed");
      onChange();
    },
    onError: (err) => toastError(err, "Delete failed"),
  });

  const packLabel = item.unit && item.pack_size != null ? `${item.pack_size} ${item.unit}` : item.unit ?? "—";

  return (
    <tr>
      <td style={tdCell}>
        <input value={name} onChange={(e) => setName(e.target.value)} onBlur={() => dirty && saveMutation.mutate()} style={cellInput} />
      </td>
      <td style={tdCell}>
        <input value={hsn} onChange={(e) => setHsn(e.target.value)} onBlur={() => dirty && saveMutation.mutate()} style={cellInput} />
      </td>
      <td style={tdCell}>
        <input type="number" step="any" value={qty} onChange={(e) => setQty(Number(e.target.value) || 0)} onBlur={() => dirty && saveMutation.mutate()} style={{ ...cellInput, textAlign: "right" }} />
      </td>
      <td style={tdCell}>
        <input type="number" step="any" value={rate ?? ""} onChange={(e) => setRate(e.target.value === "" ? null : Number(e.target.value))} onBlur={() => dirty && saveMutation.mutate()} style={{ ...cellInput, textAlign: "right" }} />
      </td>
      <td style={{ ...tdCell, textAlign: "right", color: "var(--muted)" }}>{packLabel}</td>
      <td style={{ ...tdCell, textAlign: "right" }}>
        <span style={{ fontWeight: 600, color: item.received_qty >= item.expected_qty ? "#16a34a" : "var(--text)" }}>
          {item.received_qty}
        </span>
        <span style={{ color: "var(--muted)" }}> / {item.expected_qty}</span>
      </td>
      <td style={{ ...tdCell, textAlign: "right" }}>
        <button
          type="button"
          onClick={() => { if (confirm(`Remove "${item.product_name}" from this order?`)) deleteMutation.mutate(); }}
          style={{ ...iconBtn, color: "#dc2626" }}
          title="Remove item"
        >
          <Trash2 size={12} />
        </button>
      </td>
    </tr>
  );
}

function AddItemRow({ orderId, onAdded }: { orderId: string; onAdded: () => void }) {
  const productsQuery = useQuery({ queryKey: ["inv-canonical"], queryFn: listCanonicalProducts });
  const products = productsQuery.data?.data?.products ?? [];
  const [productId, setProductId] = useState("");
  const [qty, setQty] = useState(1);
  const [rate, setRate] = useState<number | null>(null);

  const addMutation = useMutation({
    mutationFn: () => {
      const p = products.find((x) => x.product_id === productId);
      if (!p) throw new Error("Pick a product");
      return addOrderItem(orderId, {
        product_id: p.product_id,
        canonical_name: p.canonical_name,
        hsn_code: p.hsn_code,
        qty,
        rate,
      });
    },
    onSuccess: (res) => {
      if (!res.ok) { toastError(errorMessage((res.data as { error?: string }).error, "Add failed")); return; }
      toastSuccess("Item added");
      setProductId("");
      setQty(1);
      setRate(null);
      onAdded();
    },
    onError: (err) => toastError(err, "Add failed"),
  });

  return (
    <tr style={{ background: "var(--surface, #fafafa)" }}>
      <td style={tdCell}>
        <select value={productId} onChange={(e) => setProductId(e.target.value)} style={cellInput}>
          <option value="">+ Add an item from catalog…</option>
          {products.map((p) => (
            <option key={p.product_id} value={p.product_id}>
              {p.canonical_name} ({p.pack_size} {p.unit})
            </option>
          ))}
        </select>
      </td>
      <td style={tdCell}>
        <span style={{ color: "var(--muted)", fontSize: 11 }}>from catalog</span>
      </td>
      <td style={tdCell}>
        <input type="number" step="any" value={qty} onChange={(e) => setQty(Number(e.target.value) || 0)} style={{ ...cellInput, textAlign: "right" }} />
      </td>
      <td style={tdCell}>
        <input type="number" step="any" value={rate ?? ""} onChange={(e) => setRate(e.target.value === "" ? null : Number(e.target.value))} placeholder="rate" style={{ ...cellInput, textAlign: "right" }} />
      </td>
      <td colSpan={2} style={{ ...tdCell, textAlign: "right", color: "var(--muted)" }}>—</td>
      <td style={{ ...tdCell, textAlign: "right" }}>
        <button
          type="button"
          className="primary-button"
          disabled={!productId || addMutation.isPending}
          onClick={() => addMutation.mutate()}
          style={{ padding: "2px 8px", fontSize: 11 }}
          title="Add item"
        >
          <Plus size={12} />
        </button>
      </td>
    </tr>
  );
}

const thCell: React.CSSProperties = {
  padding: "6px 8px",
