/**
 * Replace every row in a tab (clear → headers → values). For snapshot
 * sheets like Catalog that should reflect the current DB state rather
 * than accumulate history. Auto-creates the tab if missing.
 */
export async function replaceSheetTab(
  sheets: sheets_v4.Sheets,
  spreadsheetId: string,
  tabName: string,
  headers: string[],
  rows: string[][],
): Promise<void> {
  await ensureSheet(sheets, spreadsheetId, tabName);
  await sheets.spreadsheets.values.clear({
    spreadsheetId,
    range: formatSheetRange(tabName, 'A:Z'),
  });
  await sheets.spreadsheets.values.update({
    spreadsheetId,
    range: formatSheetRange(tabName, 'A1'),
    valueInputOption: 'USER_ENTERED',
    requestBody: { values: [headers, ...rows] },
  });
}

