export type CatalogSheetRow = {
  canonical_name: string;
  category: string | null;
  unit: string;
  pack_size: number;
  last_price: number | null;
  barcodes: string | null; // comma-separated
  hsn_code: string | null;
};

/**
 * Snapshot of the catalog for the Google Sheet "Catalog" tab. Joins
 * canonical_products → product_barcodes (concatenated) and pulls the
 * most recent unit_rate from inventory_order_items as a price proxy
 * (canonical products don't carry a price column today).
 */
export async function listCatalogForSheet(siteId: string): Promise<CatalogSheetRow[]> {
  const db = await getDb();
  const result = await db.execute({
    sql: `
      SELECT
        cp.canonical_name,
        cp.category,
        cp.unit,
        cp.pack_size,
        cp.hsn_code,
        (SELECT string_agg(pb.barcode, ', ')
           FROM product_barcodes pb
          WHERE pb.product_id = cp.product_id) AS barcodes,
        (SELECT oi.unit_rate
           FROM inventory_order_items oi
           JOIN inventory_orders o ON o.id = oi.order_id
          WHERE oi.product_id = cp.product_id AND o.site_id = ?
          ORDER BY o.created_at DESC
          LIMIT 1) AS last_price
      FROM canonical_products cp
      WHERE cp.site_id = ?
      ORDER BY cp.canonical_name
    `,
    args: [siteId, siteId],
  });
  return result.rows as unknown as CatalogSheetRow[];
}

