import { apiRequest } from "./client";

// Must match the field-app's `config.siteId` (see field-app/src/config.ts).
// If you change one, change the other — otherwise dashboard writes and
// field-app reads land in different sites and never see each other.
const SITE_ID = (import.meta.env.VITE_OPS_SITE_ID as string | undefined) ?? "site-dev";

const SITE_HEADERS = { "X-Site-Id": SITE_ID };

export interface CanonicalProduct {
  product_id: string;
  site_id: string;
  canonical_name: string;
  category: string | null;
  hsn_code: string | null;
  unit: string;
  pack_size: number;
  created_at: string;
  updated_at: string;
}

export interface UnresolvedBillItem {
  id: string;
  site_id: string;
  order_id: string | null;
  bill_item_name: string;
  hsn_code: string | null;
  qty: number;
  unit_rate: number | null;
  line_value: number | null;
  status: string;
  created_at: string;
}

export interface BillSuggestion {
  productId: string;
  canonicalName: string;
  unit: string;
  packSize: number;
  hsnCode: string | null;
  category: string | null;
  score: number;
  method: string;
}

export interface BillExtractItem {
  tempId: string;
  bill_item_name: string;
  hsn_code: string | null;
  qty: number;
  rate: number | null;
  value: number | null;
  unit_hint: string | null;
  suggestions: BillSuggestion[];
}

export interface BillExtractResult {
  bill: {
    vendor_name: string | null;
    bill_number: string | null;
    bill_date: string | null;
    grand_total: number | null;
    tax_total: number | null;
  };
  items: BillExtractItem[];
}

export interface ValidatedBillItem {
  action: "use_existing" | "create_new";
  product_id?: string | null;
  canonical_name: string;
  category?: string | null;
  hsn_code?: string | null;
  unit: string;
  pack_size: number;
  qty: number;
  rate?: number | null;
  value?: number | null;
  bill_item_name: string;
}

export interface ValidateBillPayload {
  vendor_name?: string | null;
  bill_number?: string | null;
  bill_date?: string | null;
  grand_total?: number | null;
  items: ValidatedBillItem[];
}

export interface ComplianceLogRow {
  scanned_at: string;
  date: string;
  vendor: string | null;
  bill_number: string | null;
  product_id: string | null;
  product_name: string;
  category: string | null;
  hsn_code: string | null;
  unit: string | null;
  pack_size: number | null;
  qty_received: number;
  expected_qty: number | null;
  unit_rate: number | null;
  line_value: number | null;
  expiry_date: string | null;
  received_by: string | null;
  status: "OK" | "MISMATCH";
}

export function listCanonicalProducts() {
  return apiRequest<{ products: CanonicalProduct[] }>(
    "GET", "/api/inventory/canonical-products", undefined, SITE_HEADERS,
  );
}

export function createCanonicalProduct(input: {
  canonical_name: string;
  category?: string;
  hsn_code?: string;
  unit?: string;
  pack_size?: number;
}) {
  return apiRequest<{ product_id: string }>(
    "POST", "/api/inventory/canonical-products", input, SITE_HEADERS,
  );
}

export function listUnresolvedBillItems() {
  return apiRequest<{ items: UnresolvedBillItem[] }>(
    "GET", "/api/inventory/bills/unresolved", undefined, SITE_HEADERS,
  );
}

export function resolveBillItem(input: {
  unresolved_id: string;
  product_id: string;
  bill_item_name?: string;
  remember_alias?: boolean;
}) {
  return apiRequest<{ resolved: boolean }>(
    "POST", "/api/inventory/bills/resolve", input, SITE_HEADERS,
  );
}

export function extractBill(input: {
  image: string; // base64-encoded (no data: prefix)
  mime_type?: string;
}) {
  return apiRequest<BillExtractResult>(
    "POST", "/api/inventory/bills/extract", input, SITE_HEADERS,
  );
}

export function validateBill(payload: ValidateBillPayload) {
  return apiRequest<{ orderId: string; committed: number }>(
    "POST", "/api/inventory/bills/validate", payload, SITE_HEADERS,
  );
}

export function listCompliance(params?: { from?: string; to?: string }) {
  const q = new URLSearchParams();
  if (params?.from) q.set("from", params.from);
  if (params?.to) q.set("to", params.to);
  const qs = q.toString();
  return apiRequest<{ rows: ComplianceLogRow[] }>(
    "GET",
    `/api/inventory/compliance${qs ? `?${qs}` : ""}`,
    undefined,
    SITE_HEADERS,
  );
}

export interface SheetInfo {
  attached: boolean;
  spreadsheetId: string | null;
  ownerEmail: string | null;
  url: string | null;
  googleSsoConfigured: boolean;
  callerHasGoogleToken: boolean;
  tabs: string[];
}

export function getSheetInfo() {
  return apiRequest<SheetInfo>(
    "GET",
    "/api/inventory/sheet",
    undefined,
    SITE_HEADERS,
  );
}

export function attachSheet(urlOrId: string) {
  return apiRequest<{
    attached: boolean;
    spreadsheetId: string;
    ownerEmail: string;
    title: string | null;
    url: string;
  }>("POST", "/api/inventory/sheet", { url: urlOrId }, SITE_HEADERS);
}

// ─── Orders (admin CRUD on validated bills) ───────────────────

export interface OrderItemFull {
  id: string;
  order_id: string;
  product_id: string | null;
  product_name: string;
  bill_item_name: string | null;
  hsn_code: string | null;
  expected_qty: number;
  received_qty: number;
  unit_rate: number | null;
  line_value: number | null;
  unit: string | null;
  pack_size: number | null;
}

export interface OrderFull {
  id: string;
  site_id: string;
  vendor: string | null;
  bill_number: string | null;
  bill_date: string | null;
  grand_total: number | null;
  status: string;
  expected_at: string | null;
  arrived_at: string | null;
  created_at: string;
  items: OrderItemFull[];
}

export function listOrders() {
  return apiRequest<{ orders: OrderFull[] }>(
    "GET", "/api/inventory/orders/full", undefined, SITE_HEADERS,
  );
}

export function deleteOrder(orderId: string) {
  return apiRequest<{ deleted: boolean }>(
    "DELETE", `/api/inventory/orders/${encodeURIComponent(orderId)}`, undefined, SITE_HEADERS,
  );
}

export function updateOrder(orderId: string, patch: { vendor?: string; bill_number?: string; bill_date?: string }) {
  return apiRequest<{ updated: boolean }>(
    "PATCH", `/api/inventory/orders/${encodeURIComponent(orderId)}`, patch, SITE_HEADERS,
  );
}

export function addOrderItem(orderId: string, item: {
  product_id?: string | null;
  canonical_name: string;
  bill_item_name?: string | null;
  hsn_code?: string | null;
  qty: number;
  rate?: number | null;
}) {
  return apiRequest<{ id: string }>(
    "POST", `/api/inventory/orders/${encodeURIComponent(orderId)}/items`, item, SITE_HEADERS,
  );
}

export function updateOrderItem(itemId: string, patch: {
  product_id?: string | null;
  canonical_name?: string;
  hsn_code?: string | null;
  qty?: number;
  rate?: number | null;
}) {
  return apiRequest<{ updated: boolean }>(
    "PATCH", `/api/inventory/order-items/${encodeURIComponent(itemId)}`, patch, SITE_HEADERS,
  );
}

export function deleteOrderItem(itemId: string) {
  return apiRequest<{ deleted: boolean }>(
    "DELETE", `/api/inventory/order-items/${encodeURIComponent(itemId)}`, undefined, SITE_HEADERS,
  );
}

export function clearAliases() {
  return apiRequest<{ deleted: number }>(
    "DELETE",
    "/api/inventory/aliases",
    undefined,
    SITE_HEADERS,
  );
}

export function detachSheet() {
  return apiRequest<{ attached: false }>(
    "DELETE",
    "/api/inventory/sheet",
    undefined,
    SITE_HEADERS,
  );
}

export function syncSheet(params?: { from?: string; to?: string }) {
  return apiRequest<{ appended: number; failed: number; total: number }>(
    "POST",
    "/api/inventory/sheet/sync",
    { from: params?.from, to: params?.to },
    SITE_HEADERS,
  );
}

export async function fileToBase64(file: File): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => {
      const result = reader.result;
      if (typeof result !== "string") {
        reject(new Error("Failed to read file"));
        return;
      }
      // strip "data:image/...;base64," prefix
      const comma = result.indexOf(",");
      resolve(comma >= 0 ? result.slice(comma + 1) : result);
    };
    reader.onerror = () => reject(reader.error);
    reader.readAsDataURL(file);
  });
}

