106	export const api = {
107	  // Login is handled by visitor's guard auth endpoint, not the inventory
108	  // plugin. Lives here so screens have one client to import.
109	  async login(input: { guardName: string; pin: string }): Promise<{
110	    token: string;
111	    guardId: string;
112	    guardName: string;
113	    language: 'hindi' | 'english';
114	  }> {
115	    const deviceId = await getDeviceId();
116	    const res = await fetch(`${config.apiBaseUrl}/api/guard/login`, {
117	      method: 'POST',
118	      headers: { 'Content-Type': 'application/json' },
119	      body: JSON.stringify({
120	        guardName: input.guardName,
121	        pin: input.pin,
122	        deviceId,
123	        deviceName: 'field-app',
124	      }),
125	    });
126	    if (!res.ok) {
127	      const text = await res.text().catch(() => '');
128	      // Pull the server's reason out of `{ "error": "..." }` if present so
129	      // the LoginScreen shows something actionable instead of just "Login failed".
130	      let reason = text.slice(0, 200);
131	      try {
132	        const parsed = JSON.parse(text);
133	        if (parsed && typeof parsed.error === 'string') reason = parsed.error;
134	      } catch {}
135	      throw new ApiError(res.status, reason || `Login failed (${res.status})`, text.slice(0, 500));
136	    }
137	    return res.json();
138	  },
139	
140	  // Writes (outbox-dispatched).
141	  send: {
142	    receipt: (payload: object) => post('/api/inventory/receipts', payload),
143	    product: (payload: object) => post('/api/inventory/products', payload),
144	    issue: (payload: object) => post('/api/inventory/issues', payload),
145	    reorderRequest: (payload: object) =>
146	      post('/api/inventory/reorder-requests', payload),
147	    mismatchFlag: (payload: object) =>
148	      post('/api/inventory/mismatch-flags', payload),
149	    learnBarcode: (payload: object) =>
150	      post('/api/inventory/canonical-products/learn-barcode', payload),
151	  },
152	
153	  // Reads (called by screens).
154	  fetch: {
155	    orders: () =>
156	      request<{ orders: RemoteOrder[] }>('/api/inventory/orders').then((r) => r.orders),
157	    stock: () =>
158	      request<{ stock: RemoteStockRow[] }>('/api/inventory/stock').then((r) => r.stock),
159	    alerts: () =>
160	      request<{ alerts: RemoteStockRow[] }>('/api/inventory/alerts').then((r) => r.alerts),
161	    catalog: (barcode: string) =>
162	      request<RemoteCatalogHit>(
163	        `/api/inventory/catalog/${encodeURIComponent(barcode)}`,
164	      ),
165	    normalizeName: (rawName: string) =>
166	      request<{
167	        canonical: string;
168	        language: 'en' | 'hi' | 'hinglish' | 'unknown';
169	        confidence: number;
170	        cached: boolean;
171	      }>('/api/inventory/products/normalize', {
172	        method: 'POST',
173	        body: JSON.stringify({ rawName }),
174	      }),
175	    canonicalProducts: () =>
176	      request<{ products: RemoteCanonicalProduct[] }>(
177	        '/api/inventory/canonical-products',
178	      ).then((r) => r.products),
179	  },
180	};

