73	export async function upsertCanonicalProduct(product: CanonicalProduct): Promise<void> {
74	  const db = await getDb();
75	  await db.runAsync(
76	    `INSERT INTO canonical_products (product_id, canonical_name, category, hsn_code, unit, pack_size, updated_at)
77	     VALUES (?, ?, ?, ?, ?, ?, ?)
78	     ON CONFLICT(product_id) DO UPDATE SET
79	       canonical_name = excluded.canonical_name,
80	       category = excluded.category,
81	       hsn_code = excluded.hsn_code,
82	       unit = excluded.unit,
83	       pack_size = excluded.pack_size,
84	       updated_at = excluded.updated_at`,
85	    [
86	      product.product_id,
87	      product.canonical_name,
88	      product.category,
89	      product.hsn_code,
90	      product.unit,
91	      product.pack_size,
92	      product.updated_at,
93	    ],
94	  );
