97	/**
98	 * Replace the entire canonical product catalog with fresh data
99	 * from the backend. Used during full sync.
100	 *
101	 * IMPORTANT: do NOT `DELETE FROM canonical_products` first — there is a
102	 * cascading FK from `product_barcodes`, so a blanket delete blows away
103	 * every learned barcode → product mapping the guard has built up.
104	 * Instead we upsert each remote row, then delete the ones the remote
105	 * no longer knows about.
106	 */
107	export async function replaceCanonicalProducts(
108	  products: CanonicalProduct[],
109	): Promise<void> {
110	  const db = await getDb();
111	  for (const p of products) {
112	    await upsertCanonicalProduct(p);
113	  }
114	  if (products.length === 0) return; // empty payload — keep what we have
115	
116	  // Drop products the remote no longer has. Bind ids as literals (the
