function ReviewRowCard({
  row, catalog, onChange, onAcceptSuggestion, onAcceptCatalog, onRemove,
}: {
  row: ReviewRow;
  catalog: CanonicalProduct[];
  onChange: (patch: Partial<ReviewRow>) => void;
  onAcceptSuggestion: (s: BillSuggestion) => void;
  onAcceptCatalog: (p: CanonicalProduct) => void;
  onRemove: () => void;
}) {
  // Top backend suggestion is shown as a "did you mean…" pill at the
  // bottom — only when the spelling doesn't already match. Multiple
  // chips were confusing, so we surface just the closest one.
  const closestMatch = useMemo(() => {
    const top = row.suggestions[0];
    if (!top) return null;
    if (top.canonicalName.toLowerCase() === row.canonical_name.trim().toLowerCase()) return null;
    if (top.productId === row.product_id) return null; // already accepted
    return top;
  }, [row.suggestions, row.canonical_name, row.product_id]);

  const isUsingExisting = row.action === "use_existing" && row.product_id;

  return (
    <div style={{ border: "1px solid var(--line)", borderRadius: 10, padding: 12 }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 8 }}>
        <div style={{ fontSize: 11, color: "var(--muted)" }}>
          From bill: <b>{row.bill_item_name}</b>
        </div>
        <div style={{ display: "flex", gap: 6, alignItems: "center" }}>
          {isUsingExisting ? (
            <Pill ok>Mapped to catalog</Pill>
          ) : (
            <Pill warn>Will register as new</Pill>
          )}
          <button type="button" onClick={onRemove} style={{ ...ghostBtn, padding: "4px 8px", fontSize: 11 }}>Remove</button>
        </div>
      </div>

      <div style={{ display: "grid", gap: 8, gridTemplateColumns: "2fr 1fr 1fr 1fr 1fr 1fr 1fr", alignItems: "end" }}>
        <FieldLabel label="Canonical name">
          <CatalogCombobox
            value={row.canonical_name}
            catalog={catalog}
            selectedProductId={row.product_id}
            onTextChange={(text) =>
              onChange({ canonical_name: text, action: "create_new", product_id: null })
            }
            onPick={onAcceptCatalog}
          />
        </FieldLabel>
        <FieldLabel label="Category">
          <input type="text" value={row.category} onChange={(e) => onChange({ category: e.target.value })} style={input} />
        </FieldLabel>
        <FieldLabel label="HSN">
          <input type="text" value={row.hsn_code} onChange={(e) => onChange({ hsn_code: e.target.value })} style={input} />
        </FieldLabel>
        <FieldLabel label="Qty">
          <input type="number" step="any" value={row.qty} onChange={(e) => onChange({ qty: Number(e.target.value) || 0 })} style={input} />
        </FieldLabel>
        <FieldLabel label="Rate (₹)">
          <input type="number" step="any" value={row.rate ?? ""} onChange={(e) => onChange({ rate: e.target.value === "" ? null : Number(e.target.value) })} style={input} />
        </FieldLabel>
        <FieldLabel label="Unit">
          <select value={row.unit} onChange={(e) => onChange({ unit: e.target.value })} style={input}>
            {UNIT_OPTIONS.map((u) => <option key={u} value={u}>{u}</option>)}
          </select>
        </FieldLabel>
        <FieldLabel label="Pack size">
          <input type="number" step="any" value={row.pack_size} onChange={(e) => onChange({ pack_size: Number(e.target.value) || 1 })} style={input} />
        </FieldLabel>
      </div>

      {closestMatch && (
        <div style={{ marginTop: 10, display: "flex", gap: 8, alignItems: "center", fontSize: 12, color: "var(--muted)" }}>
          <span>Did you mean:</span>
          <button
            type="button"
            onClick={() => onAcceptSuggestion(closestMatch)}
            style={{
              border: "1px solid var(--line)",
              borderRadius: 999,
              padding: "4px 10px",
              background: "transparent",
              color: "var(--text)",
              cursor: "pointer",
              fontSize: 12,
              display: "inline-flex",
              gap: 6,
              alignItems: "center",
            }}
            title={`Closest catalog match (${Math.round(closestMatch.score * 100)}% ${closestMatch.method})`}
          >
            <span style={{ fontWeight: 600 }}>{closestMatch.canonicalName}</span>
            <span style={{ opacity: 0.7 }}>· {closestMatch.packSize} {closestMatch.unit}</span>
          </button>
        </div>
      )}
    </div>
  );
}

function CatalogCombobox({
  value, catalog, selectedProductId, onTextChange, onPick,
}: {
  value: string;
  catalog: CanonicalProduct[];
  selectedProductId: string | null;
  onTextChange: (text: string) => void;
  onPick: (product: CanonicalProduct) => void;
}) {
  const [open, setOpen] = useState(false);
  const [activeIdx, setActiveIdx] = useState(0);
  const wrapRef = useRef<HTMLDivElement>(null);

  // Close on outside click.
  useEffect(() => {
    function onDocClick(e: MouseEvent) {
      if (!wrapRef.current) return;
      if (!wrapRef.current.contains(e.target as Node)) setOpen(false);
    }
    document.addEventListener("mousedown", onDocClick);
    return () => document.removeEventListener("mousedown", onDocClick);
  }, []);

  const filtered = useMemo(() => {
    const q = value.trim().toLowerCase();
    if (!q) return catalog.slice(0, 40);
    // Substring + word-start match; rank exact > prefix > contains.
    const scored = catalog.map((p) => {
      const name = p.canonical_name.toLowerCase();
      let score = 0;
      if (name === q) score = 3;
      else if (name.startsWith(q)) score = 2;
      else if (name.includes(q)) score = 1;
      else if ((p.category ?? "").toLowerCase().includes(q)) score = 0.5;
      else if ((p.hsn_code ?? "").toLowerCase().includes(q)) score = 0.5;
      return { p, score };
    });
    return scored.filter((x) => x.score > 0).sort((a, b) => b.score - a.score).slice(0, 40).map((x) => x.p);
  }, [catalog, value]);

  function commit(p: CanonicalProduct) {
    onPick(p);
    setOpen(false);
    setActiveIdx(0);
  }

  return (
    <div ref={wrapRef} style={{ position: "relative" }}>
      <input
        type="text"
        value={value}
        onChange={(e) => { onTextChange(e.target.value); setOpen(true); setActiveIdx(0); }}
        onFocus={() => setOpen(true)}
        onKeyDown={(e) => {
          if (e.key === "ArrowDown") { e.preventDefault(); setOpen(true); setActiveIdx((i) => Math.min(filtered.length - 1, i + 1)); }
          else if (e.key === "ArrowUp") { e.preventDefault(); setActiveIdx((i) => Math.max(0, i - 1)); }
          else if (e.key === "Enter" && open && filtered[activeIdx]) { e.preventDefault(); commit(filtered[activeIdx]); }
          else if (e.key === "Escape") { setOpen(false); }
        }}
        style={input}
        autoComplete="off"
        placeholder="Search catalog or type a new name…"
      />
      {open && filtered.length > 0 && (
        <div
          style={{
            position: "absolute",
            top: "calc(100% + 2px)",
            left: 0,
            right: 0,
            zIndex: 30,
            maxHeight: 240,
            overflowY: "auto",
            background: "var(--surface, #fff)",
            border: "1px solid var(--line)",
            borderRadius: 6,
            boxShadow: "0 6px 18px rgba(0,0,0,0.08)",
          }}
        >
          {filtered.map((p, i) => {
            const isActive = i === activeIdx;
            const isSelected = selectedProductId === p.product_id;
            return (
              <div
                key={p.product_id}
                onMouseDown={(e) => { e.preventDefault(); commit(p); }}
                onMouseEnter={() => setActiveIdx(i)}
                style={{
                  padding: "6px 10px",
                  cursor: "pointer",
                  background: isActive ? "var(--line)" : "transparent",
                  display: "flex",
                  justifyContent: "space-between",
                  alignItems: "center",
                  gap: 8,
                  fontSize: 12,
                }}
              >
                <div style={{ minWidth: 0, flex: 1 }}>
                  <div style={{ fontWeight: 600, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>
                    {p.canonical_name}
                  </div>
                  <div style={{ fontSize: 11, color: "var(--muted)" }}>
                    {p.category ?? "—"} · {p.pack_size} {p.unit}{p.hsn_code ? ` · HSN ${p.hsn_code}` : ""}
                  </div>
                </div>
                {isSelected && <Check size={14} />}
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

