1	import { NativeStackScreenProps } from '@react-navigation/native-stack';
2	import { useFocusEffect } from '@react-navigation/native';
3	import { Camera, RefreshCw, Search } from 'lucide-react-native';
4	import React, { useCallback, useMemo, useState } from 'react';
5	import { FlatList, Pressable, StyleSheet, TextInput, View } from 'react-native';
6	import {
7	  AppBar,
8	  Card,
9	  IconButton,
10	  radius,
11	  Skeleton,
12	  spacing,
13	  Text,
14	} from '../../../design';
15	import {
16	  CanonicalProduct,
17	  learnBarcode,
18	  listCanonicalProducts,
19	} from '../../../db/catalog';
20	import { enqueue } from '../../../db/outbox';
21	import { getDb } from '../../../db/database';
22	import { RootStackParamList } from '../../../navigation/types';
23	import { syncCanonicalProducts, syncOrders } from '../../../sync/syncService';
24	import { useTheme } from '../../../theme';
25	
26	type Props = NativeStackScreenProps<RootStackParamList, 'CatalogPicker'>;
27	
28	type OpenOrderItem = {
29	  product_id: string;
30	  product_name: string;
31	  expected_qty: number;
32	  received_qty: number;
33	};
34	
35	export function CatalogPickerScreen({ navigation, route }: Props) {
36	  const { palette } = useTheme();
37	  const incomingBarcode = route.params?.barcode;
38	  const [products, setProducts] = useState<CanonicalProduct[]>([]);
39	  const [openItems, setOpenItems] = useState<OpenOrderItem[]>([]);
40	  const [query, setQuery] = useState('');
41	  const [loading, setLoading] = useState(true);
42	
43	  const loadFromCache = useCallback(async () => {
44	    const all = await listCanonicalProducts();
45	    setProducts(all);
46	
47	    // Items expected on today's open orders — surface these at the top
48	    // so the guard picks them in one tap.
49	    const db = await getDb();
50	    const rows = await db.getAllAsync<OpenOrderItem>(
51	      `SELECT oi.product_id, oi.product_name, oi.expected_qty, oi.received_qty
52	       FROM order_items oi
53	       JOIN orders o ON o.id = oi.order_id
54	       WHERE o.status = 'open' AND oi.product_id IS NOT NULL`,
55	    );
56	    setOpenItems(rows);
57	    setLoading(false);
58	  }, []);
59	
60	  const refresh = useCallback(async () => {
61	    // Pull a fresh catalog + open orders from the backend before
62	    // reading the local cache. Without this the screen shows
63	    // yesterday's data (or empty if the periodic sync hasn't fired).
64	    await Promise.all([syncCanonicalProducts(), syncOrders()]);
65	    await loadFromCache();
66	  }, [loadFromCache]);
67	
68	  // Refetch every time this screen comes into focus, not just on mount.
69	  useFocusEffect(
70	    useCallback(() => {
71	      void refresh();
72	    }, [refresh]),
73	  );
74	
75	  const { expected, others } = useMemo(() => {
76	    const q = query.trim().toLowerCase();
77	    const expectedIds = new Set(openItems.map((o) => o.product_id));
78	    const expectedRows = products
79	      .filter((p) => expectedIds.has(p.product_id))
80	      .map((p) => {
81	        const oi = openItems.find((o) => o.product_id === p.product_id);
82	        return {
83	          product: p,
84	          expected_qty: oi?.expected_qty ?? 0,
85	          received_qty: oi?.received_qty ?? 0,
86	        };
87	      });
88	    const otherRows = products.filter((p) => !expectedIds.has(p.product_id));
89	
90	    if (!q) return { expected: expectedRows, others: otherRows };
91	    const match = (s: string) => s.toLowerCase().includes(q);
92	    return {
93	      expected: expectedRows.filter(
94	        (r) =>
95	          match(r.product.canonical_name) ||
96	          match(r.product.category ?? '') ||
97	          match(r.product.hsn_code ?? ''),
98	      ),
99	      others: otherRows.filter(
100	        (p) =>
101	          match(p.canonical_name) ||
102	          match(p.category ?? '') ||
103	          match(p.hsn_code ?? ''),
104	      ),
105	    };
106	  }, [products, openItems, query]);
107	
108	  async function pick(product: CanonicalProduct) {
109	    // If we arrived from a barcode scan, learn the mapping NOW — before
110	    // the user finishes the receipt. Catches the case where the guard
111	    // backs out / cancels: next scan still auto-resolves correctly.
112	    if (incomingBarcode) {
113	      try {
114	        await learnBarcode(incomingBarcode, product.product_id, 'scan');
115	        await enqueue('learn_barcode', {
116	          barcode: incomingBarcode,
117	          product_id: product.product_id,
118	        }).catch(() => {});
119	      } catch {
120	        // Non-fatal: the receipt flow has its own learning step.
121	      }
122	    }
123	    const barcode = incomingBarcode ?? `catalog_${product.product_id}`;
124	    navigation.replace('Receiving', {
125	      barcode,
126	      productId: product.product_id,
127	      productName: product.canonical_name,
128	      unit: product.unit,
129	      packSize: product.pack_size,
130	    });
131	  }
132	
133	  type Row =
134	    | { kind: 'header'; key: string; label: string }
135	    | { kind: 'expected'; key: string; product: CanonicalProduct; expected_qty: number; received_qty: number }
136	    | { kind: 'product'; key: string; product: CanonicalProduct }
137	    | { kind: 'empty'; key: string };
138	
139	  const data: Row[] = useMemo(() => {
140	    const rows: Row[] = [];
141	    if (expected.length > 0) {
142	      rows.push({ kind: 'header', key: 'h-expected', label: 'Expected from open orders' });
143	      for (const r of expected) {
144	        rows.push({
145	          kind: 'expected',
146	          key: `e-${r.product.product_id}`,
147	          product: r.product,
148	          expected_qty: r.expected_qty,
149	          received_qty: r.received_qty,
150	        });
151	      }
152	    }
153	    if (others.length > 0) {
154	      rows.push({ kind: 'header', key: 'h-all', label: 'All products' });
155	      for (const p of others) {
156	        rows.push({ kind: 'product', key: `p-${p.product_id}`, product: p });
157	      }
158	    }
159	    if (expected.length === 0 && others.length === 0 && !loading) {
160	      rows.push({ kind: 'empty', key: 'empty' });
161	    }
162	    return rows;
163	  }, [expected, others, loading]);
164	
165	  return (
166	    <View style={[styles.safe, { backgroundColor: palette.background }]}>
167	      <AppBar
168	        title="Pick product"
169	        subtitle={`Choose from the catalog · ${products.length} item${products.length === 1 ? '' : 's'}`}
170	        onBack={() => navigation.goBack()}
171	        trailing={<IconButton Icon={RefreshCw} onPress={() => void refresh()} />}
172	      />
173	
174	      <View style={{ padding: spacing.md }}>
175	        <View
176	          style={{
177	            flexDirection: 'row',
178	            alignItems: 'center',
179	            gap: spacing.sm,
180	            paddingHorizontal: spacing.md,
181	            borderRadius: radius.md,
182	            backgroundColor: palette.surfaceContainerLowest,
183	            borderWidth: 1,
184	            borderColor: palette.outlineVariant,
185	          }}
186	        >
187	          <Search size={18} color={palette.onSurfaceVariant} strokeWidth={2.2} />
188	          <TextInput
189	            value={query}
190	            onChangeText={setQuery}
191	            placeholder="Search by name, category, HSN…"
192	            placeholderTextColor={palette.onSurfaceVariant}
193	            style={{ flex: 1, paddingVertical: spacing.md, color: palette.onSurface, fontSize: 15 }}
194	            autoCorrect={false}
195	            autoCapitalize="none"
196	          />
197	        </View>
198	      </View>
199	
200	      {loading ? (
201	        <View style={{ padding: spacing.md, gap: spacing.sm }}>
202	          <Skeleton height={60} />
203	          <Skeleton height={60} />
204	          <Skeleton height={60} />
205	        </View>
206	      ) : (
207	        <FlatList
208	          data={data}
209	          keyExtractor={(r) => r.key}
210	          contentContainerStyle={{ paddingHorizontal: spacing.md, paddingBottom: spacing.xl * 2, gap: spacing.sm }}
211	          renderItem={({ item }) => {
212	            if (item.kind === 'header') {
213	              return (
214	                <Text
215	                  variant="labelMedium"
216	                  color={palette.onSurfaceVariant}
217	                  style={{ marginTop: spacing.md, marginBottom: spacing.xs, textTransform: 'uppercase', letterSpacing: 0.6 }}
218	                >
219	                  {item.label}
220	                </Text>
221	              );
222	            }
223	            if (item.kind === 'empty') {
224	              return (
225	                <Card>
226	                  <View style={{ padding: spacing.lg, alignItems: 'center', gap: spacing.sm }}>
227	                    <Text variant="bodyLarge" color={palette.onSurfaceVariant} style={{ textAlign: 'center' }}>
228	                      No products match.
229	                    </Text>
230	                    <Text variant="labelMedium" color={palette.onSurfaceVariant} style={{ textAlign: 'center' }}>
231	                      Ask the admin to add this product, or flag it with a photo.
232	                    </Text>
233	                  </View>
234	                </Card>
235	              );
236	            }
237	            const p = item.product;
238	            const expectedQty = item.kind === 'expected' ? item.expected_qty : null;
239	            const receivedQty = item.kind === 'expected' ? item.received_qty : null;
240	            return (
241	              <Pressable onPress={() => { void pick(p); }}>
242	                <Card>
243	                  <View style={{ padding: spacing.md, flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', gap: spacing.md }}>
244	                    <View style={{ flex: 1 }}>
245	                      <Text variant="titleMedium">{p.canonical_name}</Text>
246	                      <View style={{ flexDirection: 'row', gap: spacing.sm, marginTop: 2, flexWrap: 'wrap' }}>
247	                        {p.category ? (
248	                          <Text variant="labelMedium" color={palette.onSurfaceVariant}>{p.category}</Text>
249	                        ) : null}
250	                        {p.hsn_code ? (
251	                          <Text variant="labelMedium" color={palette.onSurfaceVariant}>HSN {p.hsn_code}</Text>
252	                        ) : null}
253	                      </View>
254	                    </View>
255	                    <View style={{ alignItems: 'flex-end' }}>
256	                      <Text variant="titleMedium" color={palette.onSurface}>
257	                        {p.pack_size} {p.unit}
258	                      </Text>
259	                      {expectedQty !== null && (
260	                        <Text variant="labelMedium" color={palette.onSurfaceVariant}>
261	                          {receivedQty}/{expectedQty}
262	                        </Text>
263	                      )}
264	                    </View>
265	                  </View>
266	                </Card>
267	              </Pressable>
268	            );
269	          }}
270	          ListFooterComponent={
271	            <View style={{ marginTop: spacing.lg }}>
272	              <Pressable onPress={() => navigation.goBack()}>
273	                <Card>
274	                  <View style={{ padding: spacing.md, flexDirection: 'row', alignItems: 'center', gap: spacing.sm, justifyContent: 'center' }}>
275	                    <Camera size={18} color={palette.onSurfaceVariant} strokeWidth={2.2} />
276	                    <Text variant="labelLarge" color={palette.onSurfaceVariant}>
277	                      Not in this list? Flag with a photo
278	                    </Text>
279	                  </View>
280	                </Card>
281	              </Pressable>
282	            </View>
283	          }
284	        />
285	      )}
