import { NativeStackScreenProps } from '@react-navigation/native-stack';
import { useFocusEffect } from '@react-navigation/native';
import { Camera, RefreshCw, Search } from 'lucide-react-native';
import React, { useCallback, useMemo, useState } from 'react';
import { FlatList, Pressable, StyleSheet, TextInput, View } from 'react-native';
import {
  AppBar,
  Card,
  IconButton,
  radius,
  Skeleton,
  spacing,
  Text,
} from '../../../design';
import {
  CanonicalProduct,
  learnBarcode,
  listCanonicalProducts,
} from '../../../db/catalog';
import { enqueue } from '../../../db/outbox';
import { getDb } from '../../../db/database';
import { RootStackParamList } from '../../../navigation/types';
import { syncCanonicalProducts, syncOrders } from '../../../sync/syncService';
import { useTheme } from '../../../theme';

type Props = NativeStackScreenProps<RootStackParamList, 'CatalogPicker'>;

type OpenOrderItem = {
  product_id: string;
  product_name: string;
  expected_qty: number;
  received_qty: number;
};

export function CatalogPickerScreen({ navigation, route }: Props) {
  const { palette } = useTheme();
  const incomingBarcode = route.params?.barcode;
  const [products, setProducts] = useState<CanonicalProduct[]>([]);
  const [openItems, setOpenItems] = useState<OpenOrderItem[]>([]);
  const [query, setQuery] = useState('');
  const [loading, setLoading] = useState(true);

  const loadFromCache = useCallback(async () => {
    const all = await listCanonicalProducts();
    setProducts(all);

    // Items expected on today's open orders — surface these at the top
    // so the guard picks them in one tap.
    const db = await getDb();
    const rows = await db.getAllAsync<OpenOrderItem>(
      `SELECT oi.product_id, oi.product_name, oi.expected_qty, oi.received_qty
       FROM order_items oi
       JOIN orders o ON o.id = oi.order_id
       WHERE o.status = 'open' AND oi.product_id IS NOT NULL`,
    );
    setOpenItems(rows);
    setLoading(false);
  }, []);

  const refresh = useCallback(async () => {
    // Pull a fresh catalog + open orders from the backend before
    // reading the local cache. Without this the screen shows
    // yesterday's data (or empty if the periodic sync hasn't fired).
    await Promise.all([syncCanonicalProducts(), syncOrders()]);
    await loadFromCache();
  }, [loadFromCache]);

  // Refetch every time this screen comes into focus, not just on mount.
  useFocusEffect(
    useCallback(() => {
      void refresh();
    }, [refresh]),
  );

  const { expected, others } = useMemo(() => {
    const q = query.trim().toLowerCase();
    const expectedIds = new Set(openItems.map((o) => o.product_id));
    const expectedRows = products
      .filter((p) => expectedIds.has(p.product_id))
      .map((p) => {
        const oi = openItems.find((o) => o.product_id === p.product_id);
        return {
          product: p,
          expected_qty: oi?.expected_qty ?? 0,
          received_qty: oi?.received_qty ?? 0,
        };
      });
    const otherRows = products.filter((p) => !expectedIds.has(p.product_id));

    if (!q) return { expected: expectedRows, others: otherRows };
    const match = (s: string) => s.toLowerCase().includes(q);
    return {
      expected: expectedRows.filter(
        (r) =>
          match(r.product.canonical_name) ||
          match(r.product.category ?? '') ||
          match(r.product.hsn_code ?? ''),
      ),
      others: otherRows.filter(
        (p) =>
          match(p.canonical_name) ||
          match(p.category ?? '') ||
          match(p.hsn_code ?? ''),
      ),
    };
  }, [products, openItems, query]);

  async function pick(product: CanonicalProduct) {
    // If we arrived from a barcode scan, learn the mapping NOW — before
    // the user finishes the receipt. Catches the case where the guard
    // backs out / cancels: next scan still auto-resolves correctly.
    if (incomingBarcode) {
      try {
        await learnBarcode(incomingBarcode, product.product_id, 'scan');
        await enqueue('learn_barcode', {
          barcode: incomingBarcode,
          product_id: product.product_id,
        }).catch(() => {});
      } catch {
        // Non-fatal: the receipt flow has its own learning step.
      }
    }
    const barcode = incomingBarcode ?? `catalog_${product.product_id}`;
    navigation.replace('Receiving', {
      barcode,
      productId: product.product_id,
      productName: product.canonical_name,
      unit: product.unit,
      packSize: product.pack_size,
    });
  }

  type Row =
    | { kind: 'header'; key: string; label: string }
    | { kind: 'expected'; key: string; product: CanonicalProduct; expected_qty: number; received_qty: number }
    | { kind: 'product'; key: string; product: CanonicalProduct }
    | { kind: 'empty'; key: string };

  const data: Row[] = useMemo(() => {
    const rows: Row[] = [];
    if (expected.length > 0) {
      rows.push({ kind: 'header', key: 'h-expected', label: 'Expected from open orders' });
      for (const r of expected) {
        rows.push({
          kind: 'expected',
          key: `e-${r.product.product_id}`,
          product: r.product,
          expected_qty: r.expected_qty,
          received_qty: r.received_qty,
        });
      }
    }
    if (others.length > 0) {
      rows.push({ kind: 'header', key: 'h-all', label: 'All products' });
      for (const p of others) {
        rows.push({ kind: 'product', key: `p-${p.product_id}`, product: p });
      }
    }
    if (expected.length === 0 && others.length === 0 && !loading) {
      rows.push({ kind: 'empty', key: 'empty' });
    }
    return rows;
  }, [expected, others, loading]);

  return (
    <View style={[styles.safe, { backgroundColor: palette.background }]}>
      <AppBar
        title="Pick product"
        subtitle={`Choose from the catalog · ${products.length} item${products.length === 1 ? '' : 's'}`}
        onBack={() => navigation.goBack()}
        trailing={<IconButton Icon={RefreshCw} onPress={() => void refresh()} />}
      />

      <View style={{ padding: spacing.md }}>
        <View
          style={{
            flexDirection: 'row',
            alignItems: 'center',
            gap: spacing.sm,
            paddingHorizontal: spacing.md,
            borderRadius: radius.md,
            backgroundColor: palette.surfaceContainerLowest,
            borderWidth: 1,
            borderColor: palette.outlineVariant,
          }}
        >
          <Search size={18} color={palette.onSurfaceVariant} strokeWidth={2.2} />
          <TextInput
            value={query}
            onChangeText={setQuery}
            placeholder="Search by name, category, HSN…"
            placeholderTextColor={palette.onSurfaceVariant}
            style={{ flex: 1, paddingVertical: spacing.md, color: palette.onSurface, fontSize: 15 }}
            autoCorrect={false}
            autoCapitalize="none"
          />
        </View>
      </View>

      {loading ? (
        <View style={{ padding: spacing.md, gap: spacing.sm }}>
          <Skeleton height={60} />
          <Skeleton height={60} />
          <Skeleton height={60} />
        </View>
      ) : (
        <FlatList
          data={data}
          keyExtractor={(r) => r.key}
          contentContainerStyle={{ paddingHorizontal: spacing.md, paddingBottom: spacing.xl * 2, gap: spacing.sm }}
          renderItem={({ item }) => {
            if (item.kind === 'header') {
              return (
                <Text
                  variant="labelMedium"
                  color={palette.onSurfaceVariant}
                  style={{ marginTop: spacing.md, marginBottom: spacing.xs, textTransform: 'uppercase', letterSpacing: 0.6 }}
                >
                  {item.label}
                </Text>
              );
            }
            if (item.kind === 'empty') {
              return (
                <Card>
                  <View style={{ padding: spacing.lg, alignItems: 'center', gap: spacing.sm }}>
                    <Text variant="bodyLarge" color={palette.onSurfaceVariant} style={{ textAlign: 'center' }}>
                      No products match.
                    </Text>
                    <Text variant="labelMedium" color={palette.onSurfaceVariant} style={{ textAlign: 'center' }}>
                      Ask the admin to add this product, or flag it with a photo.
                    </Text>
                  </View>
                </Card>
              );
            }
            const p = item.product;
            const expectedQty = item.kind === 'expected' ? item.expected_qty : null;
            const receivedQty = item.kind === 'expected' ? item.received_qty : null;
            return (
              <Pressable onPress={() => { void pick(p); }}>
                <Card>
                  <View style={{ padding: spacing.md, flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', gap: spacing.md }}>
                    <View style={{ flex: 1 }}>
                      <Text variant="titleMedium">{p.canonical_name}</Text>
                      <View style={{ flexDirection: 'row', gap: spacing.sm, marginTop: 2, flexWrap: 'wrap' }}>
                        {p.category ? (
                          <Text variant="labelMedium" color={palette.onSurfaceVariant}>{p.category}</Text>
                        ) : null}
                        {p.hsn_code ? (
                          <Text variant="labelMedium" color={palette.onSurfaceVariant}>HSN {p.hsn_code}</Text>
                        ) : null}
                      </View>
                    </View>
                    <View style={{ alignItems: 'flex-end' }}>
                      <Text variant="titleMedium" color={palette.onSurface}>
                        {p.pack_size} {p.unit}
                      </Text>
                      {expectedQty !== null && (
                        <Text variant="labelMedium" color={palette.onSurfaceVariant}>
                          {receivedQty}/{expectedQty}
                        </Text>
                      )}
                    </View>
                  </View>
                </Card>
              </Pressable>
            );
          }}
          ListFooterComponent={
            <View style={{ marginTop: spacing.lg }}>
              <Pressable onPress={() => navigation.goBack()}>
                <Card>
                  <View style={{ padding: spacing.md, flexDirection: 'row', alignItems: 'center', gap: spacing.sm, justifyContent: 'center' }}>
                    <Camera size={18} color={palette.onSurfaceVariant} strokeWidth={2.2} />
                    <Text variant="labelLarge" color={palette.onSurfaceVariant}>
                      Not in this list? Flag with a photo
                    </Text>
                  </View>
                </Card>
              </Pressable>
            </View>
          }
        />
      )}
    </View>
  );
}

const styles = StyleSheet.create({
  safe: { flex: 1 },
});

