function OrderItemRow({ item, onChange }: { item: OrderItemFull; onChange: () => void }) {
  const [name, setName] = useState(item.product_name);
  const [qty, setQty] = useState(item.expected_qty);
  const [rate, setRate] = useState<number | null>(item.unit_rate);
  const [hsn, setHsn] = useState(item.hsn_code ?? "");
  const [unit, setUnit] = useState(item.unit ?? "pcs");
  const [packSize, setPackSize] = useState<number>(item.pack_size ?? 1);

  const itemDirty =
    name !== item.product_name ||
    qty !== item.expected_qty ||
    rate !== item.unit_rate ||
    hsn !== (item.hsn_code ?? "");

  const catalogDirty =
    unit !== (item.unit ?? "pcs") ||
    packSize !== (item.pack_size ?? 1);

  const saveItemMutation = useMutation({
    mutationFn: () => updateOrderItem(item.id, { canonical_name: name, qty, rate, hsn_code: hsn || null }),
    onSuccess: (res) => {
      if (!res.ok) { toastError(errorMessage((res.data as { error?: string }).error, "Update failed")); return; }
      onChange();
    },
    onError: (err) => toastError(err, "Update failed"),
  });

  const saveCatalogMutation = useMutation({
    mutationFn: () => {
      if (!item.product_id) throw new Error("Item is not linked to a catalog product");
      return patchCanonicalProduct(item.product_id, { unit, pack_size: packSize });
    },
    onSuccess: (res) => {
      if (!res.ok) { toastError(errorMessage((res.data as { error?: string }).error, "Update failed")); return; }
      onChange();
    },
    onError: (err) => toastError(err, "Update failed"),
  });

  const deleteMutation = useMutation({
    mutationFn: () => deleteOrderItem(item.id),
    onSuccess: (res) => {
      if (!res.ok) { toastError(errorMessage((res.data as { error?: string }).error, "Delete failed")); return; }
      toastSuccess("Item removed");
      onChange();
    },
    onError: (err) => toastError(err, "Delete failed"),
  });

  // Received column: show "X of Y" with the actual received count
  // prominent. Green when fully received, amber if over, default
  // otherwise. The big "X / Y" with raw concatenated numbers was easy
  // to misread when both values were multi-digit.
  const receivedColor =
    item.received_qty === 0 ? "var(--muted)" :
    item.received_qty >= item.expected_qty ? "#16a34a" :
    "var(--text)";

  return (
    <tr>
      <td style={tdCell}>
        <input value={name} onChange={(e) => setName(e.target.value)} onBlur={() => itemDirty && saveItemMutation.mutate()} style={cellInput} />
      </td>
      <td style={tdCell}>
        <input value={hsn} onChange={(e) => setHsn(e.target.value)} onBlur={() => itemDirty && saveItemMutation.mutate()} style={cellInput} />
      </td>
      <td style={tdCell}>
        <input type="number" step="any" value={qty} onChange={(e) => setQty(Number(e.target.value) || 0)} onBlur={() => itemDirty && saveItemMutation.mutate()} style={{ ...cellInput, textAlign: "right" }} />
      </td>
      <td style={tdCell}>
        <input type="number" step="any" value={rate ?? ""} onChange={(e) => setRate(e.target.value === "" ? null : Number(e.target.value))} onBlur={() => itemDirty && saveItemMutation.mutate()} style={{ ...cellInput, textAlign: "right" }} />
      </td>
      <td style={tdCell}>
        <input
          type="number"
          step="any"
          value={packSize}
          onChange={(e) => setPackSize(Number(e.target.value) || 1)}
          onBlur={() => catalogDirty && item.product_id && saveCatalogMutation.mutate()}
          disabled={!item.product_id}
          style={{ ...cellInput, textAlign: "right", opacity: item.product_id ? 1 : 0.4 }}
          title={item.product_id ? "Pack size (updates the catalog product)" : "Not linked to a catalog product"}
        />
      </td>
      <td style={tdCell}>
        <select
          value={unit}
          onChange={(e) => setUnit(e.target.value)}
          onBlur={() => catalogDirty && item.product_id && saveCatalogMutation.mutate()}
          disabled={!item.product_id}
          style={{ ...cellInput, opacity: item.product_id ? 1 : 0.4 }}
          title={item.product_id ? "Unit (updates the catalog product)" : "Not linked to a catalog product"}
        >
          {UNIT_OPTIONS.map((u) => <option key={u} value={u}>{u}</option>)}
          {!UNIT_OPTIONS.includes(unit) && <option value={unit}>{unit}</option>}
        </select>
      </td>
      <td style={{ ...tdCell, textAlign: "right" }}>
        <div style={{ display: "flex", alignItems: "baseline", justifyContent: "flex-end", gap: 4 }}>
          <span style={{ fontWeight: 600, fontSize: 13, color: receivedColor }}>{item.received_qty}</span>
          <span style={{ color: "var(--muted)", fontSize: 11 }}>of {item.expected_qty}</span>
        </div>
      </td>
      <td style={{ ...tdCell, textAlign: "right" }}>
        <button
          type="button"
          onClick={() => { if (confirm(`Remove "${item.product_name}" from this order?`)) deleteMutation.mutate(); }}
          style={{ ...iconBtn, color: "#dc2626" }}
          title="Remove item"
        >
          <Trash2 size={12} />
        </button>
      </td>
    </tr>
  );
}

