export async function deleteOrder(siteId: string, orderId: string): Promise<{ deleted: boolean }> {
  const db = await getDb();
  // Detach any receipts pointing at this order so the audit trail
  // survives but the FK doesn't block the delete. This works whether
  // or not the migration to ON DELETE SET NULL has run.
  await db.execute({
    sql: `UPDATE inventory_receipts SET order_item_id = NULL
          WHERE order_item_id IN (
            SELECT id FROM inventory_order_items WHERE order_id = ?
          )`,
    args: [orderId],
  });
  await db.execute({
    sql: `UPDATE inventory_receipts SET order_id = NULL WHERE order_id = ?`,
    args: [orderId],
  });
  await db.execute({
    sql: `UPDATE inventory_mismatch_flags SET order_item_id = NULL
          WHERE order_item_id IN (
            SELECT id FROM inventory_order_items WHERE order_id = ?
          )`,
    args: [orderId],
  });
  // ON DELETE CASCADE on inventory_order_items removes the items.
  const result = await db.execute({
    sql: `DELETE FROM inventory_orders WHERE id = ? AND site_id = ?`,
    args: [orderId, siteId],
  });
  return { deleted: (result.rowsAffected ?? 0) > 0 };
}

