/**
 * Telegram Command Handlers
 *
 * All /command handlers for the Telegram bot.
 * Extracted from the monolithic server.ts.
 *
 * These handlers are Telegram-specific because they use inline keyboards,
 * Telegram-specific formatting, and SOP checklist UI.
 */

import type TelegramBot from "node-telegram-bot-api";
import { mastra } from "../../index";
import { getBot, getSenderName, getMediaFileId } from "./bot";
import { sendMessage } from "./sender";
import { downloadTelegramMedia } from "./media";
import { readFileSync } from "fs";
import {
  logInfo,
  logWarn,
  logError,
} from "../../lib/logger";
import { telegram as tgConfig } from "../../lib/config";
import {
  createDailySOPs,
  createDailySOPsFromConfig,
  getSOPStats,
  getSOPTasks,
  resetDatabase,
  addStaff,
  updateStaff,
  removeStaff,
  getAllActiveStaff,
  getStaffByRole,
  linkStaffChannel,
  importStaffFromCSV,
  queryStaffDirectory,
  type DailySOPStats,
  type SOPTask,
} from "../../lib/database";
import { refreshStaffCache } from "../../core/staff-registry";
import { clearAllSheets, syncToGoogleSheets } from "../../lib/google-sheets";
import { deleteAllVectors } from "../../lib/pinecone";
import { formatShortDateTimeInIST, getCurrentISTDate } from "../../lib/time";
import type { StaffRole } from "../../lib/types";
import type { ChannelType } from "../../core/types";
import {
  createVisitorInvite,
  parseInviteCommand,
  queryVisitorManagementRecords,
  registerGuard,
  triggerLockdown,
  bulkInviteFromExcel,
} from "../../plugins/visitor";

// ─── Helpers ──────────────────────────────────────────────

function getErrorMessage(error: unknown): string {
  if (error instanceof Error) {
    return error.message;
  }
  return String(error);
}

function resolveSOPDate(input?: string): string {
  if (input && /^\d{4}-\d{2}-\d{2}$/.test(input)) {
    return input;
  }
  return getCurrentISTDate();
}

async function sendNonEmptyResponse(
  chatId: number,
  text: string | undefined,
  fallbackText: string,
  options?: {
    parseMode?: "Markdown" | "HTML" | "MarkdownV2";
    replyToMessageId?: number;
  },
): Promise<void> {
  const normalized = text?.trim();
  if (!normalized) {
    logWarn(`Generated response was empty. Falling back to: ${fallbackText}`);
    await sendMessage(chatId, fallbackText, options);
    return;
  }
  await sendMessage(chatId, normalized, options);
}

function formatVisitorManagementStatus(record: {
  currentlyInside: boolean;
  checkinTime?: string | null;
  checkoutTime?: string | null;
  approvalStatus: string;
}): string {
  if (record.currentlyInside && record.checkinTime) {
    return `Inside since ${formatShortDateTimeInIST(record.checkinTime)}`;
  }
  if (record.checkoutTime) {
    return `Exited at ${formatShortDateTimeInIST(record.checkoutTime)}`;
  }
  return `Status: ${record.approvalStatus}`;
}

async function sendCafeteriaMiniAppButton(chatId: number): Promise<void> {
  const url = tgConfig.cafeteriaMiniAppUrl();
  if (!url) {
    await sendMessage(
      chatId,
      "⚠️ Cafeteria Mini App URL is not configured. Set CAFETERIA_MINI_APP_URL to the public HTTPS Mini App URL and restart the engine.",
    );
    return;
  }

  const bot = getBot();
  await bot.sendMessage(
    chatId,
    "🍽️ Open the cafeteria ordering app to take employee orders.",
    {
      reply_markup: {
        inline_keyboard: [
          [
            {
              text: "Open Cafeteria",
              web_app: { url },
            } as any,
          ],
        ],
      },
    },
  );
}

// ─── SOP UI Builders ──────────────────────────────────────

function getSOPStatusSymbol(status: "pending" | "completed"): string {
  return status === "completed" ? "☑" : "☐";
}

export function buildSOPKeyboard(
  dateStr: string,
  sops: SOPTask[],
): TelegramBot.InlineKeyboardButton[][] {
  return sops.map((sop) => [
    {
      text: `${getSOPStatusSymbol(sop.status)} ${sop.task_name}`,
      callback_data: `sop_toggle:${dateStr}:${sop.id}`,
    },
  ]);
}

export function buildSOPChecklistText(
  dateStr: string,
  sops: SOPTask[],
  options?: { lastUpdatedBy?: string },
): string {
  const completedCount = sops.filter(
    (sop) => sop.status === "completed",
  ).length;
  const pendingCount = sops.length - completedCount;

  const lines = [
    `*Daily SOP Checklist* (${dateStr})`,
    `Completed: ${completedCount}/${sops.length}`,
    `Pending: ${pendingCount}`,
  ];

  if (options?.lastUpdatedBy) {
    lines.push(`Last updated by: ${options.lastUpdatedBy}`);
  }

  lines.push("", "Select a task to update its status.");
  return lines.join("\n");
}

function buildSOPStatsText(stats: DailySOPStats): string {
  const lines = [
    `*Daily SOP Stats* (${stats.date})`,
    `Completion: ${stats.completedTasks}/${stats.totalTasks} (${stats.completionRate}%)`,
    `Pending: ${stats.pendingTasks}`,
  ];

  if (stats.byAssignee.length > 0) {
    lines.push("", "*By Assignee*");
    for (const group of stats.byAssignee) {
      lines.push(
        `- ${group.assignee}: ${group.completedTasks}/${group.totalTasks} completed`,
      );
    }
  }

  if (stats.completedBy.length > 0) {
    lines.push("", "*Completed By*");
    for (const group of stats.completedBy) {
      lines.push(`- ${group.staffName}: ${group.completedTasks} task(s)`);
    }
  }

  if (stats.totalTasks === 0) {
    lines.push("", "No SOP tasks exist for this date.");
  }

  return lines.join("\n");
}

function buildResetKeyboard(
  requesterId: number,
): TelegramBot.InlineKeyboardButton[][] {
  return [
    [
      {
        text: "✅ Yes, Reset Everything",
        callback_data: `reset_confirm:${requesterId}`,
      },
    ],
    [
      {
        text: "❌ Cancel",
        callback_data: `reset_cancel:${requesterId}`,
      },
    ],
  ];
}

// ─── SOP Delivery ─────────────────────────────────────────

export async function sendSOPChecklistToStaff(
  dateStr: string,
  sops: SOPTask[],
  excludeChatId?: number,
): Promise<{ sent: number; failed: number }> {
  const bot = getBot();
  const staffIds = [...new Set(tgConfig.sopStaffIds())].filter(
    (staffId) => staffId !== excludeChatId,
  );

  let sent = 0;
  let failed = 0;

  for (const staffId of staffIds) {
    try {
      await bot.sendMessage(staffId, buildSOPChecklistText(dateStr, sops), {
        parse_mode: "Markdown",
        reply_markup: {
          inline_keyboard: buildSOPKeyboard(dateStr, sops),
        },
      });
      sent += 1;
    } catch (error) {
      failed += 1;
      logWarn(
        `Failed to send SOP checklist to staff chat ${staffId}: ${getErrorMessage(error)}`,
      );
    }
  }

  return { sent, failed };
}

// ─── whereami Helper ──────────────────────────────────────

export function isWhereAmICommand(text: string | undefined): boolean {
  if (!text) return false;
  const command = text.trim().split(/\s+/)[0]?.split("@")[0];
  return command === "/whereami";
}

export async function replyWithChatDetails(msg: TelegramBot.Message): Promise<void> {
  const chatLabel = msg.chat.title || msg.chat.username || getSenderName(msg);
  logInfo(`Returning chat details for ${msg.chat.type} chat ${msg.chat.id}`);
  await sendMessage(
    msg.chat.id,
    [
      "Current chat details",
      `Chat ID: ${msg.chat.id}`,
      `Chat type: ${msg.chat.type}`,
      `Chat label: ${chatLabel}`,
      "",
      "Use this value for TELEGRAM_LOG_CHANNEL_ID if you want logs sent here.",
    ].join("\n"),
  );
}

// ─── Main Command Router ─────────────────────────────────

export async function handleCommand(msg: TelegramBot.Message, command: string): Promise<void> {
  const parts = command.trim().split(/\s+/);
  const cmd = parts[0]?.split("@")[0] ?? "";
  const args = parts.slice(1);
  logInfo(`Handling command ${cmd}`);

  switch (cmd) {
    case "/summary": {
      const bot = getBot();
      await bot.sendChatAction(msg.chat.id, "typing");

      const workflow = mastra.getWorkflow("dailySummaryWorkflow");
      if (!workflow) {
        await sendMessage(msg.chat.id, "⚠️ Summary workflow not available.");
        return;
      }

      const run = await workflow.createRun();
      const result = await run.start({
        inputData: { triggerType: "manual" },
      });

      const step = Object.values(result.steps).pop();
      if (step?.status === "success") {
        const output = step.output as Record<string, unknown>;
        await sendMessage(msg.chat.id, output.formattedReport as string, {
          parseMode: "Markdown",
        });
      } else {
        await sendMessage(msg.chat.id, "⚠️ Failed to generate summary.");
      }
      break;
    }

    case "/sop": {
      // /sop trigger [shift] — manual trigger from config
      if (args[0] === "trigger") {
        const shift = args[1] || undefined;
        const dateStr = getCurrentISTDate();
        await sendMessage(msg.chat.id, `⏳ Creating SOPs from config for ${dateStr}${shift ? ` (shift: ${shift})` : ''}...`);

        try {
          const result = await createDailySOPsFromConfig(dateStr, shift);
          const lines = [`✅ *SOP Trigger Complete*`, `Created: ${result.created} tasks`, "", "*Assignments:*"];
          for (const a of result.assignments) {
            lines.push(`• ${a}`);
          }
          await sendMessage(msg.chat.id, lines.join("\n"), { parseMode: "Markdown" });

          // Show the checklist if tasks were created
          if (result.created > 0) {
            const sops = await getSOPTasks(dateStr);
            const bot = getBot();
            await bot.sendMessage(msg.chat.id, buildSOPChecklistText(dateStr, sops), {
              parse_mode: "Markdown",
              reply_markup: {
                inline_keyboard: buildSOPKeyboard(dateStr, sops),
              },
            });

            const staffDelivery = await sendSOPChecklistToStaff(dateStr, sops, msg.chat.id);
            if (staffDelivery.sent > 0) {
              await sendMessage(msg.chat.id, `📨 SOP checklist forwarded to ${staffDelivery.sent} staff chat(s).`);
            }
          }
        } catch (error) {
          await sendMessage(msg.chat.id, `❌ SOP trigger failed: ${getErrorMessage(error)}`);
        }
        break;
      }

      // Default: /sop [date] — original behavior
      const dateStr = resolveSOPDate(args[0]);
      await createDailySOPs(dateStr);
      const sops = await getSOPTasks(dateStr);

      const bot = getBot();

      await bot.sendMessage(msg.chat.id, buildSOPChecklistText(dateStr, sops), {
        parse_mode: "Markdown",
        reply_markup: {
          inline_keyboard: buildSOPKeyboard(dateStr, sops),
        },
      });

      const staffDelivery = await sendSOPChecklistToStaff(
        dateStr,
        sops,
        msg.chat.id,
      );
      if (staffDelivery.sent > 0 || staffDelivery.failed > 0) {
        const parts = [
          `📨 SOP checklist forwarded to ${staffDelivery.sent} staff chat(s).`,
        ];
        if (staffDelivery.failed > 0) {
          parts.push(`${staffDelivery.failed} delivery attempt(s) failed.`);
        }
        await sendMessage(msg.chat.id, parts.join(" "));
      }

      break;
    }

    case "/sopstats": {
      const dateStr = resolveSOPDate(args[0]);
      const stats = await getSOPStats(dateStr);
      await sendMessage(msg.chat.id, buildSOPStatsText(stats), {
        parseMode: "Markdown",
      });
      break;
    }

    case "/visitors": {
      const records = await queryVisitorManagementRecords({
        scope: "today",
        date: getCurrentISTDate(),
        limit: 20,
      });
      if (records.length === 0) {
        await sendMessage(
          msg.chat.id,
          "👥 *Today's Visitors*\n\nNo visitor activity is recorded in the live visitor management system today.",
          { parseMode: "Markdown" },
        );
        break;
      }

      const lines = records.map((record, index) => {
        const parts = [
          `${index + 1}. *${record.visitorName}*`,
          formatVisitorManagementStatus(record),
        ];
        if (record.hostName) parts.push(`Host: ${record.hostName}`);
        if (record.purpose) parts.push(`Purpose: ${record.purpose}`);
        if (record.visitorPhone) parts.push(`Phone: ${record.visitorPhone}`);
        return parts.join(" | ");
      });

      await sendMessage(
        msg.chat.id,
        `👥 *Today's Visitors*\nSource: live visitor management system\n\n${lines.join("\n")}`,
        { parseMode: "Markdown" },
      );
      break;
    }

    case "/inventory": {
      const agent = mastra.getAgent("queryAgent");
      if (!agent) return;
      const result = await agent.generate([
        { role: "user", content: "Show me today's inventory updates" },
      ]);
      await sendNonEmptyResponse(
        msg.chat.id,
        result.text,
        "I could not generate the inventory summary right now.",
        { parseMode: "Markdown" },
      );
      break;
    }

    case "/facilities": {
      const agent = mastra.getAgent("queryAgent");
      if (!agent) return;
      const result = await agent.generate([
        { role: "user", content: "Show me open facility requests" },
      ]);
      await sendNonEmptyResponse(
        msg.chat.id,
        result.text,
        "I could not generate the facility summary right now. Please try again.",
        { parseMode: "Markdown" },
      );
      break;
    }

    case "/assets": {
      const agent = mastra.getAgent("queryAgent");
      if (!agent) return;
      const result = await agent.generate([
        { role: "user", content: "Show me asset tracking status" },
      ]);
      await sendNonEmptyResponse(
        msg.chat.id,
        result.text,
        "I could not generate the asset summary right now.",
        { parseMode: "Markdown" },
      );
      break;
    }

    case "/whereami":
      await replyWithChatDetails(msg);
      break;

    case "/cafeteria":
    case "/canteen":
      await sendCafeteriaMiniAppButton(msg.chat.id);
      break;

    case "/help":
      await sendMessage(
        msg.chat.id,
        `🤖 *Office Operations Intelligence Bot*

*Commands:*
/summary — Today's full operations summary
/visitors — Today's visitor list
/cafeteria — Open cafeteria ordering app
/inventory — Inventory status
/facilities — Open maintenance requests
/assets — Asset tracking status
/sopstats — Daily SOP progress summary
/whereami — Show this chat ID
/export — Sync all data to Google Sheets
/reset — Delete DB, Pinecone, and Sheets data
/sop — Daily SOP checklist
/staff — Staff registry management
/help — This message

*Visitor Commands:*
/invite Name, purpose, host, date, email, start: HH:MM, end: HH:MM — Invite a visitor
/guard add "Name" PIN [language] — Create guard account
/lockdown — 🚨 Emergency visitor headcount

*Staff Commands:*
/staff list — Show all staff
/staff attendance — See who is in the office
/staff add "Name" role [phone] [gender] — Add staff
/staff roles — Staff grouped by role
/staff import — Import from data/staff.csv
/staff link <id> <channel> <uid> — Link to platform
/staff remove <id> — Deactivate staff

*Natural Language Queries:*
• "Who visited today?"
• "Who has laptop 23?"
• "Any open maintenance requests?"
• "What's the milk status this week?"
• "Show me overdue facility issues"
• "Prove it" / "Show evidence"

Just type your question and I'll find the answer! 🔍`,
        { parseMode: "Markdown" },
      );
      break;

    case "/export": {
      const bot = getBot();
      await bot.sendChatAction(msg.chat.id, "typing");
      await sendMessage(msg.chat.id, "📊 Syncing data to Google Sheets...");
      const exportResult = await syncToGoogleSheets();
      await sendMessage(msg.chat.id, exportResult.message);
      break;
    }

    case "/reset": {
      const requesterId = msg.from?.id;
      if (!requesterId) {
        await sendMessage(
          msg.chat.id,
          "⚠️ Could not determine who requested the reset.",
        );
        break;
      }

      const bot = getBot();
      await bot.sendMessage(
        msg.chat.id,
        "⚠️ Are you sure? This will delete ALL data - database, Pinecone vectors, and Google Sheets. This cannot be undone.",
        {
          reply_markup: {
            inline_keyboard: buildResetKeyboard(requesterId),
          },
        },
      );
      break;
    }

    case "/staff":
      await handleStaffCommand(msg, args);
      break;

    case "/invite":
      await handleInviteCommand(msg, args);
      break;

    case "/batchinvite":
      await handleBatchInviteCommand(msg, args);
      break;

    case "/guard":
      await handleGuardCommand(msg, args);
      break;

    case "/lockdown":
      await handleLockdownCommand(msg);
      break;

    default:
      await sendMessage(
        msg.chat.id,
        "❓ Unknown command. Type /help for available commands.",
      );
  }
}

// ─── Staff Command Handler ────────────────────────────────

async function handleStaffCommand(msg: TelegramBot.Message, args: string[]): Promise<void> {
  const subCmd = args[0]?.toLowerCase() || "help";

  switch (subCmd) {
    case "attendance": {
      const staff = await queryStaffDirectory();
      const activeStaff = staff.filter((s) => s.attendanceStatus === 'in');

      if (activeStaff.length === 0) {
        await sendMessage(msg.chat.id, "🏢 No staff members are currently marked IN.");
        return;
      }

      const lines = activeStaff.map((s) => {
        return `👤 *${s.name}* (${s.role})${s.department ? ` - ${s.department}` : ''}`;
      });

      await sendMessage(
        msg.chat.id, 
        `🏢 *Staff Currently In Office* (${activeStaff.length})\n\n${lines.join('\n')}`, 
        { parseMode: "Markdown" }
      );
      break;
    }

    case "list": {
      const staff = await getAllActiveStaff();
      if (staff.length === 0) {
        await sendMessage(msg.chat.id, "📋 No staff members registered yet.\nUse `/staff add \"Name\" role` to add one.", { parseMode: "Markdown" });
        return;
      }

      const lines = staff.map((s, i) => {
        const parts = [`${i + 1}. *${s.name}* (${s.role})`];
        if (s.phone) parts.push(`📱 ${s.phone}`);
        if (s.gender) parts.push(`${s.gender === "male" ? "♂" : s.gender === "female" ? "♀" : "⚧"}`);
        if (s.department) parts.push(`🏢 ${s.department}`);
        if (s.language) parts.push(`🗣 ${s.language}`);
        if (s.channels && s.channels.length > 0) {
          const chLinks = s.channels.map((c) => `${c.channel}:${c.channelUid}`).join(", ");
          parts.push(`🔗 ${chLinks}`);
        }
        parts.push(`\`${s.id.slice(0, 8)}\``);
        return parts.join(" | ");
      });

      await sendMessage(
        msg.chat.id,
        `👥 *Staff Directory* (${staff.length} members)\n\n${lines.join("\n")}`,
        { parseMode: "Markdown" },
      );
      break;
    }

    case "add": {
      // /staff add "Name" role [phone] [gender] [department]
      // Parse quoted name
      const restText = args.slice(1).join(" ");
      const quotedMatch = restText.match(/^"([^"]+)"\s+(.*)$/);
      let name: string;
      let remaining: string;

      if (quotedMatch) {
        name = quotedMatch[1]!;
        remaining = quotedMatch[2]!;
      } else {
        // No quotes — first arg is name, rest follows
        name = args[1] || "";
        remaining = args.slice(2).join(" ");
      }

      if (!name) {
        await sendMessage(msg.chat.id, '⚠️ Usage: `/staff add "Full Name" role [phone] [gender] [department] [language]`\nRoles: manager, lead, staff\nLanguages: hindi, english, hinglish', { parseMode: "Markdown" });
        return;
      }

      const parts = remaining.split(/\s+/);
      const role = parts[0]?.toLowerCase();
      if (!role || !["manager", "lead", "staff"].includes(role)) {
        await sendMessage(msg.chat.id, `⚠️ Invalid role "${role}". Must be: manager, lead, or staff.`);
        return;
      }

      const phone = parts[1] || undefined;
      const gender = parts[2]?.toLowerCase() as "male" | "female" | "other" | undefined;
      const department = parts[3] || undefined;
      const language = parts[4]?.toLowerCase() || undefined;

      try {
        const id = await addStaff({
          name,
          role: role as StaffRole,
          phone,
          gender: gender && ["male", "female", "other"].includes(gender) ? gender : undefined,
          department,
          language,
        });
        await refreshStaffCache();
        await sendMessage(
          msg.chat.id,
          `✅ Staff added: *${name}* (${role})\nID: \`${id.slice(0, 8)}\``,
          { parseMode: "Markdown" },
        );
      } catch (error) {
        await sendMessage(msg.chat.id, `❌ Failed to add staff: ${getErrorMessage(error)}`);
      }
      break;
    }

    case "update": {
      // /staff update <id> <field> <value>
      const staffId = args[1];
      const field = args[2]?.toLowerCase();
      const value = args.slice(3).join(" ");

      if (!staffId || !field || !value) {
        await sendMessage(msg.chat.id, "⚠️ Usage: `/staff update <id> <field> <value>`\nFields: name, phone, gender, role, department", { parseMode: "Markdown" });
        return;
      }

      const validFields = ["name", "phone", "gender", "role", "department", "language"];
      if (!validFields.includes(field)) {
        await sendMessage(msg.chat.id, `⚠️ Invalid field "${field}". Valid: ${validFields.join(", ")}`);
        return;
      }

      try {
        // Find staff by ID prefix
        const allStaff = await getAllActiveStaff();
        const match = allStaff.find((s) => s.id.startsWith(staffId));
        if (!match) {
          await sendMessage(msg.chat.id, `⚠️ No staff found with ID starting with "${staffId}"`);
          return;
        }

        await updateStaff(match.id, { [field]: value } as any);
        await refreshStaffCache();
        await sendMessage(msg.chat.id, `✅ Updated *${match.name}*: ${field} = "${value}"`, { parseMode: "Markdown" });
      } catch (error) {
        await sendMessage(msg.chat.id, `❌ Failed: ${getErrorMessage(error)}`);
      }
      break;
    }

    case "remove": {
      const staffId = args[1];
      if (!staffId) {
        await sendMessage(msg.chat.id, "⚠️ Usage: `/staff remove <id>`", { parseMode: "Markdown" });
        return;
      }

      const allStaff = await getAllActiveStaff();
      const match = allStaff.find((s) => s.id.startsWith(staffId));
      if (!match) {
        await sendMessage(msg.chat.id, `⚠️ No staff found with ID starting with "${staffId}"`);
        return;
      }

      await removeStaff(match.id);
      await refreshStaffCache();
      await sendMessage(msg.chat.id, `✅ Deactivated: *${match.name}*`, { parseMode: "Markdown" });
      break;
    }

    case "link": {
      // /staff link <id> <channel> <channel_uid> [username]
      const staffId = args[1];
      const channel = args[2]?.toLowerCase() as ChannelType;
      const uid = args[3];
      const uname = args[4];

      if (!staffId || !channel || !uid) {
        await sendMessage(msg.chat.id, "⚠️ Usage: `/staff link <id> <channel> <uid> [username]`\nChannels: telegram, whatsapp, slack", { parseMode: "Markdown" });
        return;
      }

      const validChannels = ["telegram", "whatsapp", "slack"];
      if (!validChannels.includes(channel)) {
        await sendMessage(msg.chat.id, `⚠️ Invalid channel "${channel}". Valid: ${validChannels.join(", ")}`);
        return;
      }

      const allStaff = await getAllActiveStaff();
      const match = allStaff.find((s) => s.id.startsWith(staffId));
      if (!match) {
        await sendMessage(msg.chat.id, `⚠️ No staff found with ID starting with "${staffId}"`);
        return;
      }

      try {
        await linkStaffChannel(match.id, channel, uid, uname);
        await refreshStaffCache();
        await sendMessage(msg.chat.id, `✅ Linked *${match.name}* → ${channel}:${uid}`, { parseMode: "Markdown" });
      } catch (error) {
        await sendMessage(msg.chat.id, `❌ Failed: ${getErrorMessage(error)}`);
      }
      break;
    }

    case "roles": {
      const managers = await getStaffByRole("manager");
      const leads = await getStaffByRole("lead");
      const staffMembers = await getStaffByRole("staff");

      const formatList = (list: typeof managers) =>
        list.length === 0
          ? "  (none)"
          : list.map((s) => `  • ${s.name}${s.phone ? ` (${s.phone})` : ""}${s.language ? ` 🗣${s.language}` : ""}`).join("\n");

      await sendMessage(
        msg.chat.id,
        `👥 *Staff by Role*\n\n` +
        `*📊 Managers (${managers.length})*\n${formatList(managers)}\n\n` +
        `*🔧 Leads (${leads.length})*\n${formatList(leads)}\n\n` +
        `*👤 Staff (${staffMembers.length})*\n${formatList(staffMembers)}`,
        { parseMode: "Markdown" },
      );
      break;
    }

    case "import": {
      const csvPath = args[1] || "data/staff.csv";
      await sendMessage(msg.chat.id, `📥 Importing from \`${csvPath}\`...`, { parseMode: "Markdown" });

      try {
        const result = await importStaffFromCSV(csvPath);
        await refreshStaffCache();

        const lines = [`✅ *Import Complete*`, `Imported: ${result.imported}`, `Skipped: ${result.skipped}`];
        if (result.errors.length > 0) {
          lines.push("", "*Errors:*");
          for (const err of result.errors.slice(0, 10)) {
            lines.push(`• ${err}`);
          }
          if (result.errors.length > 10) {
            lines.push(`... and ${result.errors.length - 10} more`);
          }
        }
        await sendMessage(msg.chat.id, lines.join("\n"), { parseMode: "Markdown" });
      } catch (error) {
        await sendMessage(msg.chat.id, `❌ Import failed: ${getErrorMessage(error)}`);
      }
      break;
    }

    default:
      await sendMessage(
        msg.chat.id,
        `👥 *Staff Registry Commands*\n\n` +
        `/staff list — Show all staff\n` +
        `/staff add "Name" role [phone] [gender] [dept] [lang] — Add\n` +
        `/staff update <id> <field> <value> — Update\n` +
        `/staff remove <id> — Deactivate\n` +
        `/staff link <id> <channel> <uid> — Link platform\n` +
        `/staff roles — Grouped by role\n` +
        `/staff import [path] — Import from CSV\n\n` +
        `Fields: name, phone, gender, role, department, language`,
        { parseMode: "Markdown" },
      );
  }
}

// ─── Invite Command Handler ───────────────────────────────────

async function handleInviteCommand(msg: TelegramBot.Message, args: string[]): Promise<void> {
  const argsText = args.join(" ").trim();

  if (!argsText) {
    await sendMessage(
      msg.chat.id,
      `📋 *Invite a Visitor*\n\nUsage: \`/invite Name, Purpose, Host, Date, Email\`\nOptional time windows: \`start: HH:MM\`, \`end: HH:MM\`\n\nExamples:\n• \`/invite Rajesh Kumar, Meeting, Ankit, today, start: 10:00, end: 13:00, rajesh@example.com\`\n• \`/invite Priya Patel, Delivery, 2026-04-20, start: 09:30, end: 11:00\`\n• \`/invite "Rahul Sharma", Interview, HR Team, tomorrow, rahul@example.com\``,
      { parseMode: "Markdown" },
    );
    return;
  }

  const parsed = parseInviteCommand(argsText);
  if (!parsed || !parsed.visitorName) {
    await sendMessage(msg.chat.id, "⚠️ Could not parse invite. Usage: `/invite Name, Purpose, Host, Date, Email, start: HH:MM, end: HH:MM`", { parseMode: "Markdown" });
    return;
  }

  const senderName = msg.from?.first_name ?? "Admin";
  await sendMessage(msg.chat.id, `⏳ Creating invite for *${parsed.visitorName}*...`, { parseMode: "Markdown" });

  try {
    const result = await createVisitorInvite({
      visitorName: parsed.visitorName,
      visitorEmail: parsed.visitorEmail,
      purpose: parsed.purpose,
      hostEmployeeName: parsed.hostEmployeeName,
      expectedDate: parsed.expectedDate ?? getCurrentISTDate(),
      expectedTime: parsed.expectedTime,
      validFrom: parsed.validFrom,
      validUntil: parsed.validUntil,
      invitedVia: "telegram",
      invitedBy: senderName,
      approvalTier: "invited",
      approvalStatus: "approved",
    });

    await sendMessage(
      msg.chat.id,
      [
        `✅ *Visitor Invited Successfully*`,
        `━━━━━━━━━━━━━━━━━━━━`,
        `👤 *${result.visitorName}*`,
        parsed.purpose ? `📋 Purpose: ${parsed.purpose}` : "",
        parsed.hostEmployeeName ? `🏢 Host: ${parsed.hostEmployeeName}` : "",
        parsed.visitorEmail ? `📧 Pass email: ${parsed.visitorEmail}` : "",
        `📅 Date: ${parsed.expectedDate ?? getCurrentISTDate()}`,
        parsed.validFrom ? `🟢 Start: ${formatShortDateTimeInIST(parsed.validFrom)}` : "",
        parsed.validUntil ? `🔴 End: ${formatShortDateTimeInIST(parsed.validUntil)}` : "",
        ``,
        `🔗 Invitation ID: \`${result.invitationId.slice(0, 8)}\``,
        `⏰ Expires: ${formatShortDateTimeInIST(result.expiresAt)}`,
        ``,
        `📱 Send this check-in link to the visitor:`,
        `${result.qrUrl}`,
      ].filter(Boolean).join("\n"),
      { parseMode: "Markdown" },
    );
  } catch (error) {
    await sendMessage(msg.chat.id, `❌ Failed to create invite: ${getErrorMessage(error)}`);
  }
}

// ─── Guard Command Handler ────────────────────────────────────

async function handleGuardCommand(msg: TelegramBot.Message, args: string[]): Promise<void> {
  const subCmd = args[0]?.toLowerCase() || "help";

  if (subCmd !== "add") {
    await sendMessage(
      msg.chat.id,
      `👮 *Guard Management*\n\nUsage: \`/guard add "Name" PIN [language]\`\n\nLanguage options: \`hindi\` (default) | \`english\`\n\nExample:\n\`/guard add "Suresh Kumar" 1234 hindi\``,
      { parseMode: "Markdown" },
    );
    return;
  }

  // /guard add "Name" PIN [lang]
  const restText = args.slice(1).join(" ");
  const quotedMatch = restText.match(/^"([^"]+)"\s+(\d{4,8})(\s+\w+)?$/);
  if (!quotedMatch) {
    await sendMessage(msg.chat.id, `⚠️ Usage: \`/guard add "Full Name" PIN [hindi|english]\``, { parseMode: "Markdown" });
    return;
  }

  const name = quotedMatch[1]!;
  const pin = quotedMatch[2]!;
  const language = (quotedMatch[3]?.trim() ?? "hindi") as "hindi" | "english";

  try {
    const { id } = await registerGuard({ name, pin, language });
    await sendMessage(
      msg.chat.id,
      `✅ *Guard registered*\n👮 ${name}\n🌐 Language: ${language}\n🆔 \`${id.slice(0, 8)}\`\n\nGuard can now login at \`/guard\` with their name and PIN.`,
      { parseMode: "Markdown" },
    );
  } catch (error) {
    await sendMessage(msg.chat.id, `❌ Failed to register guard: ${getErrorMessage(error)}`);
  }
}

// ─── Lockdown Command Handler ─────────────────────────────────

async function handleLockdownCommand(msg: TelegramBot.Message): Promise<void> {
  const triggeredBy = msg.from?.first_name ?? "Admin";
  await sendMessage(msg.chat.id, "🚨 Triggering emergency lockdown report...");

  try {
    const report = await triggerLockdown(triggeredBy);
    await sendMessage(
      msg.chat.id,
      `Report sent to all admin channels.\n📊 *${report.activeCount}* visitor(s) in premises.`,
      { parseMode: "Markdown" },
    );
  } catch (error) {
    await sendMessage(msg.chat.id, `❌ Lockdown failed: ${getErrorMessage(error)}`);
  }
}

// ─── Batch Invite Command Handler ───────────────────────────

async function handleBatchInviteCommand(msg: TelegramBot.Message, args: string[]): Promise<void> {
  const bot = getBot();
  const fileId = getMediaFileId(msg);

  if (!msg.document || !fileId) {
    await sendMessage(msg.chat.id, "⚠️ Usage: Attach an Excel file (`.xlsx` or `.csv`) and set the caption to `/batchinvite`.", { parseMode: "Markdown" });
    return;
  }

  const mimeType = msg.document.mime_type || "";
  const filename = msg.document.file_name || "";
  if (!filename.toLowerCase().endsWith(".xlsx") && !filename.toLowerCase().endsWith(".csv") && !mimeType.includes("spreadsheet")) {
    await sendMessage(msg.chat.id, "⚠️ Please attach a valid Excel (`.xlsx`) or CSV file.");
    return;
  }

  await bot.sendChatAction(msg.chat.id, "upload_document");
  await sendMessage(msg.chat.id, "📥 Downloading Excel file...");

  const media = await downloadTelegramMedia(fileId, "document");
  if (!media) {
    await sendMessage(msg.chat.id, "❌ Failed to download the file from Telegram.");
    return;
  }

  try {
    const buffer = readFileSync(media.localPath);

    await sendMessage(msg.chat.id, "⚙️ Processing bulk invites...");
    const senderName = getSenderName(msg);
    const result = await bulkInviteFromExcel(buffer, senderName, "telegram");

    const lines = [
      `✅ *Batch Invite Complete*`,
      `Total Rows: ${result.total}`,
      `Created: ${result.created}`,
      `Skipped/Errors: ${result.skipped}`
    ];

    if (result.errors.length > 0) {
      lines.push("", "*Errors:*");
      for (const err of result.errors.slice(0, 10)) {
        lines.push(`• ${err}`);
      }
      if (result.errors.length > 10) {
        lines.push(`... and ${result.errors.length - 10} more`);
      }
    }

    await sendMessage(msg.chat.id, lines.join("\n"), { parseMode: "Markdown" });

  } catch (err) {
    await sendMessage(msg.chat.id, `❌ Error processing Excel file: ${getErrorMessage(err)}`);
  }
}

