// ─── Scoped Reset Callbacks ──────────────────────────────────

type ResetScope = "inventory" | "visitor" | "all" | "wipeout";

const SCOPE_LABELS: Record<ResetScope, string> = {
  inventory: "Inventory",
  visitor:   "Visitor",
  all:       "All operational data",
  wipeout:   "EVERYTHING (including flows + users)",
};

async function handleScopedResetCancel(
  query: TelegramBot.CallbackQuery,
  data: string,
  ack: (text: string) => Promise<void>,
): Promise<void> {
  const bot = getBot();
  const parts = data.split(":");
  const scope = (parts[1] ?? "") as ResetScope;
  const requesterId = Number(parts[2]);

  if (!isAdmin(query.from.id)) {
    await ack("Unauthorized.");
    return;
  }
  if (Number.isFinite(requesterId) && requesterId !== query.from.id) {
    await ack("This prompt belongs to another admin.");
    return;
  }

  if (query.message) {
    await bot.editMessageText(`${SCOPE_LABELS[scope] ?? "Reset"} cancelled. No data was deleted.`, {
      chat_id: query.message.chat.id,
      message_id: query.message.message_id,
    });
  }
  await ack("Cancelled.");
}

async function handleScopedResetConfirm(
  query: TelegramBot.CallbackQuery,
  data: string,
  ack: (text: string) => Promise<void>,
): Promise<void> {
  const bot = getBot();
  const parts = data.split(":");
  const scope = (parts[1] ?? "") as ResetScope;
  const requesterId = Number(parts[2]);

  if (!isAdmin(query.from.id)) {
    await ack("Unauthorized.");
    return;
  }
  if (Number.isFinite(requesterId) && requesterId !== query.from.id) {
    await ack("This prompt belongs to another admin.");
    return;
  }

  await ack("Resetting…");

  if (query.message) {
    await bot
      .editMessageText(`⏳ ${SCOPE_LABELS[scope] ?? "Reset"} — wiping data…`, {
        chat_id: query.message.chat.id,
        message_id: query.message.message_id,
      })
      .catch(() => {});
  }

  const runners: Record<ResetScope, () => Promise<{ cleared: string[]; skipped: { table: string; error: string }[] }>> = {
    inventory: resetInventoryData,
    visitor:   resetVisitorData,
    all:       resetAllExceptFlowsAndAuth,
    wipeout:   wipeoutEverything,
  };

