// ─── Types ────────────────────────────────────────────────

interface MessageGroup {
  /** All raw message rows in this group */
  messages: RawMessageRow[];
  /** Unique sender+chat key */
  groupKey: string;
  /** Earliest timestamp in the group */
  earliestTimestamp: string;
}

// ─── State ────────────────────────────────────────────────

let batchTimer: ReturnType<typeof setInterval> | null = null;
let isProcessing = false;

// ─── Start / Stop ─────────────────────────────────────────

/**
 * Start the batch processor. Runs at the configured interval.
 * Safe to call multiple times — will clear any previous timer.
 */
export function startBatchProcessor(): void {
  if (batchTimer) {
    clearInterval(batchTimer);
  }

  const intervalMs = batchConfig.intervalMs();

  batchTimer = setInterval(() => {
    void processBatch();
  }, intervalMs);

  logInfo(
    `[BatchProcessor] Started — interval: ${intervalMs}ms, group window: ${batchConfig.groupWindowMs()}ms, context: ${Math.round(batchConfig.contextWindowMs() / 3600000)}h`,
    { scope: "batch-processor" },
  );
}

/**
 * Stop the batch processor.
 */
export function stopBatchProcessor(): void {
  if (batchTimer) {
    clearInterval(batchTimer);
    batchTimer = null;
    logInfo("[BatchProcessor] Stopped", { scope: "batch-processor" });
  }
}

