async function syncCatalogTabToSheet(siteId: string): Promise<void> {
  const [spreadsheetId, ownerEmail] = await Promise.all([
    getSetting(siteId, SHEET_ID_KEY),
    getSetting(siteId, SHEET_OWNER_KEY),
  ]);
  if (!spreadsheetId || !ownerEmail) return;
  const sheets = await getAdminSheetsClient(ownerEmail);
  if (!sheets) return;
  const rows = await listCatalogForSheet(siteId);
  const sheetRows = rows.map((r) => [
    r.canonical_name,
    r.category ?? "",
    r.unit,
    String(r.pack_size),
    r.last_price != null ? String(r.last_price) : "",
    r.barcodes ?? "",
    r.hsn_code ?? "",
  ]);
  await replaceSheetTab(
    sheets,
    spreadsheetId,
    "Catalog",
    INVENTORY_SHEET_HEADERS.Catalog,
    sheetRows,
  );
}

async function appendComplianceRow(siteId: string, receiptId: string): Promise<void> {
  const [spreadsheetId, ownerEmail] = await Promise.all([
    getSetting(siteId, SHEET_ID_KEY),
    getSetting(siteId, SHEET_OWNER_KEY),
  ]);
  if (!spreadsheetId || !ownerEmail) return; // no sheet attached
  const sheets = await getAdminSheetsClient(ownerEmail);
  if (!sheets) return; // owner's Google token missing — silently skip

