/**
 * Push the canonical catalog to the linked Google Sheet, NOW.
 * Most callers should use `syncCatalogTabToSheet` instead, which
 * debounces bursts of triggers (every bill validate, every product
 * create, every field registration) into a single push and so avoids
 * the Sheets `Read requests per minute per user` quota.
 */
async function syncCatalogTabToSheetNow(siteId: string): Promise<void> {
  const [spreadsheetId, ownerEmail] = await Promise.all([
    getSetting(siteId, SHEET_ID_KEY),
    getSetting(siteId, SHEET_OWNER_KEY),
  ]);
  if (!spreadsheetId || !ownerEmail) return;
  const sheets = await getAdminSheetsClient(ownerEmail);
  if (!sheets) return;
  const rows = await listCatalogForSheet(siteId);
  const sheetRows = rows.map((r) => [
    r.canonical_name,
    r.category ?? "",
    r.unit,
    String(r.pack_size),
    r.last_price != null ? String(r.last_price) : "",
    r.barcodes ?? "",
    r.hsn_code ?? "",
  ]);
  await replaceSheetTab(
    sheets,
    spreadsheetId,
    "Catalog",
    INVENTORY_SHEET_HEADERS.Catalog,
    sheetRows,
  );
}

// Debounce per site: every write path calls syncCatalogTabToSheet, but
// we only actually push to Sheets DEBOUNCE_MS after the last call. Burst
// of 30 validations → one Sheets write, not thirty. Critical to staying
// under Sheets' 60 reads/min/user quota.
const CATALOG_SYNC_DEBOUNCE_MS = 15_000;
const pendingCatalogSync = new Map<string, ReturnType<typeof setTimeout>>();

function syncCatalogTabToSheet(siteId: string): Promise<void> {
  const existing = pendingCatalogSync.get(siteId);
  if (existing) clearTimeout(existing);
  const handle = setTimeout(() => {
    pendingCatalogSync.delete(siteId);
    void syncCatalogTabToSheetNow(siteId).catch((err) => {
      logError("[Inventory] debounced catalog sync failed", err, {
        scope: "inventory.sheets",
      });
    });
  }, CATALOG_SYNC_DEBOUNCE_MS);
  pendingCatalogSync.set(siteId, handle);
  return Promise.resolve();
}

