export type BillLineItem = {
  sr_no: number;
  /** Exact text from the bill (vendor's spelling). The catalog matcher
   *  uses this to learn aliases. */
  item_purchased: string;
  /** How many packs/units of the item arrived. */
  qty: number;
  /** Unit of the pack (kg/g/l/ml/pcs/pack/box). Inferred from the
   *  item name when not a separate column. */
  unit_type: string | null;
  /** Numeric value of one pack ("750" for "750G", "1" for "1L").
   *  Null when we can't tell. */
  unit_value: number | null;
  /** High-level category — Grocery / Cleaning / Snacks / Beverages /
   *  Dairy / Office / etc. Inferred from the item name. */
  category: string | null;
  /** Per-unit rate from the bill ("RATE"). */
  rate: number | null;
  /** Line total ("VALUE"). */
  value: number | null;
  /** HSN if present on the bill; nice-to-have, never required. */
  hsn_code: string | null;
};

export type ExtractedBill = {
  vendor_name: string | null;
  bill_number: string | null;
  bill_date: string | null;
  line_items: BillLineItem[];
  grand_total: number | null;
};

const EXTRACTION_PROMPT = `You are a bill/receipt data extractor for an Indian office operations system.

Vendor bill layouts vary widely. Different vendors put the columns in different
orders, and some omit columns entirely (HSN, tax category, etc. may be missing).
Your job is to extract the USEFUL fields for each line item — not just transcribe
the columns you see. Pull values from anywhere on the line (column, item-name
suffix like "750G", row totals, etc.).

For each line item, return these fields (some inferred from the item name when
not a separate column):

  - item_purchased  — exact item text as written on the bill
  - qty             — how many packs/units arrived (number)
  - unit_type       — "kg" | "g" | "l" | "ml" | "pcs" | "pack" | "box"
                      (lowercase; pick the best fit; null only if you really
                      cannot tell)
  - unit_value      — numeric size of one pack: 750 for "750G", 1 for "1L",
                      1 for an unspecified piece; null if uncertain
  - category        — a short high-level grocery category like
                      "Grocery" | "Snacks" | "Beverages" | "Dairy" |
                      "Cleaning" | "Bakery" | "Personal Care" | "Office" |
                      "Stationery". Infer from item name. Null only if you
                      truly cannot guess.
  - rate            — per-unit price from the bill (number, no currency)
  - value           — line total (number, no currency)
  - hsn_code        — only if the bill has an HSN column; null otherwise

Examples (different vendor layouts):

  Dmart row:  "1. 19041090  2  KELLOGS MUESLI FRUIT N NUT 750G  3.0  349.0  1047.0"
  →
    { item_purchased: "KELLOGS MUESLI FRUIT N NUT 750G",
      qty: 3, unit_type: "g", unit_value: 750, category: "Breakfast",
      rate: 349, value: 1047, hsn_code: "19041090" }

  Kirana row: "Wagh Bakri 1kg bks1   5   340.00   1700.00"
  →
    { item_purchased: "Wagh Bakri 1kg bks1",
      qty: 5, unit_type: "kg", unit_value: 1, category: "Beverages",
      rate: 340, value: 1700, hsn_code: null }

  Cleaning shop row: "Vim dishwash 500ml   12   45   540"
  →
    { item_purchased: "Vim dishwash 500ml",
      qty: 12, unit_type: "ml", unit_value: 500, category: "Cleaning",
      rate: 45, value: 540, hsn_code: null }

Also return bill metadata, but DO NOT invent values when they're missing.
If the bill has no vendor name / bill number / date visible, return null —
the admin will fill them in:

  - vendor_name
  - bill_number
  - bill_date         (YYYY-MM-DD if you can convert; null otherwise)
  - grand_total       (number, no currency)

Output strict JSON in this exact shape — no markdown fences, no commentary:

{
  "vendor_name": "string or null",
  "bill_number": "string or null",
  "bill_date":   "YYYY-MM-DD or null",
  "grand_total": 3840.0,
  "line_items": [
    { "sr_no": 1, "item_purchased": "…", "qty": 3,
      "unit_type": "g", "unit_value": 750, "category": "Breakfast",
      "rate": 349.0, "value": 1047.0, "hsn_code": "19041090" }
  ]
}

Rules:
  - Extract EVERY line item, even if partially legible.
  - Preserve the EXACT item name as written (do not correct spelling).
  - qty / rate / value / unit_value must be numbers, not strings.
  - For categories you're not 100% sure about, pick the closest sensible
    bucket — don't return null just because the bill doesn't say so.
  - If the bill is in Hindi or another script, keep item names in that script.`;

