/**
 * Bill Extractor — OCR + LLM bill photo → structured line items.
 *
 * Takes a bill photo (base64 or URL) and extracts structured data:
 * vendor name, bill number, bill date, line items with HSN/qty/rate,
 * and totals. Uses the same LLM pipeline as the domain classifier.
 *
 * Output feeds into the bill-matcher for canonical product resolution.
 */

import { mastra } from "../../index";

export type BillLineItem = {
  sr_no: number;
  hsn_code: string | null;
  tax_category: string | null;
  item_purchased: string;
  qty: number;
  rate: number | null;
  value: number | null;
  unit: string | null;
};

export type ExtractedBill = {
  vendor_name: string | null;
  bill_number: string | null;
  bill_date: string | null;
  line_items: BillLineItem[];
  grand_total: number | null;
  tax_total: number | null;
};

const EXTRACTION_PROMPT = `You are a bill/receipt data extractor for an Indian office operations system.

Given an image of a vendor bill or receipt, extract ALL line items and metadata into structured JSON.

Bill columns typically include: SR NO., HSN, TAX CATEGORY, ITEM(S) PURCHASED, QTY, RATE (Rs.), VALUE (Rs.)

Return ONLY valid JSON in this exact format (no markdown fences, no explanation):
{
  "vendor_name": "string or null",
  "bill_number": "string or null",
  "bill_date": "YYYY-MM-DD or null",
  "line_items": [
    {
      "sr_no": 1,
      "hsn_code": "1905 or null",
      "tax_category": "GST 18% or null",
      "item_purchased": "exact text from bill",
      "qty": 3,
      "rate": 10.00,
      "value": 30.00,
      "unit": "pcs or kg or ml or null (infer from item name if possible)"
    }
  ],
  "grand_total": 800.00,
  "tax_total": 50.00
}

Rules:
- Extract EVERY line item, even if partially legible
- Preserve the EXACT item name as written on the bill (do not correct spelling)
- HSN codes are typically 4-8 digit numbers
- If a field is not visible or not present, use null
- qty and rate must be numbers, not strings
- If the bill is in Hindi, still extract item names in the original script
- bill_date should be converted to YYYY-MM-DD format if possible`;

function parseExtractedBill(text: string): ExtractedBill | null {
  // Strip markdown code fences if present
  const cleaned = text
    .trim()
    .replace(/^```(?:json)?/i, "")
    .replace(/```$/, "")
    .trim();

  // Find the outermost JSON object
  const start = cleaned.indexOf("{");
  const end = cleaned.lastIndexOf("}");
  if (start === -1 || end === -1) return null;

  try {
    const parsed = JSON.parse(cleaned.slice(start, end + 1));

    if (!Array.isArray(parsed.line_items)) return null;

    return {
      vendor_name: parsed.vendor_name ?? null,
      bill_number: parsed.bill_number ?? null,
      bill_date: parsed.bill_date ?? null,
      line_items: parsed.line_items.map(
        (item: Record<string, unknown>, idx: number) => ({
          sr_no: Number(item.sr_no ?? idx + 1),
          hsn_code: item.hsn_code ? String(item.hsn_code) : null,
          tax_category: item.tax_category
            ? String(item.tax_category)
            : null,
          item_purchased: String(item.item_purchased ?? "Unknown"),
          qty: Number(item.qty ?? 1),
          rate: item.rate != null ? Number(item.rate) : null,
          value: item.value != null ? Number(item.value) : null,
          unit: item.unit ? String(item.unit) : null,
        }),
      ),
      grand_total:
        parsed.grand_total != null ? Number(parsed.grand_total) : null,
      tax_total:
        parsed.tax_total != null ? Number(parsed.tax_total) : null,
    };
  } catch {
    return null;
  }
}

/**
 * Extract structured bill data from a photo.
 *
 * @param imageSource - Either a base64-encoded image string or a URL
 * @param mimeType - MIME type of the image (default: image/jpeg)
 */
export async function extractBillFromImage(
  imageSource: string,
  mimeType: string = "image/jpeg",
): Promise<{
  success: boolean;
  bill: ExtractedBill | null;
  error?: string;
}> {
  const agent = mastra.getAgent("inventoryAgent");
  if (!agent) {
    return {
      success: false,
      bill: null,
      error: "inventoryAgent not available",
    };
  }

  const isUrl =
    imageSource.startsWith("http://") || imageSource.startsWith("https://");
  const isPdf = mimeType.toLowerCase() === "application/pdf";

  // PDFs go in as `file` parts (Vercel AI SDK); images use `image` parts.
  const imageContent = isPdf
    ? isUrl
      ? { type: "file" as const, data: new URL(imageSource), mimeType }
      : { type: "file" as const, data: imageSource, mimeType }
    : isUrl
      ? { type: "image" as const, image: new URL(imageSource) }
      : { type: "image" as const, image: imageSource, mimeType };

  try {
    const result = (await agent.generate([
      { role: "system", content: EXTRACTION_PROMPT },
      {
        role: "user",
        content: [
          imageContent,
          {
            type: "text" as const,
            text: "Extract all line items from this bill/receipt image.",
          },
        ],
      },
    ])) as { text?: string };

    const text = result.text ?? "";
    const bill = parseExtractedBill(text);

    if (!bill) {
      return {
        success: false,
        bill: null,
        error: `Failed to parse LLM response: ${text.slice(0, 200)}`,
      };
    }

    // Basic validation
    if (bill.line_items.length === 0) {
      return {
        success: false,
        bill,
        error: "No line items extracted from bill",
      };
    }

    return { success: true, bill };
  } catch (error) {
    return {
      success: false,
      bill: null,
      error: `LLM extraction failed: ${error instanceof Error ? error.message : String(error)}`,
    };
  }
}

