import { apiRequest } from "./client";

// Must match the field-app's `config.siteId` (see field-app/src/config.ts).
// If you change one, change the other — otherwise dashboard writes and
// field-app reads land in different sites and never see each other.
const SITE_ID = (import.meta.env.VITE_OPS_SITE_ID as string | undefined) ?? "site-dev";

const SITE_HEADERS = { "X-Site-Id": SITE_ID };

export interface CanonicalProduct {
  product_id: string;
  site_id: string;
  canonical_name: string;
  category: string | null;
  hsn_code: string | null;
  unit: string;
  pack_size: number;
  created_at: string;
  updated_at: string;
}

export interface UnresolvedBillItem {
  id: string;
  site_id: string;
  order_id: string | null;
  bill_item_name: string;
  hsn_code: string | null;
  qty: number;
  unit_rate: number | null;
  line_value: number | null;
  status: string;
  created_at: string;
}

export interface BillSuggestion {
  productId: string;
  canonicalName: string;
  unit: string;
  packSize: number;
  hsnCode: string | null;
  category: string | null;
  score: number;
  method: string;
}

export interface BillExtractItem {
  tempId: string;
  bill_item_name: string;
  hsn_code: string | null;
  qty: number;
  rate: number | null;
  value: number | null;
  unit_hint: string | null;
  suggestions: BillSuggestion[];
}

export interface BillExtractResult {
  bill: {
    vendor_name: string | null;
    bill_number: string | null;
    bill_date: string | null;
    grand_total: number | null;
    tax_total: number | null;
  };
  items: BillExtractItem[];
}

export interface ValidatedBillItem {
  action: "use_existing" | "create_new";
  product_id?: string | null;
  canonical_name: string;
  category?: string | null;
  hsn_code?: string | null;
  unit: string;
  pack_size: number;
  qty: number;
  rate?: number | null;
  value?: number | null;
  bill_item_name: string;
}

export interface ValidateBillPayload {
  vendor_name?: string | null;
  bill_number?: string | null;
  bill_date?: string | null;
  grand_total?: number | null;
  items: ValidatedBillItem[];
}

export interface ComplianceLogRow {
  scanned_at: string;
  date: string;
  vendor: string | null;
  bill_number: string | null;
  product_id: string | null;
  product_name: string;
  bill_item_name: string | null;
  category: string | null;
  hsn_code: string | null;
  unit: string | null;
  pack_size: number | null;
  qty_received: number;
  expected_qty: number | null;
  unit_rate: number | null;
  line_value: number | null;
  expiry_date: string | null;
  received_by: string | null;
  status: "OK" | "MISMATCH";
}

export function listCanonicalProducts() {
  return apiRequest<{ products: CanonicalProduct[] }>(
    "GET", "/api/inventory/canonical-products", undefined, SITE_HEADERS,
  );
}

export function patchCanonicalProduct(productId: string, patch: {
  canonical_name?: string;
  category?: string | null;
  hsn_code?: string | null;
  unit?: string;
  pack_size?: number;
}) {
  return apiRequest<{ updated: boolean }>(
    "PATCH",
    `/api/inventory/canonical-products/${encodeURIComponent(productId)}`,
    patch,
    SITE_HEADERS,
  );
}

export function createCanonicalProduct(input: {
  canonical_name: string;
  category?: string;
  hsn_code?: string;
  unit?: string;
  pack_size?: number;
}) {
  return apiRequest<{ product_id: string }>(
    "POST", "/api/inventory/canonical-products", input, SITE_HEADERS,
  );
}

export function listUnresolvedBillItems() {
  return apiRequest<{ items: UnresolvedBillItem[] }>(
    "GET", "/api/inventory/bills/unresolved", undefined, SITE_HEADERS,
  );
}

export function resolveBillItem(input: {
  unresolved_id: string;
  product_id: string;
