function OrdersTab() {
  const queryClient = useQueryClient();
  const ordersQuery = useQuery({ queryKey: ["inv-orders"], queryFn: listOrders });
  const orders = ordersQuery.data?.data?.orders ?? [];

  const invalidate = () => {
    void queryClient.invalidateQueries({ queryKey: ["inv-orders"] });
  };

  const [showNew, setShowNew] = useState(false);
  const [newVendor, setNewVendor] = useState("");
  const [newBillNumber, setNewBillNumber] = useState("");
  const [newBillDate, setNewBillDate] = useState("");

  const deleteOrderMutation = useMutation({
    mutationFn: deleteOrder,
    onSuccess: (res) => {
      if (!res.ok) { toastError(errorMessage((res.data as { error?: string }).error, "Delete failed")); return; }
      toastSuccess("Order deleted");
      invalidate();
    },
    onError: (err) => toastError(err, "Delete failed"),
  });

  const createOrderMutation = useMutation({
    mutationFn: () => createOrder({
      vendor: newVendor.trim() || null,
      bill_number: newBillNumber.trim() || null,
      bill_date: newBillDate || null,
    }),
    onSuccess: (res) => {
      if (!res.ok) { toastError(errorMessage((res.data as { error?: string }).error, "Create failed")); return; }
      toastSuccess("Order created — expand to add items");
      setShowNew(false);
      setNewVendor(""); setNewBillNumber(""); setNewBillDate("");
      invalidate();
    },
    onError: (err) => toastError(err, "Create failed"),
  });

  return (
    <div>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 10 }}>
        <div style={{ fontWeight: 600 }}>
          {orders.length} order{orders.length === 1 ? "" : "s"}
        </div>
        <div style={{ display: "flex", gap: 8 }}>
          <button type="button" onClick={() => void ordersQuery.refetch()} style={ghostBtn}>
            <RefreshCw size={14} /> Refresh
          </button>
          <button type="button" className="primary-button" onClick={() => setShowNew(true)}>
            <Plus size={14} /> New order
          </button>
        </div>
      </div>

      {showNew && (
