const SEARCH_PATH_SQL = `SET search_path TO ${officeOpsSchemaName()},public`;
class SchemaAwareClient extends PgClient {
  override connect(callback?: any): any {
    if (typeof callback === "function") {
      return super.connect((err: Error | null) => {
        if (err) return callback(err);
        super.query(SEARCH_PATH_SQL, (setErr: Error | null) => {
          callback(setErr);
        });
      });
    }
    return (super.connect() as unknown as Promise<unknown>)
      .then(() => super.query(SEARCH_PATH_SQL))
      .then(() => undefined);
  }
}

