// Per-line suggestions — no writes. Wrap each suggester call so a
// catalog lookup failure (transient DB error, schema-path drift on
// a freshly-issued pool connection after the long OCR wait, etc.)
// doesn't 500 the whole extraction. The admin still gets the OCR
// items and can map them manually if suggestions are empty.
const items = await Promise.all(
  extraction.bill.line_items.map(async (line, idx) => {
    let suggestions: Awaited<ReturnType<typeof suggestForBillLine>> = [];
    try {
      suggestions = await suggestForBillLine(auth.siteId, line, 3);
    } catch (err) {
      logError("[Inventory] suggestForBillLine failed (continuing)", err, {
        scope: "inventory.extract",
        action: line.item_purchased,
      });
    }
    return {
      tempId: `t_${idx}`,
      bill_item_name: line.item_purchased,
      hsn_code: line.hsn_code,
      qty: line.qty,
      rate: line.rate,
      value: line.value,
      unit_type: line.unit_type,
      unit_value: line.unit_value,
      category: line.category,
      suggestions,
    };
  }),
);

