function normalizePostgresStatement(statement: SqlStatement): { sql: string; args: SqlArgs } {
  const rawSql = typeof statement === "string" ? statement : statement.sql;
  const args = typeof statement === "string" ? [] : statement.args ?? [];
  let sql = rawSql.trim();

  if (!sql) {
    return { sql: "", args };
  }

  sql = sql
    .replace(/INSERT\s+OR\s+REPLACE\s+INTO\s+staff_channels\s*\(([^)]+)\)\s*VALUES\s*\(([^)]+)\)/i,
      "INSERT INTO staff_channels ($1) VALUES ($2) ON CONFLICT (channel, channel_uid) DO UPDATE SET staff_id = EXCLUDED.staff_id, channel_uname = EXCLUDED.channel_uname, created_at = EXCLUDED.created_at")
    .replace(/datetime\(vs\.checkin_time,\s*'\+'\s*\|\|\s*\?\s*\|\|\s*'\s*minutes'\)\s*<\s*\?/gi,
      "(vs.checkin_time::timestamptz + (?::int * interval '1 minute')) < ?::timestamptz")
    .replace(/datetime\(created_at,\s*'\+'\s*\|\|\s*\?\s*\|\|\s*'\s*hours'\)\s*<\s*datetime\(\?\)/gi,
      "(created_at::timestamptz + (?::int * interval '1 hour')) < ?::timestamptz")
    .replace(/datetime\(created_at,\s*'\+24 hours'\)\s*<\s*datetime\(\?\)/gi,
      "(created_at::timestamptz + interval '24 hours') < ?::timestamptz");

  return {
    sql: replaceQuestionPlaceholders(sql),
    args,
  };
}

function replaceQuestionPlaceholders(sql: string): string {
  let index = 0;
  let output = "";
  let inSingleQuote = false;
  for (let i = 0; i < sql.length; i++) {
    const char = sql[i];
    const next = sql[i + 1];
    if (char === "'" && next === "'") {
      output += char + next;
      i++;
      continue;
    }
    if (char === "'") {
      inSingleQuote = !inSingleQuote;
      output += char;
      continue;
    }
    if (char === "?" && !inSingleQuote) {
      index++;
      output += `$${index}`;
      continue;
    }
    output += char;
  }
  return output;
}

function splitSqlStatements(sql: string): string[] {
  return sql
    .split(";")
    .map((statement) => statement.trim())
    .filter(Boolean);
}

