export async function getSetting(siteId: string, key: string): Promise<string | null> {
  const db = await getDb();
  const result = await db.execute({
    sql: `SELECT value FROM inventory_settings WHERE site_id = ? AND key = ?`,
    args: [siteId, key],
  });
  const row = result.rows[0] as { value: string | null } | undefined;
  return row?.value ?? null;
}

export async function setSetting(siteId: string, key: string, value: string): Promise<void> {
