export async function adjustOnHand(input: {
  siteId: string;
  barcode: string;
  delta: number;
  fallbackName?: string;
  fallbackCategory?: string | null;
  fallbackUnit?: string | null;
}): Promise<void> {
  const db = await getDb();
  // The delta is passed twice: once clamped for the INSERT path (a brand
  // new row created by a negative-delta issue starts at 0, never below)
  // and once raw for the UPDATE path (`EXCLUDED.on_hand` would be the
  // clamped value, which would silently swallow negative deltas).
  await db.execute({
    sql: `
      INSERT INTO inventory_stock (barcode, site_id, name, category, unit, on_hand, threshold)
      VALUES (?, ?, ?, ?, ?, GREATEST(?, 0), 0)
      ON CONFLICT (site_id, barcode) DO UPDATE SET
        on_hand = GREATEST(inventory_stock.on_hand + ?, 0),
        updated_at = now()
    `,
    args: [
      input.barcode,
      input.siteId,
      input.fallbackName ?? "Unknown",
      input.fallbackCategory ?? null,
      input.fallbackUnit ?? null,
      input.delta,
      input.delta,
    ],
  });
}

