async function appendComplianceRow(siteId: string, receiptId: string): Promise<void> {
  // Granular step-by-step logging to pinpoint which call throws. The
  // outer try/catch in the receipts route only logs "Sheet append
  // failed" — it can't tell us whether it was getSetting, the SELECT,
  // drizzle, or the actual Sheets API.
  /* eslint-disable no-console */
  let step: string = "init";
  try {
    step = "getSetting(SHEET_ID_KEY)";
    const spreadsheetId = await getSetting(siteId, SHEET_ID_KEY);
    step = "getSetting(SHEET_OWNER_KEY)";
    const ownerEmail = await getSetting(siteId, SHEET_OWNER_KEY);
    if (!spreadsheetId || !ownerEmail) {
      console.warn(`[Inventory] Received append skipped (no sheet attached): site=${siteId}, receipt=${receiptId}`);
      return;
    }

    step = "getAdminSheetsClient";
    const sheets = await getAdminSheetsClient(ownerEmail);
    if (!sheets) {
      console.warn(`[Inventory] Received append skipped (owner Google token missing): owner=${ownerEmail}, receipt=${receiptId}`);
      return;
    }

    step = "getComplianceLogForReceipt";
    const row = await getComplianceLogForReceipt(siteId, receiptId);
    if (!row) {
      console.warn(`[Inventory] Received append skipped (compliance row not found): site=${siteId}, receipt=${receiptId}`);
      return;
    }

    step = "appendInventoryRow(Received)";
    console.log(`[Inventory] Received append → "${row.product_name}" qty=${row.qty_received} (receipt=${receiptId})`);
    await appendInventoryRow(
      sheets,
      spreadsheetId,
      "Received",
      INVENTORY_SHEET_HEADERS.Received,
      complianceRowToSheetValues(row),
    );
  } catch (err) {
    // Re-throw so the outer catch still logs through logError(); but
    // first emit a step label so we see WHICH call blew up.
    console.error(`[Inventory] Received append failed at step "${step}":`, err instanceof Error ? err.message : String(err));
    throw err;
  }
  /* eslint-enable no-console */
}

