function replaceQuestionPlaceholders(sql: string): string {
  let index = 0;
  let output = "";
  let inSingleQuote = false;
  let inDoubleQuote = false;
  let inLineComment = false;
  let inBlockComment = false;
  for (let i = 0; i < sql.length; i++) {
    const char = sql[i];
    const next = sql[i + 1];

    // End of a -- line comment is the next newline; nothing else
    // toggles state inside the comment.
    if (inLineComment) {
      output += char;
      if (char === "\n") inLineComment = false;
      continue;
    }
    // End of /* … */ block comment.
    if (inBlockComment) {
      output += char;
      if (char === "*" && next === "/") {
        output += next;
        i++;
        inBlockComment = false;
      }
      continue;
    }
    // Doubled-quote escape inside a single-quoted string ('' = literal ').
    if (inSingleQuote && char === "'" && next === "'") {
      output += char + next;
      i++;
      continue;
    }
    if (char === "'" && !inDoubleQuote) {
      inSingleQuote = !inSingleQuote;
      output += char;
      continue;
    }
    // Double-quoted identifiers ("col name") — we don't replace ? inside
    // those either. Apostrophes inside don't toggle string state.
    if (char === '"' && !inSingleQuote) {
      inDoubleQuote = !inDoubleQuote;
      output += char;
      continue;
    }
    // Start of a -- line comment.
    if (!inSingleQuote && !inDoubleQuote && char === "-" && next === "-") {
      inLineComment = true;
      output += char;
      continue;
    }
    // Start of a /* … */ block comment.
    if (!inSingleQuote && !inDoubleQuote && char === "/" && next === "*") {
      inBlockComment = true;
      output += char;
      continue;
    }
    if (char === "?" && !inSingleQuote && !inDoubleQuote) {
      index++;
      output += `$${index}`;
      continue;
    }
    output += char;
  }
  return output;
}

