24	  return () => listeners.delete(l);
25	}
26	
27	async function notify() {
28	  const c = await pendingCount().catch(() => 0);
29	  listeners.forEach((l) => l(c, _lastSyncAt));
30	}
31	
32	// Dispatch table for outbox kinds. Adding a new kind = one line here
33	// + a handler in api.send.*.
34	const DISPATCH: Record<OutboxKind, (payload: object) => Promise<unknown>> = {
35	  receipt: api.send.receipt,
36	  product_registration: api.send.product,
37	  issue: api.send.issue,
38	  dispense: api.send.issue, // same endpoint, renamed in-app
39	  reorder_request: api.send.reorderRequest,
40	  mismatch_flag: api.send.mismatchFlag,
41	  learn_barcode: api.send.learnBarcode,
42	};
43	
44	export async function flushOnce(): Promise<{ sent: number; failed: number }> {
45	  if (running) {
46	    // Queue a retry so manual "Sync Now" taps aren't silently dropped.
47	    retryQueued = true;
48	    return { sent: 0, failed: 0 };
49	  }
50	  running = true;
51	  let sent = 0;
52	  let failed = 0;
53	  try {
54	    const net = await Network.getNetworkStateAsync().catch(() => ({ isConnected: false }));
55	    if (!net.isConnected) return { sent, failed };
56	
57	    // Recover anything orphaned by a prior crash/kill before picking
58	    // the batch — otherwise the stuck row will be skipped again.
59	    await recoverOrphanedSending().catch(() => 0);
60	
61	    const batch = await nextBatch(config.outboxBatchSize);
62	    for (const row of batch) {
63	      const dispatch = DISPATCH[row.kind];
64	      if (!dispatch) {
65	        await markFailed(row.id, `Unknown kind: ${row.kind}`);
66	        failed++;
67	        continue;
68	      }
69	      try {
70	        await markSending(row.id);
71	        await dispatch(JSON.parse(row.payload));
72	        await markSent(row.id);
73	        sent++;
74	      } catch (err) {
75	        await markFailed(row.id, err instanceof Error ? err.message : String(err));
76	        failed++;
77	      }
78	    }
79	    if (sent > 0 || failed > 0) {
80	      _lastSyncAt = Date.now();
81	    }
82	
83	    // Pull latest canonical products catalog on each sync cycle.
84	    // This is lightweight (just a GET) and ensures guards always
85	    // have the latest admin-curated product names.
86	    await syncCanonicalProducts().catch(() => {});
87	    // Also mirror the open-orders list so ReceivingScreen can resolve
88	    // catalog picks to the right order item without a round-trip.
89	    await syncOrders().catch(() => {});
90	  } finally {
91	    running = false;
92	    await notify();
93	  }
94	
95	  // If someone tapped "Sync Now" while we were busy, run again.
96	  if (retryQueued) {
97	    retryQueued = false;
98	    return flushOnce();
99	  }
100	
101	  return { sent, failed };
102	}
103	
104	/**
105	 * Pull the canonical product catalog from the backend and replace
106	 * the local SQLite cache. Guards pick from this list — keeping it
107	 * fresh is essential for the catalog-only gate flow.
108	 *
109	 * Returns the counts so the picker UI can surface "X of Y synced" and
110	 * the user can detect cache mismatches without having to dig into logs.
111	 */
112	let _lastCatalogSync: { remote: number; written: number; failed: number; error: string | null } = {
113	  remote: 0, written: 0, failed: 0, error: null,
114	};
115	export function getLastCatalogSync() { return _lastCatalogSync; }
116	
117	export async function syncCanonicalProducts(): Promise<{ remote: number; written: number; failed: number }> {
118	  try {
119	    const remote = await api.fetch.canonicalProducts();
120	    const local: CanonicalProduct[] = remote.map((r) => ({
121	      product_id: r.product_id,
122	      canonical_name: r.canonical_name,
123	      category: r.category,
124	      hsn_code: r.hsn_code,
125	      unit: r.unit,
126	      pack_size: r.pack_size,
127	      updated_at: Date.now(),
128	    }));
129	    const result = await replaceCanonicalProducts(local);
130	    _lastCatalogSync = {
131	      remote: remote.length,
132	      written: result.ok,
133	      failed: result.failed,
134	      error: result.firstError ?? null,
135	    };
136	    if (result.failed > 0) {
137	      // eslint-disable-next-line no-console
138	      console.warn(`[catalog] sync wrote ${result.ok}/${remote.length}; ${result.failed} failed. First error: ${result.firstError}`);
139	    }
140	    return { remote: remote.length, written: result.ok, failed: result.failed };
141	  } catch (err) {
142	    _lastCatalogSync = {
143	      ..._lastCatalogSync,
144	      error: err instanceof Error ? err.message : String(err),
145	    };
146	    // eslint-disable-next-line no-console
147	    console.warn('[catalog] sync failed:', err);
148	    return { remote: 0, written: 0, failed: 0 };
149	  }
150	}
151	
152	/**
153	 * Pull the current open-orders list from the backend and mirror it into
154	 * the local orders/order_items tables. Lets ReceivingScreen resolve a
155	 * catalog pick to the right order item locally.
156	 */
157	export async function syncOrders(): Promise<void> {
158	  try {
159	    const remote = await api.fetch.orders();
160	    await upsertOrdersFromRemote(remote);
161	  } catch {
162	    // Non-fatal: ReceivingScreen falls back to "no matching order".
163	  }
164	}
165	
166	export function startSync(): void {
167	  if (timer) return;
168	  // Recover anything left mid-flight by a previous process before the
169	  // first flush, otherwise nextBatch skips them and they stay stuck on
170	  // "Sending…" forever.
171	  recoverOrphanedSending()
172	    .then((n) => {
173	      if (n > 0) {
174	        // eslint-disable-next-line no-console
175	        console.log(`[sync] recovered ${n} orphaned 'sending' row${n === 1 ? '' : 's'}`);
176	      }
177	    })
178	    .catch(() => {})
179	    .finally(() => {
180	      flushOnce().catch(() => {});
181	    });
182	  timer = setInterval(() => {
183	    flushOnce().catch(() => {});
184	  }, config.syncIntervalMs);
185	}
186	
187	export function stopSync(): void {
188	  if (timer) clearInterval(timer);
189	  timer = null;
190	}

