26	export function AlertsScreen({ navigation }: Props) {
27	  const t = useT();
28	  const { palette } = useTheme();
29	  const [rows, setRows] = useState<StockRow[]>([]);
30	  const [requested, setRequested] = useState<Set<string>>(new Set());
31	  const [initialLoading, setInitialLoading] = useState(true);
32	  const [refreshing, setRefreshing] = useState(false);
33	
34	  const load = useCallback(async () => {
35	    // Flush pending writes first so the remote reflects the latest state.
36	    await flushOnce().catch(() => {});
37	    try {
38	      // Pull the full stock snapshot (not just the alerts subset) so we
39	      // can replace authoritatively — wiped items disappear instead of
40	      // lingering. We compute alerts locally via listLowOrOut.
41	      const remote = await api.fetch.stock();
42	      await replaceStockFromRemote(
43	        remote.map((r) => ({
44	          barcode: r.barcode,
45	          name: r.name,
46	          category: r.category,
47	          unit: r.unit,
48	          on_hand: Number(r.on_hand),
49	          threshold: Number(r.threshold),
50	        })),
51	      );
52	    } catch {
53	      // Fall back to local SQLite cache.
54	    }
55	    setRows(await listLowOrOut());
56	    setInitialLoading(false);
57	  }, []);
58	
59	  useEffect(() => {
60	    load();
61	    const unsub = navigation.addListener('focus', load);
62	    return unsub;
63	  }, [navigation, load]);
64	
65	  const onRefresh = useCallback(async () => {
66	    setRefreshing(true);
67	    try {
68	      await load();
69	    } finally {
70	      setRefreshing(false);
71	    }
72	  }, [load]);
73	
74	  const reorder = async (row: StockRow) => {
75	    haptic.tap();
76	    await enqueue('reorder_request', {
77	      id: `ror_${nanoid(12)}`,
78	      barcode: row.barcode,
79	      product_name: row.name,
80	      on_hand: row.on_hand,
81	      threshold: row.threshold,
82	      requested_at: Date.now(),
83	    });
84	    setRequested((prev) => new Set(prev).add(row.barcode));
85	    flushOnce().catch(() => {});
86	    haptic.success();
87	  };
88	
89	  return (
90	    <View style={[styles.safe, { backgroundColor: palette.background }]}>
91	      <AppBar title={t('alerts')} subtitle={t('alertsSub')} onBack={() => navigation.goBack()} />
92	      {initialLoading && rows.length === 0 ? (
93	        <View style={styles.list}>
94	          {[0, 1, 2].map((i) => (
95	            <View key={i} style={{ marginBottom: spacing.md }}>
96	              <Card tone="filled" padding="lg">
97	                <View style={styles.head}>
98	                  <View style={{ flex: 1, gap: 6 }}>
99	                    <Skeleton width="55%" height={18} />
100	                    <Skeleton width="75%" height={14} />
101	                  </View>
102	                  <Skeleton width={56} height={24} rounded="pill" />
103	                </View>
104	                <View style={{ height: spacing.md }} />
105	                <Skeleton width="40%" height={36} rounded="pill" />
106	              </Card>
107	            </View>
108	          ))}
109	        </View>
110	      ) : (
111	      <FlatList
112	        data={rows}
113	        keyExtractor={(r) => r.barcode}
114	        contentContainerStyle={styles.list}
115	        refreshControl={
116	          <RefreshControl refreshing={refreshing} onRefresh={onRefresh} tintColor={palette.primary} />
117	        }
118	        ItemSeparatorComponent={() => <View style={{ height: spacing.md }} />}
119	        renderItem={({ item }) => {
120	          const status = statusFor(item);
121	          const tone = status === 'out' ? 'danger' : 'warn';
122	          const label = status === 'out' ? t('outStock') : t('lowStock');
123	          const done = requested.has(item.barcode);
124	          return (
125	            <Card tone="filled" padding="lg">
126	              <View style={styles.head}>
127	                <View style={{ flex: 1 }}>
128	                  <Text variant="titleMedium">{item.name}</Text>
129	                  <Text
130	                    variant="bodyMedium"
131	                    color={palette.onSurfaceVariant}
132	                    style={{ marginTop: 2 }}
133	                  >
134	                    {item.on_hand} {item.unit ?? ''} {t('onHand')} · threshold {item.threshold}
135	                  </Text>
136	                </View>
137	                <StatusPill label={label} tone={tone} />
138	              </View>
139	              <View style={{ height: spacing.md }} />
140	              {done ? (
141	                <StatusPill label={t('reorderSent')} tone="success" Icon={Check} />
142	              ) : (
143	                <Button
144	                  label={t('requestReorder')}
145	                  variant="tonal"
146	                  size="md"
147	                  onPress={() => reorder(item)}
148	                />
149	              )}
150	            </Card>
151	          );
152	        }}
153	        ListEmptyComponent={
154	          <View style={styles.empty}>
155	            <Text variant="headlineSmall" style={{ textAlign: 'center' }}>
156	              All stocked up
157	            </Text>
158	            <Text
159	              variant="bodyLarge"
160	              color={palette.onSurfaceVariant}
161	              style={{ textAlign: 'center', marginTop: spacing.sm }}
162	            >
163	              Nothing is below its threshold right now.
164	            </Text>
165	          </View>
166	        }
167	      />
168	      )}
169	    </View>
170	  );
171	}
172	
173	const styles = StyleSheet.create({
174	  safe: { flex: 1 },
175	  list: { padding: spacing.xl, paddingBottom: spacing.xxxl },
176	  head: { flexDirection: 'row', alignItems: 'flex-start', gap: spacing.md },
177	  empty: { padding: spacing.xxl },
178	});

