/** Remove a single alias by its primary key. Used by the dashboard's
 *  per-product alias expander when an admin wants to drop a poisoned
 *  or wrong mapping without nuking every alias on the site. */
export async function deleteProductAlias(aliasId: string): Promise<{ deleted: boolean }> {
  const db = await getDb();
  const result = await db.execute({
    sql: `DELETE FROM product_aliases WHERE id = ?`,
    args: [aliasId],
  });
  return { deleted: (result.rowsAffected ?? 0) > 0 };
}

