  method === "GET"
) {
  const auth = await authenticate(req, res);
  if (!auth) return true;
  const productId = pathname
    .replace("/api/inventory/canonical-products/", "")
    .replace("/aliases", "");
  if (!productId) {
    json(res, 400, { error: "missing product id" });
    return true;
