  json(res, 200, { aliases: await listProductAliases(productId) });
  return true;
}

// Delete a single alias by id.
//   DELETE /api/inventory/aliases/:id
if (pathname.startsWith("/api/inventory/aliases/") && method === "DELETE") {
  const auth = await authenticate(req, res);
  if (!auth) return true;
  if (!auth.adminEmail) {
    json(res, 403, { error: "Admin only" });
    return true;
  }
  const aliasId = pathname.replace("/api/inventory/aliases/", "");
  if (!aliasId) {
    json(res, 400, { error: "missing alias id" });
    return true;
  }
  const result = await deleteProductAlias(aliasId);
  json(res, 200, result);
  return true;
}

