// Seed list of common inventory categories. Admin can still type a
// custom one — these are just suggestions to keep naming consistent
// across products and across vendors.
const CATEGORY_SEED = [
  "Beverages",
  "Snacks",
  "Bakery",
  "Dairy",
  "Frozen",
  "Pantry / Grocery",
  "Fruits & Vegetables",
