/**
 * Text-backed numeric input — fixes three classes of pain with the
 * built-in <input type="number">:
 *   1. Admin couldn't fully clear the field (auto-coerce-to-0/1 fought
 *      the empty state). Now you can type, backspace to blank, paste
 *      freely; we only normalise on blur.
 *   2. Scroll-wheel-changes-the-value. People scrolling the page would
 *      silently change qty/rate. We use type="text" so the wheel
 *      doesn't touch it; inputMode="decimal" still gets the right
 *      mobile keyboard.
 *   3. Spinner arrows (the up/down stepper) — gone for the same reason.
 *
 * On blur, an empty value falls back to 0 per spec.
 */
function NumericInput({
  value,
  onChange,
  onBlur,
  fallback = 0,
  style,
  ...rest
}: {
  value: number;
  onChange: (v: number) => void;
  onBlur?: () => void;
  fallback?: number;
  style?: React.CSSProperties;
} & Omit<React.InputHTMLAttributes<HTMLInputElement>, "value" | "onChange" | "onBlur" | "style" | "type">) {
  const [text, setText] = useState<string>(String(value ?? fallback));

  // Re-sync the local buffer when the parent's value changes from
  // outside (e.g. a catalog suggestion auto-fills the row).
  useEffect(() => {
    const expected = String(value ?? fallback);
    setText((cur) => (Number(cur) === Number(expected) ? cur : expected));
  }, [value, fallback]);

  return (
    <input
      type="text"
      inputMode="decimal"
      autoComplete="off"
      value={text}
      onChange={(e) => {
        const raw = e.target.value;
        if (raw === "" || /^-?\d*\.?\d*$/.test(raw)) {
          setText(raw);
          // Intermediate states like "" / "-" / "." aren't pushed up.
          if (raw !== "" && raw !== "-" && raw !== ".") {
            const n = Number(raw);
            if (Number.isFinite(n)) onChange(n);
          }
        }
      }}
      onBlur={() => {
        if (text === "" || text === "-" || text === ".") {
          setText(String(fallback));
          onChange(fallback);
        }
        onBlur?.();
      }}
      style={style}
      {...rest}
    />
  );
}

/**
 * Category combobox — typed input with a dropdown of category
 * suggestions. Seeds from CATEGORY_SEED plus every distinct category
 * already used in the catalog, so admin-added customs become part of
 * the suggestion pool naturally.
 */
function CategoryCombobox({
  value,
  catalog,
  onChange,
  style,
}: {
  value: string;
  catalog: CanonicalProduct[];
  onChange: (v: string) => void;
  style?: React.CSSProperties;
}) {
  const [open, setOpen] = useState(false);
  const [activeIdx, setActiveIdx] = useState(0);
  const wrapRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    function onDocClick(e: MouseEvent) {
      if (!wrapRef.current) return;
      if (!wrapRef.current.contains(e.target as Node)) setOpen(false);
    }
    document.addEventListener("mousedown", onDocClick);
    return () => document.removeEventListener("mousedown", onDocClick);
  }, []);

