const UNIT_OPTIONS = ["pcs", "kg", "g", "l", "ml", "pack"];

// Seed list of common inventory categories. Admin can still type a
// custom one — these are just suggestions to keep naming consistent
// across products and across vendors.
const CATEGORY_SEED = [
  "Beverages",
  "Snacks",
  "Bakery",
  "Dairy",
  "Frozen",
  "Pantry / Grocery",
  "Fruits & Vegetables",
  "Cleaning",
  "Personal Care",
  "Cafeteria",
  "Office",
  "Stationery",
  "Other",
];

/**
 * Text-backed numeric input — fixes three classes of pain with the
 * built-in <input type="number">:
 *   1. Admin couldn't fully clear the field (auto-coerce-to-0/1 fought
 *      the empty state). Now you can type, backspace to blank, paste
 *      freely; we only normalise on blur.
 *   2. Scroll-wheel-changes-the-value. People scrolling the page would
 *      silently change qty/rate. We use type="text" so the wheel
 *      doesn't touch it; inputMode="decimal" still gets the right
 *      mobile keyboard.
 *   3. Spinner arrows (the up/down stepper) — gone for the same reason.
 *
 * On blur, an empty value falls back to 0 per spec.
 */
function NumericInput({
  value,
  onChange,
  onBlur,
  fallback = 0,
  style,
  ...rest
}: {
  value: number;
  onChange: (v: number) => void;
  onBlur?: () => void;
  fallback?: number;
  style?: React.CSSProperties;
} & Omit<React.InputHTMLAttributes<HTMLInputElement>, "value" | "onChange" | "onBlur" | "style" | "type">) {
  const [text, setText] = useState<string>(String(value ?? fallback));

  // Re-sync the local buffer when the parent's value changes from
  // outside (e.g. a catalog suggestion auto-fills the row).
  useEffect(() => {
    const expected = String(value ?? fallback);
    setText((cur) => (Number(cur) === Number(expected) ? cur : expected));
  }, [value, fallback]);

  return (
    <input
      type="text"
      inputMode="decimal"
      autoComplete="off"
      value={text}
      onChange={(e) => {
        const raw = e.target.value;
        if (raw === "" || /^-?\d*\.?\d*$/.test(raw)) {
          setText(raw);
          // Intermediate states like "" / "-" / "." aren't pushed up.
          if (raw !== "" && raw !== "-" && raw !== ".") {
            const n = Number(raw);
            if (Number.isFinite(n)) onChange(n);
          }
        }
      }}
      onBlur={() => {
        if (text === "" || text === "-" || text === ".") {
          setText(String(fallback));
          onChange(fallback);
        }
        onBlur?.();
      }}
      style={style}
      {...rest}
    />
  );
}

/**
 * Category combobox — typed input with a dropdown of category
 * suggestions. Seeds from CATEGORY_SEED plus every distinct category
 * already used in the catalog, so admin-added customs become part of
 * the suggestion pool naturally.
 */
function CategoryCombobox({
  value,
  catalog,
  onChange,
  style,
}: {
  value: string;
  catalog: CanonicalProduct[];
  onChange: (v: string) => void;
  style?: React.CSSProperties;
}) {
  const [open, setOpen] = useState(false);
  const [activeIdx, setActiveIdx] = useState(0);
  const wrapRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    function onDocClick(e: MouseEvent) {
      if (!wrapRef.current) return;
      if (!wrapRef.current.contains(e.target as Node)) setOpen(false);
    }
    document.addEventListener("mousedown", onDocClick);
    return () => document.removeEventListener("mousedown", onDocClick);
  }, []);

  const options = useMemo(() => {
    const used = new Set<string>();
    for (const p of catalog) {
      const c = (p.category ?? "").trim();
      if (c) used.add(c);
    }
    // Union: seed list + any custom categories already in the catalog.
    const merged = [...new Set([...CATEGORY_SEED, ...Array.from(used)])];
    const q = value.trim().toLowerCase();
    if (!q) return merged.sort((a, b) => a.localeCompare(b));
    return merged
      .filter((c) => c.toLowerCase().includes(q))
      .sort((a, b) => {
        const al = a.toLowerCase();
        const bl = b.toLowerCase();
        const aStarts = al.startsWith(q) ? 0 : 1;
        const bStarts = bl.startsWith(q) ? 0 : 1;
        if (aStarts !== bStarts) return aStarts - bStarts;
        return a.localeCompare(b);
      });
  }, [catalog, value]);

  function commit(c: string) {
    onChange(c);
    setOpen(false);
    setActiveIdx(0);
  }

  return (
    <div ref={wrapRef} style={{ position: "relative" }}>
      <input
        type="text"
        value={value}
        onChange={(e) => { onChange(e.target.value); setOpen(true); setActiveIdx(0); }}
        onFocus={() => setOpen(true)}
        onKeyDown={(e) => {
          if (e.key === "ArrowDown") { e.preventDefault(); setOpen(true); setActiveIdx((i) => Math.min(options.length - 1, i + 1)); }
          else if (e.key === "ArrowUp") { e.preventDefault(); setActiveIdx((i) => Math.max(0, i - 1)); }
          else if (e.key === "Enter" && open && options[activeIdx]) { e.preventDefault(); commit(options[activeIdx]); }
          else if (e.key === "Escape") { setOpen(false); }
        }}
        placeholder="Type or pick a category…"
        autoComplete="off"
        style={style ?? input}
      />
      {open && options.length > 0 && (
        <div
          style={{
            position: "absolute",
            top: "calc(100% + 2px)",
            left: 0,
            right: 0,
            zIndex: 30,
            maxHeight: 200,
            overflowY: "auto",
            background: "var(--surface, #fff)",
            border: "1px solid var(--line)",
            borderRadius: 6,
            boxShadow: "0 6px 18px rgba(0,0,0,0.08)",
          }}
        >
          {options.map((c, i) => (
            <div
              key={c}
              onMouseDown={(e) => { e.preventDefault(); commit(c); }}
              onMouseEnter={() => setActiveIdx(i)}
              style={{
                padding: "5px 10px",
                cursor: "pointer",
                background: i === activeIdx ? "var(--line)" : "transparent",
                fontSize: 12,
              }}
            >
              {c}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

