1	import { ChevronLeft, ChevronRight } from 'lucide-react-native';
2	import React, { useMemo, useState } from 'react';
3	import { Modal, Pressable, StyleSheet, View } from 'react-native';
4	import { Button, radius, spacing, Text } from '../../../design';
5	import { haptic } from '../../../utils/haptics';
6	import { useTheme } from '../../../theme';
7	import { useT } from '../../../i18n';
8	
9	const MONTH_NAMES = [
10	  'January', 'February', 'March', 'April', 'May', 'June',
11	  'July', 'August', 'September', 'October', 'November', 'December',
12	];
13	const DAY_NAMES = ['Su', 'Mo', 'Tu', 'We', 'Th', 'Fr', 'Sa'];
14	
15	type Props = {
16	  visible: boolean;
17	  value: Date | null;
18	  minimumDate?: Date;
19	  onSelect: (date: Date) => void;
20	  onDismiss: () => void;
21	};
22	
23	/**
24	 * Pure-JS calendar date picker modal. No native module required.
25	 * Material 3 styled with month navigation and day grid.
26	 */
27	export function DatePickerModal({ visible, value, minimumDate, onSelect, onDismiss }: Props) {
28	  const { palette } = useTheme();
29	  const t = useT();
30	  const today = new Date();
31	  const [viewYear, setViewYear] = useState(value?.getFullYear() ?? today.getFullYear());
32	  const [viewMonth, setViewMonth] = useState(value?.getMonth() ?? today.getMonth());
33	  const [selected, setSelected] = useState<Date | null>(value);
34	
35	  // Reset view when modal opens with new value
36	  React.useEffect(() => {
37	    if (visible) {
38	      const d = value ?? today;
39	      setViewYear(d.getFullYear());
40	      setViewMonth(d.getMonth());
41	      setSelected(value);
42	    }
43	    // eslint-disable-next-line react-hooks/exhaustive-deps
44	  }, [visible]);
45	
46	  const days = useMemo(() => {
47	    const firstDay = new Date(viewYear, viewMonth, 1).getDay();
48	    const daysInMonth = new Date(viewYear, viewMonth + 1, 0).getDate();
49	    const grid: (number | null)[] = [];
50	    for (let i = 0; i < firstDay; i++) grid.push(null);
51	    for (let d = 1; d <= daysInMonth; d++) grid.push(d);
52	    return grid;
53	  }, [viewYear, viewMonth]);
54	
55	  const goBack = () => {
56	    if (viewMonth === 0) {
57	      setViewMonth(11);
58	      setViewYear(viewYear - 1);
59	    } else {
60	      setViewMonth(viewMonth - 1);
61	    }
62	  };
63	
64	  const goForward = () => {
65	    if (viewMonth === 11) {
66	      setViewMonth(0);
67	      setViewYear(viewYear + 1);
68	    } else {
69	      setViewMonth(viewMonth + 1);
70	    }
71	  };
72	
73	  const isDisabled = (day: number) => {
74	    if (!minimumDate) return false;
75	    const d = new Date(viewYear, viewMonth, day);
76	    const min = new Date(minimumDate.getFullYear(), minimumDate.getMonth(), minimumDate.getDate());
77	    return d < min;
78	  };
79	
80	  const isSelected = (day: number) => {
81	    if (!selected) return false;
82	    return (
83	      selected.getFullYear() === viewYear &&
84	      selected.getMonth() === viewMonth &&
85	      selected.getDate() === day
86	    );
87	  };
88	
89	  const isToday = (day: number) => {
90	    return (
91	      today.getFullYear() === viewYear &&
92	      today.getMonth() === viewMonth &&
93	      today.getDate() === day
94	    );
95	  };
96	
97	  const handleDayPress = (day: number) => {
98	    if (isDisabled(day)) return;
99	    haptic.tap();
100	    setSelected(new Date(viewYear, viewMonth, day));
101	  };
102	
103	  const handleConfirm = () => {
104	    if (selected) {
105	      onSelect(selected);
106	    }
107	    onDismiss();
108	  };
109	
110	  const CELL = 40;
111	
112	  return (
113	    <Modal visible={visible} transparent animationType="fade" onRequestClose={onDismiss}>
114	      <Pressable style={styles.backdrop} onPress={onDismiss}>
115	        <Pressable onPress={(e) => e.stopPropagation()} style={[styles.card, { backgroundColor: palette.surface }]}>
116	          {/* Month/Year header */}
117	          <View style={styles.header}>
118	            <Pressable onPress={goBack} hitSlop={12} style={styles.navBtn}>
119	              <ChevronLeft size={24} color={palette.onSurface} />
120	            </Pressable>
121	            <Text variant="titleMedium">
122	              {MONTH_NAMES[viewMonth]} {viewYear}
123	            </Text>
124	            <Pressable onPress={goForward} hitSlop={12} style={styles.navBtn}>
125	              <ChevronRight size={24} color={palette.onSurface} />
126	            </Pressable>
127	          </View>
128	
129	          {/* Day-of-week labels */}
130	          <View style={styles.weekRow}>
131	            {DAY_NAMES.map((d) => (
132	              <View key={d} style={[styles.cell, { width: CELL, height: 28 }]}>
133	                <Text variant="labelMedium" color={palette.onSurfaceVariant}>
134	                  {d}
135	                </Text>
136	              </View>
137	            ))}
138	          </View>
139	
140	          {/* Day grid */}
141	          <View style={styles.grid}>
142	            {days.map((day, idx) => {
143	              if (day === null) {
144	                return <View key={`e-${idx}`} style={{ width: CELL, height: CELL }} />;
145	              }
146	              const disabled = isDisabled(day);
147	              const sel = isSelected(day);
148	              const tod = isToday(day);
149	              return (
150	                <Pressable
151	                  key={day}
152	                  disabled={disabled}
153	                  onPress={() => handleDayPress(day)}
154	                  style={[
155	                    styles.cell,
156	                    {
157	                      width: CELL,
158	                      height: CELL,
159	                      borderRadius: CELL / 2,
160	                      backgroundColor: sel ? palette.primary : 'transparent',
161	                    },
162	                    tod && !sel && { borderWidth: 1, borderColor: palette.primary },
163	                  ]}
164	                >
165	                  <Text
166	                    variant="bodyLarge"
167	                    color={
168	                      disabled
169	                        ? palette.outlineVariant
170	                        : sel
171	                        ? palette.onPrimary
172	                        : palette.onSurface
173	                    }
174	                  >
175	                    {day}
176	                  </Text>
177	                </Pressable>
178	              );
179	            })}
180	          </View>
181	
182	          {/* Actions */}
183	          <View style={styles.actions}>
184	            <Button label={t('cancel')} variant="text" onPress={onDismiss} size="md" />
185	            <Button
186	              label={t('select')}
187	              onPress={handleConfirm}
188	              size="md"
189	              disabled={!selected}
190	            />
191	          </View>
192	        </Pressable>
193	      </Pressable>
194	    </Modal>
195	  );
196	}
197	
198	const styles = StyleSheet.create({
199	  backdrop: {
200	    flex: 1,
201	    backgroundColor: 'rgba(0,0,0,0.45)',
202	    justifyContent: 'center',
203	    alignItems: 'center',
204	  },
205	  card: {
206	    width: '90%',
207	    maxWidth: 360,
208	    borderRadius: radius.lg,
209	    padding: spacing.lg,
210	    elevation: 8,
211	    shadowColor: '#000',
212	    shadowOffset: { width: 0, height: 4 },
213	    shadowOpacity: 0.2,
214	    shadowRadius: 12,
215	  },
216	  header: {
217	    flexDirection: 'row',
218	    alignItems: 'center',
219	    justifyContent: 'space-between',
220	    marginBottom: spacing.md,
221	  },
222	  navBtn: {
223	    width: 40,
224	    height: 40,
225	    borderRadius: 20,
226	    alignItems: 'center',
227	    justifyContent: 'center',
228	  },
229	  weekRow: {
