          >
            <X size={20} color={palette.onSurfaceVariant} strokeWidth={2.2} />
          </Pressable>
        )}
      </View>
      {(error || helper) && (
        <Text
          variant="labelMedium"
          color={error ? palette.error : palette.onSurfaceVariant}
          style={{ marginTop: spacing.xs }}
        >
          {error ?? helper}
        </Text>
      )}
    </View>
  );
}

