              {q.label}
            </Text>
          </Pressable>
        ))}
      </View>
    </>
  )}

  {!noExpiry && perPackExpiry && (
    <View style={{ marginTop: spacing.sm, gap: spacing.xs }}>
      {perPackExpiries.map((d, i) => (
        <Pressable
          key={i}
          onPress={() => { setEditingPackIdx(i); setShowPicker(true); }}
          style={[
            styles.expiryInput,
            {
